	<row1 cat="sql">
		<a1>Task1</a1>
		<a2>
			<l0>select null as voucher_date,</l0>
			<l1>a.branchname,</l1>
			<l2>''Opening Balance'' as vouchertype, </l2>
			<l3>0 as recordid, </l3>
			<l4>0 as accountshdrid, </l4>
			<l5>null as transid, </l5>
			<l6>null as axrowoptions, </l6>
			<l7>a.accountname,</l7>
			<l8>a.subledgername, </l8>
			<l9>null as voucher_number, null as docid,</l9>
			<l10>case when (sum(a.base_debit) - sum(a.base_credit)) &gt; 0 then sum(a.base_debit) - sum(a.base_credit) else 0 end as base_debit , </l10>
			<l11>case when (sum(a.base_debit) - sum(a.base_credit)) &lt; 0 then abs(sum(a.base_debit) - sum(a.base_credit)) else 0 end as base_credit, </l11>
			<l12>null AS details,</l12>
			<l13>null as reconciled</l13>
			<l14>from mv_accountsdetails a</l14>
			<l15>where a.voucher_date &lt; cast( :fromdate as date)</l15>
			<l16>and (a.branchname = cast( :pbranchname as text) or </l16>
			<l17>               ( cast( :pbranchname as text)= ''ALL'' and ( cast( :pbranchlist as text) like ''%''||a.branchname||''%''  or :pbranchlist = ''ALL'')) )   </l17>
			<l18>and a.company = cast( :pcompanyid as numeric)  </l18>
			<l19>and a.accountname = :mpaccountname </l19>
			<l20>and ((( a.reconciled  = ''T'' and upper( :preconciled) =''ONLY RECONCILED'') or ( a.reconciled  = ''F'' and upper( :preconciled) =''ONLY UNRECONCILED'')) or upper( :preconciled) =''BOTH'') </l20>
			<l21>group by a.branchname,a.accountname,a.subledgername</l21>
			<l22>UNION</l22>
			<l23>select a.voucher_date,</l23>
			<l24>a.branchname,</l24>
			<l25>a.vouchertype, </l25>
			<l26>case when a.sourceid = 0 then a.accountshdrid else a.sourceid end as recordid, </l26>
			<l27>a.accountshdrid, </l27>
			<l28>''t''||a.transid as transid, </l28>
			<l29>''treconcile,Reconcile,Script,thumbs_up_down~teditstatu,Edit Recon. Status,Script,edit_location_alt~treceipt,Receipt,Script,calendar_month~tpayment,Payment,Script,calendar_today~tcustrecei,Customer Receipt,Script,attach_money~tsupppayme,Supplier Payment,Script,collections_bookmark</l29>
			<l30>~tbulkrecon,Reconcile all Marked,Script,supervised_user_circle</l30>
			<l31>~tbankrec,Bank Recon. Report,Script,comment_bank'' </l31>
			<l32>as axrowoptions, </l32>
			<l33>a.accountname,</l33>
			<l34>a.subledgername, </l34>
			<l35>func_returns_hyperlink( a.voucher_number,''formpage'',a.transid,(case when a.sourceid = 0 then a.accountshdrid else a.sourceid end),</l35>
			<l36>                      (select t.caption from tstructs t where t.name = a.transid)) as voucher_number,a.voucher_number as docid,</l36>
			<l37>a.base_debit, </l37>
			<l38>a.base_credit, </l38>
			<l39>''&lt;span style="font-weight:bold;"&gt;Branch &lt;/span&gt;'' || a.branchname || ''&lt;br/&gt;'' ||</l39>
			<l40>CASE </l40>
			<l41>    WHEN (a.reference_number IS NOT NULL OR a.reference_date IS NOT NULL) THEN </l41>
			<l42>        ''&lt;span style="font-weight:bold;"&gt;Ref#/Date &lt;/span&gt;'' || a.reference_number || ''-'' || to_char(a.reference_date, ''dd/mm/yyyy'') || ''&lt;br/&gt;'' ELSE ''''  END ||</l42>
			<l43>CASE </l43>
			<l44>    WHEN (a.cheque_number IS NOT NULL OR a.cheque_date IS NOT NULL) THEN </l44>
			<l45>        ''&lt;span style="font-weight:bold;"&gt;Chq#/Date &lt;/span&gt;'' || a.cheque_number || ''-'' || to_char(a.cheque_date, ''dd/mm/yyyy'') || ''&lt;br/&gt;'' ELSE ''''  END ||</l45>
			<l46>CASE </l46>
			<l47>    WHEN a.reconciled_date IS NOT NULL THEN </l47>
			<l48>        ''&lt;span style="font-weight:bold;"&gt;Reconciled Date &lt;/span&gt;'' || a.reconciled_date || ''&lt;br/&gt;'' ELSE ''''  END ||</l48>
			<l49>CASE </l49>
			<l50>    WHEN a.narration IS NOT NULL THEN </l50>
			<l51>        ''&lt;span style="font-style:italic;"&gt;'' || a.narration || ''&lt;/span&gt;&lt;br/&gt;'' </l51>
			<l52>    ELSE '''' </l52>
			<l53>END AS details,</l53>
			<l54>case when upper(a.reconciled) = ''T'' then ''&lt;span class="material-icons material-icons-style" style="color:#2b4da1"&gt;check_box&lt;/span&gt;'' else </l54>
			<l55>''&lt;span class="material-icons material-icons-style" style="color:#2b4da1"&gt;check_box_outline_blank&lt;/span&gt;'' end as reconciled</l55>
			<l56>from mv_accountsdetails a</l56>
			<l57>where a.voucher_date between cast( :fromdate as date) and cast( :asondate as date)</l57>
			<l58>and (a.branchname = cast( :pbranchname as text) or </l58>
			<l59>               ( cast( :pbranchname as text)= ''ALL'' and ( cast( :pbranchlist as text) like ''%''||a.branchname||''%''  or :pbranchlist = ''ALL'')) )   </l59>
			<l60>and a.company = cast( :pcompanyid as numeric)  </l60>
			<l61>and a.accountname = :mpaccountname </l61>
			<l62>and ((( a.reconciled  = ''T'' and upper( :preconciled) =''ONLY RECONCILED'') or ( a.reconciled  = ''F'' and upper( :preconciled) =''ONLY UNRECONCILED'')) or upper( :preconciled) =''BOTH'')  </l62>
			<l63>order by accountname,voucher_date</l63>
		</a2>
		<a3></a3>
		<a4>reportsql</a4>
	</row1>
