		<x__head caption="Item Wise Sales" cat="txt" parent="pnlButton" color="$00F2F0F0" align="none" def="left" tlhw="7,5,19,53" font="_Tahoma,,,clWindowText" type="pnl"/>
	</comps>
	<row1 cat="sql">
		<a1>Task1</a1>
		<a2>
			<l0>select a.categoryname, a.productcategory, a.brand_name, a.itemdesc, sum(a.qty) as invoice_qty, sum(a.gross_amount) as gross_amount, sum(a.discount) as discount,</l0>
			<l1>sum(a.taxableamount) as taxableamount, sum(a.net_amount) as net_amount,''tmonthly,Monthly Sales,Script,calendar_today~tdaily,Daily Sales,Script,attach_money~tcustomer,Customer wise Sales,Script,calendar_month~tbranch,Branch wise Sales,Script,thumbs_up_down~tchannel,Channel wise Sales,Script,edit_location_alt~tyearly,Annual Sales,Script,collections_bookmark'' </l1>
			<l2>as axrowoptions,''Branch wise'' as branchwise,''Channel wise'' as channelwise,''Customer wise'' as customerwise,''Monthly Sales'' as monthlysales,''Daily Sales'' as dailysales,</l2>
			<l3>''Yearly Sales'' as yearlysales</l3>
			<l4>from vw_sales_items a</l4>
			<l5>where a.company = cast( :pcompanyid as numeric)</l5>
			<l6>and (a.branchname = :pbranchname or :pbranchname = ''ALL'')</l6>
			<l7>and (a.itemdesc = :pitem or :pitem = ''ALL'')</l7>
			<l8>and a.docdate between cast( :pfromdate as date) AND cast( :ptodate as date)</l8>
			<l9>group by a.categoryname, a.productcategory, a.brand_name, a.itemdesc</l9>
			<l10>having sum(a.qty) &gt; 0</l10>
			<l11>order by 1,2,4</l11>
		</a2>
		<a3></a3>
		<a4>reportsql</a4>
	</row1>
