('itmsumm', 'Sales Summary', '<root pform="yes" name="itmsumm" caption="Sales Summary" updatedon="20/05/2026 11:26:22" updatedby="tamilselvan" updusername="" dbtype="postgre" importedon="10/03/2025 19:04:23" importedby="admin" createdon="20/05/2026 11:26:22 AM" createdby="tamilselvan"><iview cat="iview" hideprojname="" hidereportdate="" parrange="1"><a0>itmsumm</a0><a2>Sales Summary</a2><a3 ptable=""></a3><a4>0</a4><a5>true</a5><a6></a6><a7></a7><a8>0</a8><a9></a9><a10>false</a10><a11>true</a11><a12></a12><a13></a13><a14></a14><a15></a15><a16></a16><a17>Enabled</a17><a18>false</a18><a19>false</a19><a51></a51><a52></a52><a53></a53><a54></a54><a55>select row</a55><a57>false</a57><a63>true</a63><a64>false</a64><b9>Sales Summary</b9><b10></b10><b11></b11><b12></b12><b13></b13><b14></b14><b15></b15><b16></b16><b17></b17><b35>false</b35><b36>Center</b36><b37>Center</b37><a31></a31><a32>1</a32><a33>false</a33><a34>false</a34><a35>0</a35><a36></a36><a37></a37><a38></a38><a39>false</a39><a40>false</a40><a21>false</a21><a41>false</a41><a42>clskyblue</a42><a43>[Tahoma,9,clBlack,,True,False,False,False]</a43><a44>[Tahoma,8,clBlack,,True,False,False,False]</a44><a45>[Tahoma,8,clBlack,,True,False,False,False]</a45><a46>$00F3AFA0</a46><a47>[Tahoma,8,clBlack,,True,False,False,False]</a47><a48>$00EEF1F2</a48><a49>$00E2E8E9</a49><a50>18</a50><a60>1</a60><b18></b18><b21></b21><b23></b23><b22>0</b22><b38>Classic</b38><b39>None</b39><a65>false</a65><a66>false</a66></iview><scripts cat="actions"><openiview script="true" cap="Open Iview" type="iview" apply="Current Row " applyon="" sname="itmsumm" desc="" failmessage="" validate="no" web="no" breakonerror="no" localnum="14"><r1 id="a1" op="5" task="scripts" type="" sname="" apply="" applyon=""><param1 task="scripts" op="7"><exprset><l0>if preportby = {Branch wise}</l0><l1>  LoadIView({saldtrp},{pbranch=:itemdesc~pitemname=:pitemname~pfromdate=:pfromdate~ptodate=:ptodate},{d},{true})g)</l1><l2>elseif preportby = {Channel wise}</l2><l3>  LoadIView({saldtrp},{pchannel=:itemdesc~pitemname=:pitemname~pfromdate=:pfromdate~ptodate=:ptodate},{d},{true})g)</l3><l4>elseif preportby = {Customer wise}</l4><l5>  LoadIView({saldtrp},{pcustomer=:itemdesc~pitemname=:pitemname~pfromdate=:pfromdate~ptodate=:ptodate},{d},{true})g)</l5><l6>elseif preportby = {Monthly Sales}</l6><l7>  LoadIView({saldtrp},{pitemname=:pitemname~pfromdate=:pfromdate~ptodate=:ptodate},{d},{true})g)</l7><l8>elseif preportby = {Daily Sales}</l8><l9>  LoadIView({saldtrp},{pitemname=:pitemname~pfromdate=:pfromdate~ptodate=:ptodate},{d},{true})g)</l9><l10>elseif preportby = {Yearly Sales}</l10><l11>  LoadIView({saldtrp},{pitemname=:pitemname~pfromdate=:pfromdate~ptodate=:ptodate},{d},{true})g)</l11><l12>end if</l12></exprset></param1></r1></openiview></scripts><comps cat="comps" dwbtb="true" LocalNum="9" btn="6" vupd="" pnlheight="35"><btn1 key="btn1" caption="Print" cat="btn" tlhw="7,1,20,20" parent="btnPanel" font="Tahoma,8,clWindowText,ffff" def="right" task="print" action="" container="" sname="" flat="true" position="Left" visible="true" footer="false" hint="Print" down=""><icon><text>list</text><addClass>material-icons</addClass></icon></btn1><btn2 key="btn2" caption="Preview" cat="btn" tlhw="7,1,20,20" parent="btnPanel" font="Tahoma,8,clWindowText,ffff" def="right" task="preview" action="" container="" sname="" flat="true" position="Left" visible="true" footer="false" hint="Preview" down=""><icon><text>video_label</text><addClass>material-icons</addClass></icon></btn2><btn3 key="btn3" caption="Page Setup / Printer Setting" cat="btn" tlhw="7,1,20,20" parent="btnPanel" font="Tahoma,8,clWindowText,ffff" def="right" task="printersetting" action="" container="" sname="" flat="true" position="Left" visible="true" footer="false" hint="Page Setup / Printer Setting" down=""><icon><text>import_contacts</text><addClass>material-icons</addClass></icon></btn3><btn4 key="btn4" caption="View" cat="btn" tlhw="7,1,20,20" parent="btnPanel" font="Tahoma,8,clWindowText,ffff" def="right" task="view" action="" container="" sname="" flat="true" position="Left" visible="true" footer="false" hint="View" down=""><icon><text>remove_red_eye</text><addClass>material-icons</addClass></icon></btn4><btn5 key="btn5" caption="Find" cat="btn" tlhw="7,1,20,20" parent="btnPanel" font="Tahoma,8,clWindowText,ffff" def="right" task="find" action="" container="" sname="" flat="true" position="Left" visible="true" footer="false" hint="Find" down=""><icon><text>search</text><addClass>material-icons</addClass></icon></btn5><btn6 key="btn6" caption="Tasks" cat="btn" tlhw="7,1,20,20" parent="btnPanel" font="Tahoma,8,clWindowText,ffff" def="right" task="tasks" action="" container="" sname="" flat="true" position="Left" visible="true" footer="false" hint="Tasks" down="" folder="true"><icon><text>receipt</text><addClass>material-icons</addClass></icon></btn6><x__head caption="Sales Summary" cat="txt" parent="pnlButton" color="$00F2F0F0" align="none" def="left" tlhw="7,5,19,53" font="_Tahoma,,,clWindowText" type="pnl"/></comps><row1 cat="sql"><a1>Task1</a1><a2><l0>select a.categoryname, a.productcategory, a.brand_name, a.itemdesc, sum(a.invoice_qty) as invoice_qty, sum(a.gross_amount) as gross_amount, sum(a.discount) as discount,</l0><l1>sum(a.taxableamount) as taxableamount, sum(a.net_amount) as net_amount</l1><l2>from</l2><l3>(SELECT </l3><l4>    a.categoryname, </l4><l5>    a.productcategory, </l5><l6>    a.brand_name, </l6><l7>    SUM(a.qty) AS invoice_qty, </l7><l8>    SUM(a.gross_amount) AS gross_amount, </l8><l9>    SUM(a.discount) AS discount,</l9><l10>    SUM(a.taxableamount) AS taxableamount, </l10><l11>    SUM(a.net_amount) AS net_amount,</l11><l12>    CASE </l12><l13>        WHEN :preportby = ''Channel wise'' THEN a.channel</l13><l14>        WHEN :preportby = ''Customer wise'' THEN a.party_name</l14><l15>        WHEN :preportby = ''Branch wise'' THEN a.branchname</l15><l16>        WHEN :preportby = ''Monthly Sales'' THEN </l16><l17>            CAST(CURRENT_DATE - INTERVAL ''30 DAY'' AS VARCHAR) || '' to '' || CAST(CURRENT_DATE AS VARCHAR)</l17><l18>        WHEN :preportby = ''Daily Sales'' THEN </l18><l19>            CAST(CURRENT_DATE AS VARCHAR) || '' to '' || CAST(CURRENT_DATE AS VARCHAR)</l19><l20>        WHEN :preportby = ''Yearly Sales'' THEN </l20><l21>            CAST(CURRENT_DATE - INTERVAL ''365 DAY'' AS VARCHAR) || '' to '' || CAST(CURRENT_DATE AS VARCHAR)</l21><l22>    END AS itemdesc </l22><l23>FROM </l23><l24>    vw_sales_items a</l24><l25>WHERE  a.company = cast( :pcompanyid as numeric)</l25><l26>and a.itemdesc = :pitemname</l26><l27>AND a.docdate BETWEEN </l27><l28>            (CASE </l28><l29>                WHEN :preportby = ''Monthly Sales'' THEN CURRENT_DATE - INTERVAL ''30 DAY''</l29><l30>                WHEN :preportby = ''Daily Sales'' THEN CURRENT_DATE</l30><l31>                WHEN :preportby = ''Yearly Sales'' THEN CURRENT_DATE - INTERVAL ''365 DAY''</l31><l32>                ELSE cast( :pfromdate as date) end) AND cast( :ptodate as date)</l32><l33>GROUP BY </l33><l34>    a.categoryname, </l34><l35>    a.productcategory, </l35><l36>    a.brand_name, </l36><l37>    a.channel,  </l37><l38>    a.party_name, </l38><l39>    a.branchname)a</l39><l40>group by a.categoryname, a.productcategory, a.brand_name, a.itemdesc</l40><l41>HAVING </l41><l42>    SUM(a.invoice_qty) &gt; 0</l42></a2><a3></a3><a4>reportsql</a4></row1><pcompanyid cat="params" ord="1"><a1>Task1</a1><a0>pcompanyid</a0><a2>Company</a2><a4>Numeric</a4><a9>false</a9><a6 sugg="false">m_companyid</a6><a10></a10><a21>true</a21><a11></a11><a5>0</a5><a12>true</a12><a14>false</a14><a56></a56><a13>Accept</a13><a15><s>pitemname</s></a15><a67>325</a67><a68>false</a68></pcompanyid><pitemname cat="params" ord="2"><a1>Task1</a1><a0>pitemname</a0><a2>Item Name</a2><a4>Character</a4><a9>false</a9><a6 sugg="false"></a6><a10></a10><a21>false</a21><a11 pcount="1">select a.itemdesc from item a
where a.company = :pcompanyid 
and a.cancel = ''F'' 
and a.app_desc = 1
and a.active = ''T'' 
order by 1 </a11><a5>0</a5><a12>true</a12><a14>false</a14><a56></a56><a13>Select</a13><a15></a15><a67>325</a67><a68>false</a68></pitemname><preportby cat="params" ord="3"><a1>Task1</a1><a0>preportby</a0><a2>Reported By</a2><a4>Character</a4><a9>false</a9><a6 sugg="false"></a6><a10></a10><a21>false</a21><a11>select ''Channel wise'' as option from dual 
UNION
select ''Customer wise'' as option from dual 
UNION
select ''Branch wise'' as option from dual 
UNION
select ''Monthly Sales'' as option from dual 
UNION
select ''Daily Sales'' as option from dual 
UNION
select ''Yearly Sales'' as option from dual 
order by option</a11><a5>0</a5><a12>true</a12><a14>false</a14><a56></a56><a13>Select</a13><a15><s>pfromdate</s></a15><a67>325</a67><a68>false</a68></preportby><pfromdate cat="params" ord="4"><a1>Task1</a1><a0>pfromdate</a0><a2>From Date</a2><a4>Date/Time</a4><a9>false</a9><a6 sugg="false">m_fystartdate</a6><a10></a10><a21>false</a21><a11 pcount="2">select CASE  WHEN :preportby = ''Monthly Sales'' THEN CURRENT_DATE - INTERVAL ''30 DAY''
                WHEN :preportby = ''Daily Sales'' THEN CURRENT_DATE
                WHEN :preportby = ''Yearly Sales'' THEN CURRENT_DATE - INTERVAL ''365 DAY''
                ELSE cast( :pfromdate as date) end from dual</a11><a5>0</a5><a12>true</a12><a14>false</a14><a56></a56><a13>Accept</a13><a15><s>pfromdate</s></a15><a67>325</a67><a68>false</a68></pfromdate><ptodate cat="params" ord="5"><a1>Task1</a1><a0>ptodate</a0><a2>To Date</a2><a4>Date/Time</a4><a9>false</a9><a6 sugg="false">date()</a6><a10></a10><a21>false</a21><a11></a11><a5>0</a5><a12>true</a12><a14>false</a14><a56></a56><a13>Accept</a13><a15></a15><a67>325</a67><a68>false</a68></ptodate><categoryname cat="querycol" encrypted="F" freezecol="F" negativenorep="" customdecimal="F"><a2>categoryname</a2><a3>Item Category</a3><a1>Task1</a1><a4>Character</a4><a5>0</a5><a6></a6><a7>false</a7><a8>true</a8><a21>false</a21><a13>false</a13><a10>false</a10><a11>false</a11><a12>Clwindow</a12><a9>[Arial,8,clBlack,,False,False,False,False]</a9><a14>Left</a14><a15>true</a15><a16>false</a16><a17>181</a17><a18></a18><a19>false</a19><a53></a53><a54></a54><a55></a55><a58></a58><a59></a59><a61>0</a61><a62></a62><a69 masking=""></a69></categoryname><productcategory cat="querycol" encrypted="F" freezecol="F" negativenorep="" customdecimal="F"><a2>productcategory</a2><a3>Item Subcategory</a3><a1>Task1</a1><a4>Character</a4><a5>0</a5><a6></a6><a7>false</a7><a8>true</a8><a21>false</a21><a13>false</a13><a10>false</a10><a11>false</a11><a12>Clwindow</a12><a9>[Arial,8,clBlack,,False,False,False,False]</a9><a14>Left</a14><a15>true</a15><a16>false</a16><a17>226</a17><a18></a18><a19>false</a19><a53></a53><a54></a54><a55></a55><a58></a58><a59></a59><a61>0</a61><a62></a62><a69 masking=""></a69></productcategory><brand_name cat="querycol" encrypted="F" freezecol="F" negativenorep="" customdecimal="F"><a2>brand_name</a2><a3>Brand</a3><a1>Task1</a1><a4>Character</a4><a5>0</a5><a6></a6><a7>false</a7><a8>true</a8><a21>false</a21><a13>false</a13><a10>false</a10><a11>false</a11><a12>Clwindow</a12><a9>[Arial,8,clBlack,,False,False,False,False]</a9><a14>Left</a14><a15>true</a15><a16>false</a16><a17>80</a17><a18></a18><a19>false</a19><a53></a53><a54></a54><a55></a55><a58></a58><a59></a59><a61>0</a61><a62></a62><a69 masking=""></a69></brand_name><itemdesc cat="querycol" encrypted="F" freezecol="F" negativenorep="" customdecimal="F"><a2>itemdesc</a2><a3>{preportby}</a3><a1>Task1</a1><a4>Character</a4><a5>0</a5><a6></a6><a7>false</a7><a8>true</a8><a21>false</a21><a13>false</a13><a10>false</a10><a11>false</a11><a12>Clwindow</a12><a9>[Arial,8,clBlack,,False,False,False,False]</a9><a14>Left</a14><a15>true</a15><a16>false</a16><a17>236</a17><a18></a18><a19>false</a19><a53></a53><a54></a54><a55>openiview</a55><a58></a58><a59></a59><a61>0</a61><a62></a62><a69 masking=""></a69></itemdesc><invoice_qty cat="querycol" encrypted="F" freezecol="F" negativenorep="" customdecimal="F"><a2>invoice_qty</a2><a3>Qty</a3><a1>Task1</a1><a4>Numeric</a4><a5>2</a5><a6></a6><a7>false</a7><a8>true</a8><a21>false</a21><a13>false</a13><a10>true</a10><a11>false</a11><a12>Clwindow</a12><a9>[Arial,8,clBlack,,False,False,False,False]</a9><a14>Right</a14><a15>true</a15><a16>false</a16><a17>78</a17><a18></a18><a19>false</a19><a53></a53><a54></a54><a55></a55><a58></a58><a59></a59><a61>0</a61><a62></a62><a69 masking=""></a69></invoice_qty><gross_amount cat="querycol" encrypted="F" freezecol="F" negativenorep="" customdecimal="F"><a2>gross_amount</a2><a3>Gross Amount</a3><a1>Task1</a1><a4>Numeric</a4><a5>2</a5><a6></a6><a7>false</a7><a8>true</a8><a21>false</a21><a13>false</a13><a10>true</a10><a11>false</a11><a12>Clwindow</a12><a9>[Arial,8,clBlack,,False,False,False,False]</a9><a14>Right</a14><a15>true</a15><a16>false</a16><a17>117</a17><a18></a18><a19>false</a19><a53></a53><a54></a54><a55></a55><a58></a58><a59></a59><a61>0</a61><a62></a62><a69 masking=""></a69></gross_amount><discount cat="querycol" encrypted="F" freezecol="F" negativenorep="" customdecimal="F"><a2>discount</a2><a3>Discount</a3><a1>Task1</a1><a4>Numeric</a4><a5>2</a5><a6></a6><a7>false</a7><a8>true</a8><a21>false</a21><a13>false</a13><a10>