	<row1 cat="sql">
		<a1>Task1</a1>
		<a2>
			<l0>select a.branchname,a.locationname, i.itemcode, i.itemdesc, sum(a.opening_qty) opening_qty,sum(a.received_qty) received_qty,sum(a.issued_qty) issued_qty,</l0>
			<l1>sum( a.opening_qty + a.received_qty + a.issued_qty )  as closing_qty,</l1>
			<l2>sum( a.opening_value + a.received_value + a.issued_value )  as closing_value,</l2>
			<l3>cast( :pfromdate as date) as fromdate,</l3>
			<l4>cast( :ptodate as date) as todate</l4>
			<l5>from</l5>
			<l6>( select a.itemid itemname, a.locationname, a.branchname, a.company, </l6>
			<l7>sum(received_qty + issued_qty) as opening_qty,sum(a.received_value + issued_value) AS opening_value, 0 issued_qty, 0 AS issued_value,  0 as received_qty, 0 AS received_value</l7>
			<l8>from mv_stockdetails a</l8>
			<l9>where a.company = cast( :pcompanyid as numeric)</l9>
			<l10>and a.docdate &lt; cast( :pfromdate as date) </l10>
			<l11>group by a.itemid, a.locationname, a.branchname, a.company</l11>
			<l12>union all</l12>
			<l13>select a.itemid itemname, a.locationname, a.branchname, a.company, 0 as opening_qty, 0 AS opening_value, </l13>
			<l14>case when lower(a.plusorminus) = ''m'' then sum(a.issued_qty)  else 0 end as issued_qty,</l14>
			<l15>case when lower(a.plusorminus) = ''m'' then sum(a.issued_value)  else 0 end as issued_value,</l15>
			<l16>case when lower(a.plusorminus) = ''p'' then sum(a.received_qty)  else 0 end as received_qty_,</l16>
			<l17>case when lower(a.plusorminus) = ''p'' then sum(a.received_value)  else 0 end as received_value</l17>
			<l18>from mv_stockdetails a</l18>
			<l19>where a.company = cast( :pcompanyid as numeric)</l19>
			<l20>and a.docdate between cast( :pfromdate as date)  and  cast( :ptodate as date)</l20>
			<l21>group by a.itemid, a.locationname, a.branchname, a.company, a.plusorminus</l21>
			<l22>) a,item i</l22>
			<l23>where a.itemname = i.itemid</l23>
			<l24>and i.itemid != 1</l24>
			<l25>and (a.branchname  = :pbranch or :pbranch = ''ALL'' )</l25>
			<l26>and (a.locationname  = :plocation or :plocation = ''ALL'' )</l26>
			<l27>group by i.itemcode, i.itemname, a.locationname, a.branchname, i.itemdesc</l27>
			<l28>having sum(a.opening_qty + a.issued_qty + a.received_qty) &gt;= 0</l28>
			<l29>order by a.branchname,a.locationname, i.itemdesc</l29>
		</a2>
		<a3></a3>
		<a4>reportsql</a4>
	</row1>
