	<row1 cat="sql">
		<a1>Task1</a1>
		<a2>
			<l0>SELECT a.salesorder_headerid, func_returns_hyperlink( d.party_name,''formpage'',''gcust'',d.mg_customerid,''Customer'',d.party_name) as party_name, br.branchname,concat(a.docdate,'' '',func_returns_hyperlink( a.docid,''formpage'',''slord'',a.salesorder_headerid,''Sales Order'',a.docid)) as docid,</l0>
			<l1>concat(func_returns_hyperlink( c.itemdesc,''formpage'',''prodm'',c.itemid,''Product Master'',c.itemdesc),'' / '',c.itemcode) as itemname, c.uom, b.order_qty, b.invoiced_qty,</l1>
			<l2>       (b.order_qty - b.invoiced_qty) as pending_qty, ''Raise Invoice'' as gaction, a.currency,i.categoryname, p.productcategory, m.brand_name,d.party_name as mparty_name,a.docid as mdocid,</l2>
			<l3>       c.itemdesc</l3>
			<l4>  FROM salesorder_header a, salesorder_items b, item c, mg_customer d, branch br,itemcategory i, productcategory p, brand_master m</l4>
			<l5>  WHERE a.cancel = ''F''</l5>
			<l6>    AND a.salesorder_headerid = b.salesorder_headerid</l6>
			<l7>    and br.branchid = a.branch</l7>
			<l8>    and c.active = ''T''</l8>
			<l9>    and c.cancel = ''F''</l9>
			<l10>    and c.app_desc = 1</l10>
			<l11>    AND (b.order_qty - b.invoiced_qty) &gt; 0  </l11>
			<l12>    AND a.company = cast( :pcompanyid as numeric)</l12>
			<l13>    and (br.branchname = :pbranch or :pbranch = ''ALL'')</l13>
			<l14>    and (d.party_name = :pcustomer or :pcustomer = ''ALL'')</l14>
			<l15>    and (a.docdate BETWEEN cast( :pfromdate as date) and cast( :ptodate as date)) </l15>
			<l16>    AND b.itemname = c.itemid</l16>
			<l17>    AND a.customer = d.mg_customerid</l17>
			<l18>    and c.itemcategory = i.itemcategoryid</l18>
			<l19>      and c.productcategory = p.productcategoryid</l19>
			<l20>      and c.itembrand = m.brand_masterid</l20>
			<l21>  ORDER BY a.docdate desc</l21>
		</a2>
		<a3></a3>
		<a4>reportsql</a4>
	</row1>
