	<row1 cat="sql">
		<a1>Task1</a1>
		<a2>
			<l0>select </l0>
			<l1>a.arapdetailsid, </l1>
			<l2>a.sourceid, </l2>
			<l3>a.transid, </l3>
			<l4>a.mg_accountid, </l4>
			<l5>a.mg_subledgerid,  </l5>
			<l6>a.accountname,</l6>
			<l7>a.subledgername, </l7>
			<l8>a.branchname, </l8>
			<l9>a.docid, </l9>
			<l10>a.docdate, </l10>
			<l11>a.creditdays, </l11>
			<l12>a.due_date, </l12>
			<l13>concat( to_char(due_date,''dd/mm/yyyy''),''-'',cast( a.creditdays as varchar),'' Days'') as duedays,</l13>
			<l14>a.namount AS bamount, </l14>
			<l15>a.setnamount as setamount, </l15>
			<l16>a.outstanding_namount outstanding_bamount, </l16>
			<l17>a.outstanding_days, </l17>
			<l18>case when a.outstanding_days &lt;= a.mslab1 and a.outstanding_namount  &gt; 0 then a.outstanding_namount  else 0 end as mslab1, </l18>
			<l19>case when a.outstanding_days between cast( :slab1 as numeric) + 1 and :slab2 and a.outstanding_namount  &gt; 0 then a.outstanding_namount else 0 end as mslab2,</l19>
			<l20>case when a.outstanding_days between cast( :slab2 as numeric) + 1 and :slab3 and a.outstanding_namount  &gt; 0 then a.outstanding_namount else 0 end as mslab3,</l20>
			<l21>case when a.outstanding_days &gt; cast( :slab3 as numeric) and a.outstanding_namount  &gt; 0 then a.outstanding_namount else 0 end as mslab4,</l21>
			<l22>case when a.outstanding_days between cast( :slab4 as numeric) + 1 and :slab5 and a.outstanding_namount  &gt; 0 then a.outstanding_namount else 0 end as mslab5,</l22>
			<l23>case when a.outstanding_days &gt; cast( :slab5 as numeric) and a.outstanding_namount  &gt; 0 then a.outstanding_namount else 0 end as mslab6,</l23>
			<l24>a.salesman, </l24>
			<l25>a.statejurisdiction as state </l25>
			<l26>from (</l26>
			<l27>select a.arapdetailsid, </l27>
			<l28>a.sourceid, </l28>
			<l29>''t''||REGEXP_REPLACE(a.mapname, ''[0-9]'', '''', ''g'' ) as transid, </l29>
			<l30>m.mg_accountid, </l30>
			<l31>s.mg_subledgerid,  </l31>
			<l32>m.accountname,</l32>
			<l33>s.subledgername, </l33>
			<l34>br.branchname, </l34>
			<l35>a.docid, a.docdate, </l35>
			<l36>cast( :asondate as date) as asondate,</l36>
			<l37>a.creditdays, </l37>
			<l38>a.docdate + interval ''1day'' * a.creditdays  as due_date, </l38>
			<l39>a.amount, </l39>
			<l40>a.bamount, </l40>
			<l41>a.namount, </l41>
			<l42>b.amount as setamount, </l42>
			<l43>b.bamount as setbamount, </l43>
			<l44>b.namount as setnamount, </l44>
			<l45>cast( a.amount + coalesce ( b.amount,0) as numeric) as outstanding_amount,</l45>
			<l46>cast( a.bamount + coalesce ( b.bamount,0) as numeric) as outstanding_bamount,</l46>
			<l47>cast( a.namount + coalesce ( b.namount,0) as numeric) as outstanding_namount, </l47>
			<l48>upper( :pduewise)  as duewise, </l48>
			<l49>cast( REGEXP_REPLACE(</l49>
			<l50>cast( cast( :asondate as date) - case when upper( :pduewise) = ''YES'' then a.docdate + interval ''1 day'' * a.creditdays </l50>
			<l51>else a.docdate end as text), ''[^0-9]'', '''', ''g'' )  as numeric)</l51>
			<l52>as outstanding_days, </l52>
			<l53>cast( :slab1 as numeric) as mslab1, </l53>
			<l54>cast( :slab2 as numeric) as mslab2, </l54>
			<l55>cast( :slab3 as numeric) as mslab3, </l55>
			<l56>cast( :slab4 as numeric) as mslab4, </l56>
			<l57>cast( :slab5 as numeric) as mslab5, </l57>
			<l58>s.salesman, </l58>
			<l59>s.statejurisdiction </l59>
			<l60>from arapdetails a</l60>
			<l61>join branch br on ( a.branch = br.branchid ) </l61>
			<l62>left join (</l62>
			<l63>select b.accountname, b.subledgername, </l63>
			<l64>b.refno, max(b.refdate) as refdate, </l64>
			<l65>sum(b.amount) as amount, </l65>
			<l66>sum(b.bamount) as bamount, sum(b.namount) as namount</l66>
			<l67>from arapadjustments b </l67>
			<l68>where b.cancel = ''F''</l68>
			<l69>and b.company = cast( :pcompanyid as numeric )</l69>
			<l70>group by b.accountname, b.subledgername, b.refno</l70>
			<l71>) b on ( a.subledgercode = b.subledgername </l71>
			<l72> and a.docid = b.refno </l72>
			<l73> and a.docdate &lt;= :asondate</l73>
			<l74> and a.accountname = b.accountname</l74>
			<l75> )</l75>
			<l76> join mg_subledger s on ( a.subledgercode = s.mg_subledgerid  )</l76>
			<l77> join mg_account m on ( s.controlaccount = m.mg_accountid  )</l77>
			<l78>where a.cancel = ''F''</l78>
			<l79>and  a.app_desc = 1</l79>
			<l80>and a.company  = cast( :pcompanyid as numeric )</l80>
			<l81>and (s.subledgername = :psubledgername or :psubledgername = ''ALL'')</l81>
			<l82>and (br.branchname = cast( :pbranchname as text) or cast( :pbranchname as text) = ''ALL'')</l82>
			<l83>and ( m.accountname = cast( :paccountname as text) or cast( :paccountname as text) = ''ALL'' )</l83>
			<l84>and (( a.docdate &lt;= :asondate and upper( :pduewise) = ''NO'') or ( a.docdate + interval ''1 day'' * a.creditdays  &lt;= :asondate and upper(:pduewise) = ''YES'')  </l84>
			<l85>) </l85>
			<l86>) a</l86>
			<l87>where a.outstanding_namount != 0 </l87>
			<l88>order by accountname, subledgername, docdate</l88>
		</a2>
		<a3></a3>
		<a4>reportsql</a4>
	</row1>
