	<row1 cat="sql">
		<a1>Task1</a1>
		<a2>
			<l0>select s.subledgername,sum(s.bamount) as bamount,sum(s.setamount) as setamount,sum(s.outstanding_bamount) as outstanding_bamount,</l0>
			<l1>sum(s.mslab1) as mslab1,sum(s.mslab2) as mslab2,sum(s.mslab3) as mslab3,sum(s.mslab4) as mslab4 from </l1>
			<l2>(select </l2>
			<l3>a.arapdetailsid, </l3>
			<l4>a.sourceid, </l4>
			<l5>a.transid, </l5>
			<l6>a.mg_accountid, </l6>
			<l7>a.mg_subledgerid,  </l7>
			<l8>a.accountname,</l8>
			<l9>a.subledgername, </l9>
			<l10>a.branchname, </l10>
			<l11>a.docid, </l11>
			<l12>a.docdate, </l12>
			<l13>a.creditdays, </l13>
			<l14>a.due_date, </l14>
			<l15>concat( to_char(due_date,''dd/mm/yyyy''),''-'',cast( a.creditdays as varchar),'' Days'') as duedays,</l15>
			<l16>a.namount AS bamount, </l16>
			<l17>a.setnamount as setamount, </l17>
			<l18>a.outstanding_namount as outstanding_bamount, </l18>
			<l19>a.outstanding_days, </l19>
			<l20>case when a.outstanding_days &lt;= a.mslab1 and a.outstanding_namount  &gt; 0 then a.outstanding_namount  else 0 end as mslab1, </l20>
			<l21>case when a.outstanding_days between cast( :slab1 as numeric) + 1 and :slab2 and a.outstanding_namount  &gt; 0 then a.outstanding_namount else 0 end as mslab2,</l21>
			<l22>case when a.outstanding_days between cast( :slab2 as numeric) + 1 and :slab3 and a.outstanding_namount  &gt; 0 then a.outstanding_namount else 0 end as mslab3,</l22>
			<l23>case when a.outstanding_days &gt; cast( :slab3 as numeric) and a.outstanding_namount  &gt; 0 then a.outstanding_namount else 0 end as mslab4,</l23>
			<l24>case when a.outstanding_days between cast( :slab4 as numeric) + 1 and :slab5 and a.outstanding_namount  &gt; 0 then a.outstanding_namount else 0 end as mslab5,</l24>
			<l25>case when a.outstanding_days &gt; cast( :slab5 as numeric) and a.outstanding_namount  &gt; 0 then a.outstanding_namount else 0 end as mslab6,</l25>
			<l26>a.salesman, </l26>
			<l27>a.statejurisdiction as state </l27>
			<l28>from (</l28>
			<l29>select a.arapdetailsid, </l29>
			<l30>a.sourceid, </l30>
			<l31>''t''||REGEXP_REPLACE(a.mapname, ''[0-9]'', '''', ''g'' ) as transid, </l31>
			<l32>m.mg_accountid, </l32>
			<l33>s.mg_subledgerid,  </l33>
			<l34>m.accountname,</l34>
			<l35>s.subledgername, </l35>
			<l36>br.branchname, </l36>
			<l37>a.docid, a.docdate, </l37>
			<l38>cast( :asondate as date) as asondate,</l38>
			<l39>a.creditdays, </l39>
			<l40>a.docdate + interval ''1day'' * a.creditdays  as due_date, </l40>
			<l41>a.amount, </l41>
			<l42>a.bamount, </l42>
			<l43>a.namount, </l43>
			<l44>b.amount as setamount, </l44>
			<l45>b.bamount as setbamount, </l45>
			<l46>b.namount as setnamount, </l46>
			<l47>cast( a.amount + coalesce ( b.amount,0) as numeric) as outstanding_amount,</l47>
			<l48>cast( a.bamount + coalesce ( b.bamount,0) as numeric) as outstanding_bamount,</l48>
			<l49>cast( a.namount + coalesce ( b.namount,0) as numeric) as outstanding_namount, </l49>
			<l50>upper( :pduewise)  as duewise, </l50>
			<l51>cast( REGEXP_REPLACE(</l51>
			<l52>cast( cast( :asondate as date) - case when upper( :pduewise) = ''YES'' then a.docdate + interval ''1 day'' * a.creditdays </l52>
			<l53>else a.docdate end as text), ''[^0-9]'', '''', ''g'' )  as numeric)</l53>
			<l54>as outstanding_days, </l54>
			<l55>cast( :slab1 as numeric) as mslab1, </l55>
			<l56>cast( :slab2 as numeric) as mslab2, </l56>
			<l57>cast( :slab3 as numeric) as mslab3, </l57>
			<l58>cast( :slab4 as numeric) as mslab4, </l58>
			<l59>cast( :slab5 as numeric) as mslab5, </l59>
			<l60>s.salesman, </l60>
			<l61>s.statejurisdiction </l61>
			<l62>from arapdetails a</l62>
			<l63>join branch br on ( a.branch = br.branchid ) </l63>
			<l64>left join (</l64>
			<l65>select b.accountname, b.subledgername, </l65>
			<l66>b.refno, max(b.refdate) as refdate, </l66>
			<l67>sum(b.amount) as amount, </l67>
			<l68>sum(b.bamount) as bamount, sum(b.namount) as namount</l68>
			<l69>from arapadjustments b </l69>
			<l70>where b.cancel = ''F''</l70>
			<l71>and b.company = cast( :pcompanyid as numeric )</l71>
			<l72>group by b.accountname, b.subledgername, b.refno</l72>
			<l73>) b on ( a.subledgercode = b.subledgername </l73>
			<l74> and a.docid = b.refno </l74>
			<l75> and a.docdate &lt;= :asondate</l75>
			<l76> and a.accountname = b.accountname</l76>
			<l77> )</l77>
			<l78> join mg_subledger s on ( a.subledgercode = s.mg_subledgerid  )</l78>
			<l79> join mg_account m on ( s.controlaccount = m.mg_accountid  )</l79>
			<l80>where a.cancel = ''F''</l80>
			<l81>and  a.app_desc = 1</l81>
			<l82>and a.company  = cast( :pcompanyid as numeric )</l82>
			<l83>and (s.subledgername = :psubledgername or :psubledgername = ''ALL'')</l83>
			<l84>and (br.branchname = cast( :pbranchname as text) or cast( :pbranchname as text) = ''ALL'')</l84>
			<l85>and ( m.accountname = cast( :paccountname as text) or cast( :paccountname as text) = ''ALL'' )</l85>
			<l86>and (( a.docdate &lt;= :asondate and upper( :pduewise) = ''NO'') or ( a.docdate + interval ''1 day'' * a.creditdays  &lt;= :asondate and upper(:pduewise) = ''YES'')  </l86>
			<l87>) </l87>
			<l88>) a</l88>
			<l89>where a.outstanding_namount != 0 </l89>
			<l90>order by accountname, subledgername, docdate)s </l90>
			<l91>group by s.subledgername</l91>
		</a2>
		<a3></a3>
		<a4>reportsql</a4>
	</row1>
