and  a.company = cast( :pcompanyid as numeric)
UNION
select ''ALL'' as employee_name from dual
order by 1
</a11><a5>0</a5><a12>true</a12><a14>false</a14><a56></a56><a13>Select</a13><a15></a15><a67>325</a67><a68>false</a68></psalesman><pitem cat="params" ord="3"><a1>Task1</a1><a0>pitem</a0><a2>Product Name</a2><a4>Character</a4><a9>false</a9><a6 sugg="false">{ALL}</a6><a10></a10><a21>false</a21><a11 pcount="1">select a.itemdesc from vw_item a 
