	<row1 cat="sql">
		<a1>Task1</a1>
		<a2>
			<l0>select a.categoryname, a.productcategory, a.brand_name, a.branchname,a.itemdesc, sum(a.qty) as invoice_qty, sum(a.gross_amount) as gross_amount, sum(a.discount) as discount,</l0>
			<l1>sum(a.taxableamount) as taxableamount, sum(a.net_amount) as net_amount</l1>
			<l2>from vw_sales_items a</l2>
			<l3>where a.company = cast( :pcompanyid as numeric)</l3>
			<l4>and a.docdate between cast( :pfromdate as date) AND cast( :ptodate as date)</l4>
			<l5>and (a.itemdesc = :pitem or :pitem = ''ALL'')</l5>
			<l6>and (a.branchname = :pbranchname or :pbranchname = ''ALL'')</l6>
			<l7>group by a.categoryname, a.productcategory, a.brand_name, a.itemdesc,a.branchname</l7>
			<l8>having sum(a.qty) &gt; 0</l8>
			<l9>order by 1,2,4</l9>
		</a2>
		<a3></a3>
		<a4>reportsql</a4>
	</row1>
