('purdtlrp', 'Purchase Detailed', '<root pform="yes" name="purdtlrp" caption="Purchase Detailed" updatedon="20/05/2026 11:43:33" updatedby="tamilselvan" createdon="20/05/2026 11:43:33 AM" createdby="tamilselvan"><iview cat="iview" hideprojname="" hidereportdate="" parrange="1"><a0>purdtlrp</a0><a2>Purchase Detailed</a2><a3 ptable=""></a3><a4>0</a4><a5>true</a5><a6></a6><a7></a7><a8>0</a8><a9></a9><a10>false</a10><a11>true</a11><a12></a12><a13></a13><a14></a14><a15></a15><a16></a16><a17>Enabled</a17><a18>false</a18><a19>false</a19><a51></a51><a52></a52><a53></a53><a54></a54><a55>select row</a55><a57>false</a57><a63>true</a63><a64>false</a64><b9>Purchase Detailed</b9><b10></b10><b11></b11><b12></b12><b13></b13><b14></b14><b15></b15><b16></b16><b17></b17><b35>false</b35><b36>Center</b36><b37>Center</b37><a31></a31><a32>1</a32><a33>false</a33><a34>false</a34><a35>0</a35><a36></a36><a37></a37><a38></a38><a39>false</a39><a40>false</a40><a21>false</a21><a41>false</a41><a42>clskyblue</a42><a43>[Tahoma,9,clBlack,,True,False,False,False]</a43><a44>[Tahoma,8,clBlack,,True,False,False,False]</a44><a45>[Tahoma,8,clBlack,,True,False,False,False]</a45><a46>$00F3AFA0</a46><a47>[Tahoma,8,clBlack,,True,False,False,False]</a47><a48>$00EEF1F2</a48><a49>$00E2E8E9</a49><a50>18</a50><a60>1</a60><b18></b18><b21></b21><b23></b23><b22>0</b22><b38>Classic</b38><b39></b39><a65>false</a65><a66>false</a66></iview><scripts cat="actions"><opnfrm script="true" cap="Open Form" type="iview" apply="Current Row " applyon="" sname="purdtlrp" desc="" failmessage="" validate="no" web="no" breakonerror="no" localnum="6"><r1 id="a1" op="5" task="scripts" type="" sname="" apply="" applyon=""><param1 task="scripts" op="7"><exprset><l0>if transid={pbill}</l0><l1>    LoadFormAndData({pbill},{purchase_bill_headerid=:purchase_bill_headerid},{d},{true})</l1><l2>elseif transid={purre}</l2><l3>    LoadFormAndData({purre},{purchasereturn_headerid=:purchasereturn_headerid},{d},{true})</l3><l4>end if</l4></exprset></param1></r1></opnfrm></scripts><comps cat="comps" dwbtb="true" LocalNum="9" btn="6" vupd="" pnlheight="35"><btn1 key="btn1" caption="Print" cat="btn" tlhw="7,1,20,20" parent="btnPanel" font="Tahoma,8,clWindowText,ffff" def="right" task="print" action="" container="" sname="" flat="true" position="Left" visible="true" footer="false" hint="Print" down=""/><btn2 key="btn2" caption="Preview" cat="btn" tlhw="7,1,20,20" parent="btnPanel" font="Tahoma,8,clWindowText,ffff" def="right" task="preview" action="" container="" sname="" flat="true" position="Left" visible="true" footer="false" hint="Preview" down=""/><btn3 key="btn3" caption="Page Setup / Printer Setting" cat="btn" tlhw="7,1,20,20" parent="btnPanel" font="Tahoma,8,clWindowText,ffff" def="right" task="printersetting" action="" container="" sname="" flat="true" position="Left" visible="true" footer="false" hint="Page Setup / Printer Setting" down=""/><btn4 key="btn4" caption="View" cat="btn" tlhw="7,1,20,20" parent="btnPanel" font="Tahoma,8,clWindowText,ffff" def="right" task="view" action="" container="" sname="" flat="true" position="Left" visible="true" footer="false" hint="View" down=""/><btn5 key="btn5" caption="Find" cat="btn" tlhw="7,1,20,20" parent="btnPanel" font="Tahoma,8,clWindowText,ffff" def="right" task="find" action="" container="" sname="" flat="true" position="Left" visible="true" footer="false" hint="Find" down=""/><btn6 key="btn6" caption="Tasks" cat="btn" tlhw="7,1,20,20" parent="btnPanel" font="Tahoma,8,clWindowText,ffff" def="right" task="tasks" action="" container="" sname="" flat="true" position="Left" visible="false" footer="false" hint="Tasks" down="" folder="true"/><x__head caption="Purchase Detailed" cat="txt" parent="pnlButton" color="$00F2F0F0" align="none" def="left" tlhw="7,5,19,53" font="_Tahoma,,,clWindowText" type="pnl"/></comps><row1 cat="sql"><a1>Task1</a1><a2><l0>select a.docdate,func_returns_hyperlink( a.docid,''formpage'',a.transid,a.headerid, (case when a.transid = ''pbill'' then ''Purchase Bill'' else ''Purchase Return'' end),a.docid)as docid,</l0><l1>sum(a.qty) as qty,sum(a.grossamount) as gross_amount, sum(a.netamtwotax) as netamtwotax, sum(a.taxableamount) as taxableamount, sum(a.discamount) as discount,</l1><l2>sum(a.netamount) as net_amount, a.branchname, a.transid,a.supplier </l2><l3>from vw_purchase_items a </l3><l4>where a.company = cast( :pcompanyid as numeric) </l4><l5>and (a.branchname = :pbranch or :pbranch =''ALL'')</l5><l6>and (a.itemdesc = :pitemname or :pitemname = ''ALL'')</l6><l7>and (a.currency = :pcurrency or :pcurrency = ''ALL'') </l7><l8>and (a.supplier = :psupplier or :psupplier = ''ALL'') </l8><l9>and (a.brand_name = :pbrand or :pbrand = ''ALL'')</l9><l10>and (a.categoryname = :pcategory or :pcategory = ''ALL'')</l10><l11>and (a.productcategory = :psubcategory or :psubcategory = ''ALL'')</l11><l12>and (a.docdate BETWEEN cast( :pfromdate as date) and cast( :ptodate as date)) </l12><l13>group by a.docdate,a.docid, a.branchname, a.supplier, a.transid,a.headerid </l13><l14>order by branchname, docdate desc</l14></a2><a3></a3><a4>reportsql</a4></row1><pcompanyid cat="params" ord="1"><a1>Task1</a1><a0>pcompanyid</a0><a2>Company</a2><a4>Numeric</a4><a9>false</a9><a6 sugg="false">m_companyid</a6><a10></a10><a21>true</a21><a11></a11><a5>0</a5><a12>true</a12><a14>false</a14><a56></a56><a13>Accept</a13><a15><s>pitemname,psupplier,pbrand,pcategory,psubcategory</s></a15><a67>325</a67><a68>false</a68></pcompanyid><pbranch cat="params" ord="2"><a1>Task1</a1><a0>pbranch</a0><a2>Branch</a2><a4>Character</a4><a9>false</a9><a6 sugg="false">{ALL}</a6><a10></a10><a21>false</a21><a11 pcount="0">select a.branchname from vw_userbranchlocations a 
where a.username = :username 
union 
select ''ALL'' as branchname from dual 
order by 1</a11><a5>0</a5><a12>true</a12><a14>false</a14><a56></a56><a13>Select</a13><a15></a15><a67>325</a67><a68>false</a68></pbranch><pitemname cat="params" ord="3"><a1>Task1</a1><a0>pitemname</a0><a2>Item Name</a2><a4>Character</a4><a9>false</a9><a6 sugg="false">{ALL}</a6><a10></a10><a21>false</a21><a11 pcount="1">select a.itemdesc from item a 
where a.cancel = ''F'' 
and a.app_desc = 1 
and a.active = ''T'' 
and a.company = :pcompanyid 
union 
select ''ALL'' as itemdesc from dual 
order by 1</a11><a5>0</a5><a12>true</a12><a14>false</a14><a56></a56><a13>Select</a13><a15></a15><a67>325</a67><a68>false</a68></pitemname><pcurrency cat="params" ord="4"><a1>Task1</a1><a0>pcurrency</a0><a2>Currency</a2><a4>Character</a4><a9>false</a9><a6 sugg="false">{ALL}</a6><a10></a10><a21>false</a21><a11>select a.currency from currency a 
where a.cancel = ''F'' 
and a.app_desc = 1 
and a.active = ''T'' 
UNION
select ''ALL'' as currency from dual
order by 1</a11><a5>0</a5><a12>true</a12><a14>false</a14><a56></a56><a13>Select</a13><a15></a15><a67>325</a67><a68>false</a68></pcurrency><psupplier cat="params" ord="5"><a1>Task1</a1><a0>psupplier</a0><a2>Supplier</a2><a4>Character</a4><a9>false</a9><a6 sugg="false">{ALL}</a6><a10></a10><a21>false</a21><a11 pcount="1">select a.party_name from mg_supplier a 
where a.cancel = ''F'' 
and a.app_desc = 1 
and a.active = ''T'' 
and a.company = cast( :pcompanyid as numeric)
and (a.mg_supplierid = cast( :m_supplierid as numeric) or cast( :m_supplierid as numeric) = 0)
UNION
select ''ALL'' as party_name from dual 
