r1></open></scripts><comps cat="comps" dwbtb="true" LocalNum="9" btn="6" vupd="" pnlheight="35"><btn1 key="btn1" caption="Print" cat="btn" tlhw="7,1,20,20" parent="btnPanel" font="Tahoma,8,clWindowText,ffff" def="right" task="print" action="" container="" sname="" flat="true" position="Left" visible="true" footer="false" hint="Print" down=""><icon><text>list</text><addClass>material-icons</addClass></icon></btn1><btn2 key="btn2" caption="Preview" cat="btn" tlhw="7,1,20,20" parent="btnPanel" font="Tahoma,8,clWindowText,ffff" def="right" task="preview" action="" container="" sname="" flat="true" position="Left" visible="true" footer="false" hint="Preview" down=""><icon><text>video_label</text><addClass>material-icons</addClass></icon></btn2><btn3 key="btn3" caption="Page Setup / Printer Setting" cat="btn" tlhw="7,1,20,20" parent="btnPanel" font="Tahoma,8,clWindowText,ffff" def="right" task="printersetting" action="" container="" sname="" flat="true" position="Left" visible="true" footer="false" hint="Page Setup / Printer Setting" down=""><icon><text>import_contacts</text><addClass>material-icons</addClass></icon></btn3><btn4 key="btn4" caption="View" cat="btn" tlhw="7,1,20,20" parent="btnPanel" font="Tahoma,8,clWindowText,ffff" def="right" task="view" action="" container="" sname="" flat="true" position="Left" visible="true" footer="false" hint="View" down=""><icon><text>remove_red_eye</text><addClass>material-icons</addClass></icon></btn4><btn5 key="btn5" caption="Find" cat="btn" tlhw="7,1,20,20" parent="btnPanel" font="Tahoma,8,clWindowText,ffff" def="right" task="find" action="" container="" sname="" flat="true" position="Left" visible="true" footer="false" hint="Find" down=""><icon><text>search</text><addClass>material-icons</addClass></icon></btn5><btn6 key="btn6" caption="Tasks" cat="btn" tlhw="7,1,20,20" parent="btnPanel" font="Tahoma,8,clWindowText,ffff" def="right" task="tasks" action="" container="" sname="" flat="true" position="Left" visible="true" footer="false" hint="Tasks" down="" folder="true"><icon><text>receipt</text><addClass>material-icons</addClass></icon></btn6><x__head caption="Product Category Wise Purchases" cat="txt" parent="pnlButton" color="$00F2F0F0" align="none" def="left" tlhw="7,5,19,53" font="_Tahoma,,,clWindowText" type="pnl"/></comps><row1 cat="sql"><a1>Task1</a1><a2><l0>select a.categoryname, a.productcategory, a.brand_name, a.itemdesc, sum(a.qty) as qty, sum(a.grossamount) as gross_amount, sum(a.discamount) as discount,</l0><l1>sum(a.taxableamount) as taxableamount, sum(a.netamount) as net_amount</l1><l2>from vw_purchase_items a</l2><l3>where a.company = cast( :pcompanyid as numeric)</l3><l4>and a.docdate between cast( :pfromdate as date) AND cast( :ptodate as date)</l4><l5>and (a.itemdesc = :pitem or :pitem = ''ALL'')</l5><l6>and (a.categoryname = :pcategory or :pcategory = ''ALL'')</l6><l7>group by a.categoryname, a.productcategory, a.brand_name, a.itemdesc</l7><l8>order by 1,2,4</l8></a2><a3></a3><a4>reportsql</a4></row1><pcompanyid cat="params" ord="1"><a1>Task1</a1><a0>pcompanyid</a0><a2>pcompanyid</a2><a4>Numeric</a4><a9>false</a9><a6 sugg="false">m_companyid</a6><a10></a10><a21>true</a21><a11></a11><a5>0</a5><a12>true</a12><a14>false</a14><a56></a56><a13>Accept</a13><a15><s>pcategory,pitem</s></a15><a67>325</a67><a68>false</a68></pcompanyid><pcategory cat="params" ord="2"><a1>Task1</a1><a0>pcategory</a0><a2>Category</a2><a4>Character</a4><a9>false</a9><a6 sugg="false">{ALL}</a6><a10></a10><a21>false</a21><a11 pcount="1">select a.categoryname from itemcategory a 
where a.cancel = ''F''
and a.app_desc = 1 
and a.active = ''T'' 
and a.company = cast( :pcompanyid as numeric)
UNION
select ''ALL'' as categoryname from dual
order by 1</a11><a5>0</a5><a12>true</a12><a14>false</a14><a56></a56><a13>Select</a13><a15></a15><a67>325</a67><a68>false</a68></pcategory><pitem cat="params" ord="3"><a1>Task1</a1><a0>pitem</a0><a2>Product Name</a2><a4>Character</a4><a9>false</a9><a6 sugg="false">{ALL}</a6><a10></a10><a21>false</a21><a11 pcount="1">select a.itemdesc from vw_item a 
where a.company = cast( :pcompanyid as numeric)
UNION
select ''ALL'' as itemdesc from dual
