('accrecv', 'Accounts Receivable', '<root pform="yes" name="accrecv" caption="Accounts Receivable" updatedon="20/05/2026 12:04:02" updatedby="tamilselvan" createdon="20/05/2026 12:04:02 PM" createdby="tamilselvan"><iview cat="iview" hideprojname="" hidereportdate="" parrange="1"><a0>accrecv</a0><a2>Accounts Receivable</a2><a3 ptable=""></a3><a4>0</a4><a5>true</a5><a6></a6><a7></a7><a8>0</a8><a9></a9><a10>false</a10><a11>true</a11><a12></a12><a13></a13><a14></a14><a15></a15><a16></a16><a17>Enabled</a17><a18>false</a18><a19>false</a19><a51></a51><a52></a52><a53></a53><a54></a54><a55>select row</a55><a57>false</a57><a63>true</a63><a64>false</a64><b9>Accounts Receivable</b9><b10></b10><b11></b11><b12></b12><b13></b13><b14></b14><b15></b15><b16></b16><b17></b17><b35>false</b35><b36>Center</b36><b37>Center</b37><a31></a31><a32>1</a32><a33>false</a33><a34>false</a34><a35>0</a35><a36></a36><a37></a37><a38></a38><a39>false</a39><a40>false</a40><a21>false</a21><a41>false</a41><a42>clskyblue</a42><a43>[Tahoma,9,clBlack,,True,False,False,False]</a43><a44>[Tahoma,8,clBlack,,True,False,False,False]</a44><a45>[Tahoma,8,clBlack,,True,False,False,False]</a45><a46>$00F3AFA0</a46><a47>[Tahoma,8,clBlack,,True,False,False,False]</a47><a48>$00EEF1F2</a48><a49>$00E2E8E9</a49><a50>18</a50><a60>1</a60><b18></b18><b21></b21><b23></b23><b22>0</b22><b38>Classic</b38><b39>None</b39><a65>false</a65><a66>false</a66></iview><scripts cat="actions"><open script="true" cap="open" type="iview" apply="Current Row " applyon="" sname="accrecv" desc="" failmessage="" validate="no" web="no" breakonerror="no" localnum="2"><r1 id="a1" op="5" task="scripts" type="" sname="" apply="" applyon=""><param1 task="scripts" op="7"><exprset><l0>LoadIView({outcusin},{pbranchname=:pbranchname~asondate=:asondate~pcustomer=:subledgerparam~slab1=:slab1~slab2=:slab2~slab3=:slab3~slab4=:slab4~slab5=:slab5~pdues=:pdues~preportby=:preportby~psalesmanstate=:salesmenstate},{d},{True})</l0></exprset></param1></r1></open></scripts><comps cat="comps" dwbtb="true" LocalNum="9" btn="6" vupd="" pnlheight="35"><btn1 key="btn1" caption="Print" cat="btn" tlhw="7,1,20,20" parent="btnPanel" font="Tahoma,8,clWindowText,ffff" def="right" task="print" action="" container="" sname="" flat="true" position="Left" visible="true" footer="false" hint="Print" down=""><icon><text>list</text><addClass>material-icons</addClass></icon></btn1><btn2 key="btn2" caption="Preview" cat="btn" tlhw="7,1,20,20" parent="btnPanel" font="Tahoma,8,clWindowText,ffff" def="right" task="preview" action="" container="" sname="" flat="true" position="Left" visible="true" footer="false" hint="Preview" down=""><icon><text>video_label</text><addClass>material-icons</addClass></icon></btn2><btn3 key="btn3" caption="Page Setup / Printer Setting" cat="btn" tlhw="7,1,20,20" parent="btnPanel" font="Tahoma,8,clWindowText,ffff" def="right" task="printersetting" action="" container="" sname="" flat="true" position="Left" visible="true" footer="false" hint="Page Setup / Printer Setting" down=""><icon><text>import_contacts</text><addClass>material-icons</addClass></icon></btn3><btn4 key="btn4" caption="View" cat="btn" tlhw="7,1,20,20" parent="btnPanel" font="Tahoma,8,clWindowText,ffff" def="right" task="view" action="" container="" sname="" flat="true" position="Left" visible="true" footer="false" hint="View" down=""><icon><text>remove_red_eye</text><addClass>material-icons</addClass></icon></btn4><btn5 key="btn5" caption="Find" cat="btn" tlhw="7,1,20,20" parent="btnPanel" font="Tahoma,8,clWindowText,ffff" def="right" task="find" action="" container="" sname="" flat="true" position="Left" visible="true" footer="false" hint="Find" down=""><icon><text>search</text><addClass>material-icons</addClass></icon></btn5><btn6 key="btn6" caption="Tasks" cat="btn" tlhw="7,1,20,20" parent="btnPanel" font="Tahoma,8,clWindowText,ffff" def="right" task="tasks" action="" container="" sname="" flat="true" position="Left" visible="true" footer="false" hint="Tasks" down="" folder="true"><icon><text>receipt</text><addClass>material-icons</addClass></icon></btn6><x__head caption="Accounts Receivable" cat="txt" parent="pnlButton" color="$00F2F0F0" align="none" def="left" tlhw="7,5,19,53" font="_Tahoma,,,clWindowText" type="pnl"/></comps><row1 cat="sql"><a1>Task1</a1><a2><l0>select </l0><l1>a.accountname,</l1><l2>a.subledgername, </l2><l3>a.mg_accountid, </l3><l4>max(a.mg_subledgerid) as mg_subledgerid,</l4><l5>sum(a.amount) as amount,  </l5><l6>sum(a.outstanding_amount) as outstanding_amount,</l6><l7>sum(a.mslab0) as mslab0, </l7><l8>sum(a.mslab1) as mslab1, </l8><l9>sum(a.mslab2) as mslab2, </l9><l10>sum(a.mslab3) as mslab3, </l10><l11>sum(a.mslab4) as mslab4, </l11><l12>case when :preportby = ''By Customer'' then a.subledgername else ''ALL'' end as subledgerparam,</l12><l13>case when :preportby != ''By Customer'' then max(a.salesmenstate) else ''ALL'' end as  salesmenstate</l13><l14>from</l14><l15>(</l15><l16>select </l16><l17>a.arapdetailsid, </l17><l18>a.sourceid, </l18><l19>a.transid, </l19><l20>a.mg_accountid, </l20><l21>a.mg_subledgerid,  </l21><l22>a.accountname,</l22><l23>a.subledgername, </l23><l24>a.branchname, </l24><l25>func_returns_hyperlink( a.docid,''formpage'',a.stransid,a.sourceheaderid,(select t.caption from tstructs t where t.name = a.stransid)) as docid,</l25><l26>a.docid as mdocid,</l26><l27>a.docdate, </l27><l28>a.creditdays, </l28><l29>a.due_date, </l29><l30>a.amount,</l30><l31>a.setamount, </l31><l32>a.outstanding_amount,  </l32><l33>a.outstanding_days, </l33><l34>case when (a.outstanding_days &lt;= 0 or a.outstanding_amount  &lt;= 0) then a.outstanding_amount else 0 end as mslab0,  </l34><l35>case when a.outstanding_days &lt;= a.mslab1 and a.outstanding_amount &gt; 0 and a.outstanding_days &gt; 0 then a.outstanding_amount  else 0 end as mslab1, </l35><l36>case when a.outstanding_days between cast( :slab1 as numeric) + 1 and :slab2 and a.outstanding_amount  &gt; 0 then a.outstanding_amount else 0 end as mslab2,</l36><l37>case when a.outstanding_days between cast( :slab2 as numeric) + 1 and :slab3 and a.outstanding_amount  &gt; 0 then a.outstanding_amount else 0 end as mslab3,</l37><l38>case when a.outstanding_days &gt; cast( :slab3 as numeric) and a.outstanding_amount  &gt; 0 then a.outstanding_amount else 0 end as mslab4,</l38><l39>case when a.outstanding_days between cast( :slab4 as numeric) + 1 and :slab5 and a.outstanding_amount  &gt; 0 then a.outstanding_amount else 0 end as mslab5,</l39><l40>case when a.outstanding_days &gt; cast( :slab5 as numeric) and a.outstanding_amount  &gt; 0 then a.outstanding_amount else 0 end as mslab6, </l40><l41>a.salesmenstate</l41><l42>from (</l42><l43>select a.arapdetailsid, </l43><l44>a.sourceid, </l44><l45>substring(a.mapname FROM ''[A-Za-z]+'')as transid,  </l45><l46>(select substring(e.mapname FROM ''[A-Za-z]+'') from accountsdtl d, accountshdr e where a.sourceid = d.accountsdtlid and e.accountshdrid = d.accountshdrid) as stransid,</l46><l47>m.mg_accountid, </l47><l48>s.mg_subledgerid,  </l48><l49>(select e.sourceid from accountsdtl d, accountshdr e where a.sourceid = d.accountsdtlid and e.accountshdrid = d.accountshdrid) as sourceheaderid, </l49><l50>m.accountname,</l50><l51>case when :preportby = ''By Customer'' then  s.subledgername</l51><l52>     when :preportby = ''By State/Province'' then s.statejurisdiction</l52><l53>     when :preportby = ''By Salesmen'' then s.salesman</l53><l54>end as subledgername,     </l54><l55>case when :preportby = ''By State/Province'' then s.statejurisdiction</l55><l56>     when :preportby = ''By Salesmen'' then s.salesman  </l56><l57>     else ''ALL'' end </l57><l58>as salesmenstate,  </l58><l59>br.branchname, </l59><l60>a.docid, a.docdate, </l60><l61>cast( :asondate as date) as asondate,</l61><l62>case when a.amount &gt; 0 then a.creditdays else 0 end as creditdays,</l62><l63>case when a.amount &gt; 0 then a.docdate + interval ''1day'' * a.creditdays else a.docdate end as due_date,</l63><l64>case when cast( :pcurrency as text) = ''ALL'' then a.bamount else a.namount end as amount,   </l64><l65>case when cast( :pcurrency as text) = ''ALL'' then cast( a.bamount + coalesce ( b.bamount,0) as numeric) else cast( a.namount + coalesce ( b.namount,0) as numeric) </l65><l66>end as outstanding_amount, </l66><l67>case when cast( :pcurrency as text) = ''ALL'' then coalesce(b.bamount,0) else coalesce(b.namount,0) end as setamount,</l67><l68>case when a.amount &gt; 0 then </l68><l69>case when cast( :pdues as text) = ''Over Dues'' then cast( cast( :asondate as date) - cast( a.docdate + interval ''1day'' * a.creditdays as date)  as numeric)</l69><l70>else  cast( :asondate as date) - a.docdate end </l70><l71>else 0 end as outstanding_days,  </l71><l72>cast( :slab1 as numeric) as mslab1, </l72><l73>cast( :slab2 as numeric) as mslab2, </l73><l74>cast( :slab3 as numeric) as mslab3, </l74><l75>cast( :slab4 as numeric) as mslab4, </l75><l76>cast( :slab5 as numeric) as mslab5</l76><l77>from arapdetails a</l77><l78>join branch br on ( a.branch = br.branchid ) </l78><l79>left join (</l79><l80>select b.accountname, b.subledgername, </l80><l81>b.refno, max(b.refdate) as refdate, </l81><l82>sum(b.amount) as amount, </l82><l83>sum(b.bamount) as bamount, sum(b.namount) as namount</l83><l84>from arapadjustments b </l84><l85>where b.cancel = ''F''</l85><l86>and b.company = cast( :pcompanyid as numeric )</l86><l87>group by b.accountname, b.subledgername, b.refno</l87><l88>) b on ( a.subledgercode = b.subledgername </l88><l89> and a.docid = b.refno </l89><l90> and a.docdate &lt;= :asondate</l90><l91> and a.accountname = b.accountname</l91><l92> )</l92><l93> join mg_subledger s on ( a.subledgercode = s.mg_subledgerid  )</l93><l94> join mg_account m on ( s.controlaccount = m.mg_accountid and m.acatcode = ''r'' )</l94><l95> join currency c on ( m.acurrency = c.currencyid)</l95><l96>where a.cancel = ''F''</l96><l97>and  a.app_desc = 1</l97><l98>and a.company  = cast( :pcompanyid as numeric )</l98><l99>and (c.currency = cast( :pcurrency as text) or cast( :pcurrency as text) = ''ALL'')</l99><l100>and (br.branchname = cast( :pbranchname as text) or cast( :pbranchname as text) = ''ALL'') </l100><l101>and a.docdate &lt;= :asondate</l101><l102>) a</l102><l103>where a.outstanding_amount != 0 </l103><l104>) a</l104><l105>group by a.accountname,</l105><l106>a.subledgername,</l106><l107>a.mg_accountid</l107><l108>order by accountname, subledgername</l108></a2><a3></a3><a4>reportsql</a4></row1><pcompanyid cat="params" ord="1"><a1>Task1</a1><a0>pcompanyid</a0><a2>pcompanyid</a2><a4>Numeric</a4><a9>false</a9><a6 sugg="false">m_companyid</a6><a10></a10><a21>true</a21><a11></a11><a5>0</a5><a12>true</a12><a14>false</a14><a56></a56><a13>Accept</a13><a15><s>pcurrency</s></a15><a67>325</a67><a68>false</a68></pcompanyid><pbranchname cat="params" ord="2"><a1>Task1</a1><a0>pbranchname</a0><a2>Branch</a2><a4>Character</a4><a9>false</a9><a6 sugg="false">m_branch</a6><a10></a10><a21>false</a21><a11 pcount="0">select a.branchname
from vw_userbranchlocations a
where a.username = :username 
and a.companyid = cast( :m_companyid as numeric)
union 
select ''ALL'' as branchname from dual 
order by 1</a11><a5>0</a5><a12>true</a12><a14>false</a14><a56></a56><a13>Select</a13><a15></a15><a67>325</a67><a68>false</a68></pbranchname><pcurrency cat="params" ord="3"><a1>Task1</a1><a0>pcurrency</a0><a2>Currency</a2><a4>Character</a4><a9>false</a9><a6 sugg="false">m_currency</a6><a10></a10><a21>false</a21><a11 pcount="1">select distinct b.currency from currency b, mg_account c 
where c.company = cast( :pcompanyid as numeric) and
c.acurrency = b.currencyid and 
c.acatcode = ''r''
union 
select ''ALL'' as currency 
order by 1
</a11><a5>0</a5><a12>true</a12><a14>false</a14><a56></a56><a13>Select</a13><a15></a15><a67>325</a67><a68>false</a68></pcurrency><pdues cat="params" ord="4"><a1>Task1</a1><a0>pdues</a0><a2>Status</a2><a4>Character</a4><a9>false</a9><a6 sugg="false">{Over Dues}</a6><a10></a10><a21>false</a21><a11>SELECT ''Dues'' AS CHOICE 
union 
select ''Over Dues'' as choice 
order by 1
</a11><a5>0</a5><a12>true</a12><a14>false</a14><a56></a56><a13>Select</a13><a15></a15><a67>325</a67><a68>false</a68></pdues><preportby cat="params" ord="5"><a1>Task1</a1><a0>preportby</a0><a2>Report By</a2><a4>Character</a4><a9>false</a9><a6 sugg="false">{By Customer}</a6><a10></a10><a21>false</a21><a11>select ''By Customer'' as choice 
union 
select ''By Salesmen'' as choice
union
select ''By State/Province'' as choice 
