		<a11></a11>
		<a5>0</a5>
		<a12>true</a12>
		<a14>false</a14>
		<a56></a56>
		<a13>Accept</a13>
		<a15>
			<s>pcurrency,psalesmanstate,pcustomer</s></a15>
		<a67>325</a67>
		<a68>false</a68>
	</pcompanyid>
	<pbranchname cat="params" ord="2">
		<a1>Task1</a1>
		<a0>pbranchname</a0>
		<a2>Branch</a2>
		<a4>Character</a4>
		<a9>false</a9>
		<a6 sugg="false">m_branch</a6>
		<a10></a10>
		<a21>false</a21>
		<a11 pcount="0">select a.branchname
from vw_userbranchlocations a
where a.username = :username 
and a.companyid = cast( :m_companyid as numeric)
union 
select ''ALL'' as branchname from dual 
order by 1</a11>
		<a5>0</a5>
		<a12>true</a12>
		<a14>false</a14>
		<a56></a56>
		<a13>Select</a13>
