	<row1 cat="sql">
		<a1>Task1</a1>
		<a2>
			<l0>select to_char( a.docdate,''Month'') as months,br.branchname,sum(b.cramount) as cramount</l0>
			<l1>from deposit a</l1>
			<l2>join depositaccountdtl b on  a.depositid = b.depositid</l2>
			<l3>join mg_account c on c.mg_accountid = b.accountname</l3>
			<l4>join branch br on br.branchid = a.branch</l4>
			<l5>where a.cancel = ''F''</l5>
			<l6>and a.app_desc = 1 </l6>
			<l7>and b.cramount &gt; 0</l7>
			<l8>and a.company = cast( :companyid as numeric)</l8>
			<l9>and (br.branchname = :pbranch or :pbranch = ''ALL'')</l9>
			<l10>AND (a.docdate BETWEEN cast( :pfromdate as date) AND cast( :ptodate as date))</l10>
			<l11>group by  to_char( a.docdate,''Month'') ,br.branchname</l11>
			<l12>order by 1</l12>
		</a2>
		<a3></a3>
		<a4>reportsql</a4>
	</row1>
