= y.accountshdrid </l2><l3>join mg_account m1 on (m1.mg_accountid = y.accountname and m1.acatcode = ''o'' and alie = ''2'') </l3><l4>join branch br on br.branchid = x.branch</l4><l5>where x.cancel = ''F''</l5><l6>and x.app_desc = 1</l6><l7>and x.company = cast( :pcompanyid as numeric )</l7><l8>and (br.branchname = :pbranch or :pbranch = ''ALL'')</l8><l9>AND (x.docdate BETWEEN cast( :pfromdate as date) AND cast( :ptodate as date))</l9><l10>group by m1.accountname</l10><l11>order by 1</l11></a2><a3></a3><a4>reportsql</a4></row1><pcompanyid cat="params" ord="1"><a1>Task1</a1><a0>pcompanyid</a0><a2>Company</a2><a4>Numeric</a4><a9>false</a9><a6 sugg="false">m_companyid</a6><a10></a10><a21>true</a21><a11></a11><a5>0</a5><a12>true</a12><a14>false</a14><a56></a56><a13>Accept</a13><a15></a15><a67>325</a67><a68>false</a68></pcompanyid><pbranch cat="params" ord="2"><a1>Task1</a1><a0>pbranch</a0><a2>Branch</a2><a4>Character</a4><a9>false</a9><a6 sugg="false">{ALL}</a6><a10></a10><a21>false</a21><a11 pcount="0">select a.branchname from vw_userbranchlocations a 
