	<row1 cat="sql">
		<a1>Task1</a1>
		<a2>
			<l0>select * </l0>
			<l1>from (</l1>
			<l2>select s.*, </l2>
			<l3>m.inward as batch_inward, m.outward as batch_outward, </l3>
			<l4>case when s.stock_inward != m.inward then ''Batch Master inward error''  </l4>
			<l5>     when s.stock_outward != m.outward then ''Batch master outward error'' </l5>
			<l6>     else ''No error''</l6>
			<l7>end as batchmastererror</l7>
			<l8>from</l8>
			<l9>(select b.branchname, c.locationname, i.itemname, i.itemcode, </l9>
			<l10>i.itemid, </l10>
			<l11>c.locationid,</l11>
			<l12>sum(case when upper( a.plusorminus ) =''P'' then qty else 0 end) as stock_inward,</l12>
			<l13>sum(case when upper( a.plusorminus ) =''M'' and a.stock_qty != 0 then qty else 0 end) as stock_outward,</l13>
			<l14>sum(a.stock_qty) as stock_qty</l14>
			<l15>from stockvalue a, branch b, location c, item i</l15>
			<l16>where a.cancel = ''F''</l16>
			<l17>and a.branch = b.branchid </l17>
			<l18>and a.location = c.locationid</l18>
			<l19>and a.itemname = i.itemid</l19>
			<l20>group by b.branchname, c.locationname, i.itemname, i.itemcode, </l20>
			<l21>i.itemid, </l21>
			<l22>c.locationid) S </l22>
			<l23>left outer join (select location, itemname, sum(inward) as inward, sum(outward) as outward from batchmaster m group by location, itemname) m  </l23>
			<l24>on ( s.locationid = m.location and s.itemid = m.itemname )</l24>
			<l25>) A</l25>
			<l26>where (a.stock_inward != a.batch_inward or a.stock_outward != a.batch_outward)  </l26>
			<l27>order by A.locationname, a.itemname</l27>
		</a2>
		<a3></a3>
		<a4>reportsql</a4>
	</row1>
