	<row1 cat="sql">
		<a1>Task1</a1>
		<a2>
			<l0>select a1.sessionid,func_returns_hyperlink( fn_findheaderdocid(a1.structname,a1.recordid),''formpage'',a1.structname,a1.recordid,t.caption) as docid ,a1.calledon,t.caption,a1.recordid,a1.timetaken,a1.dbtimetaken,a1.servicename,a1.callfinished </l0>
			<l1>from axaudit a</l1>
			<l2>join  axpertlog a1 on a.sessionid =a1.sessionid </l2>
			<l3>join tstructs t on t.name = a1.structname</l3>
			<l4>where a1.sessionid = :psessionid</l4>
			<l5>and date_trunc(''day'', a.logintime) between :fromdate and :todate </l5>
			<l6>order by a1.calledon </l6>
		</a2>
		<a3></a3>
		<a4>reportsql</a4>
	</row1>
