	<row1 cat="sql">
		<a1>Task1</a1>
		<a2>
			<l0>select b.username, a.sessionid ,b.nickname, a.logintime, a.logouttime, a.ip, a.other, :fromdate as pfromdate, :todate as ptodate</l0>
			<l1>from axaudit a, axusers b </l1>
			<l2>where date_trunc(''day'', a.logintime) between :fromdate and :todate</l2>
			<l3>and a.username = b.username </l3>
			<l4>and b.username = :pusername</l4>
			<l5>order by a.username, a.logintime desc</l5>
		</a2>
		<a3></a3>
		<a4>reportsql</a4>
	</row1>
