	<row1 cat="sql">
		<a1>Task1</a1>
		<a2>
			<l0>select a.categoryname, a.productcategory, a.brand_name, a.itemdesc, sum(a.bill_qty) as bill_qty, sum(a.gross_amount) as gross_amount, sum(a.discount) as discount,</l0>
			<l1>sum(a.taxableamount) as taxableamount, sum(a.net_amount) as net_amount</l1>
			<l2>from</l2>
			<l3>(select a.categoryname, a.productcategory, a.brand_name,  sum(a.qty) as bill_qty, sum(a.grossamount) as gross_amount, sum(a.discamount) as discount,</l3>
			<l4>sum(a.taxableamount) as taxableamount, sum(a.netamount) as net_amount,</l4>
			<l5>case when :preportby = ''Currency wise'' then a.currency</l5>
			<l6> 	 when :preportby = ''Supplier wise'' then a.supplier</l6>
			<l7>     when :preportby = ''Branch wise'' then a.branchname</l7>
			<l8>     WHEN :preportby = ''Monthly Purchase'' THEN cast(cast( CURRENT_DATE  - INTERVAL ''30 DAY'' as date) as varchar) || '' to '' || cast(cast(current_date as date) as varchar)</l8>
			<l9>                WHEN :preportby = ''Daily Purchase'' THEN cast(cast( CURRENT_DATE as date) as varchar) || '' to '' || cast(cast(current_date as date) as varchar)</l9>
			<l10>                WHEN :preportby = ''Yearly Purchase'' THEN cast(cast( CURRENT_DATE  - INTERVAL ''365 DAY'' as date) as varchar) || '' to '' || cast(cast(current_date as date) as varchar)</l10>
			<l11> 	end as itemdesc </l11>
			<l12>from vw_purchase_items a</l12>
			<l13>where  a.company = cast( :pcompanyid as numeric)</l13>
			<l14>and a.itemdesc = :pitemname</l14>
			<l15>AND a.docdate BETWEEN </l15>
			<l16>            (CASE </l16>
			<l17>                WHEN :preportby = ''Monthly Purchase'' THEN CURRENT_DATE - INTERVAL ''30 DAY''</l17>
			<l18>                WHEN :preportby = ''Daily Purchase'' THEN CURRENT_DATE</l18>
			<l19>                WHEN :preportby = ''Yearly Purchase'' THEN CURRENT_DATE - INTERVAL ''365 DAY''</l19>
			<l20>                ELSE cast( :pfromdate as date) end) AND cast( :ptodate as date)</l20>
			<l21>group by a.categoryname, a.productcategory, a.brand_name, a.supplier,a.branchname,a.currency)a</l21>
			<l22>group by a.categoryname, a.productcategory, a.brand_name, a.itemdesc</l22>
			<l23>order by 1,2,4</l23>
		</a2>
		<a3></a3>
		<a4>reportsql</a4>
	</row1>
