	</pcompanyid>
	<preportby cat="params" ord="2">
		<a1>Task1</a1>
		<a0>preportby</a0>
		<a2>Reported By</a2>
		<a4>Character</a4>
		<a9>false</a9>
		<a6 sugg="false"></a6>
		<a10></a10>
		<a21>false</a21>
		<a11>select ''Currecy wise'' as option from dual 
UNION
select ''Supplier wise'' as option from dual 
UNION
select ''Branch wise'' as option from dual 
UNION
select ''Monthly Purchase'' as option from dual 
UNION
select ''Daily Purchase'' as option from dual 
UNION
select ''Yearly Purchase'' as option from dual 
order by option</a11>
		<a5>0</a5>
		<a12>true</a12>
		<a14>false</a14>
		<a56></a56>
		<a13>Select</a13>
		<a15>
			<s>pfromdate</s></a15>
		<a67>325</a67>
		<a68>false</a68>
	</preportby>
