	<row1 cat="sql">
		<a1>Task1</a1>
		<a2>
			<l0>select i.itemid, i.itemdesc, </l0>
			<l1>func_returns_hyperlink( i.itemname ,''formpage'',i.transid,i.itemid,''Product Master'') as itemname, </l1>
			<l2>i.itemcode,i.uom, a.total_qty as total_qty,</l2>
			<l3>d.pivotlink as pivot, d.closing_qty </l3>
			<l4>from (select a.itemid itemname,   </l4>
			<l5>sum(a.received_qty + a.issued_qty) as total_qty</l5>
			<l6>from mv_stockdetails a</l6>
			<l7>where  a.company = :pcompanyid </l7>
			<l8>and a.branchname =  :pbranch</l8>
			<l9>and (a.locationname = :plocation or :plocation = ''ALL'')</l9>
			<l10>group by a.itemid </l10>
			<l11>order by itemname</l11>
			<l12>) a</l12>
			<l13>left join (select a.itemid,  </l13>
			<l14>sum(a.received_qty + a.issued_qty) closing_qty, </l14>
			<l15>concat( a.branchname,''^'', a.locationname) as pivotlink</l15>
			<l16>from mv_stockdetails a</l16>
			<l17>where a.company = :pcompanyid </l17>
			<l18>and a.branchname = :pbranch</l18>
			<l19>and (a.locationname = :plocation or :plocation = ''ALL'')</l19>
			<l20>group by a.itemid, concat( a.branchname,''^'', a.locationname)</l20>
			<l21>) d on  (a.itemname = d.itemid), item i </l21>
			<l22>where a.itemname  = i.itemid  </l22>
			<l23>and i.itemid != 1 </l23>
			<l24>  and a.total_qty &gt; 0</l24>
			<l25>order by itemdesc, pivot</l25>
		</a2>
		<a3></a3>
		<a4>reportsql</a4>
	</row1>
