	<row1 cat="sql">
		<a1>Task1</a1>
		<a2>
			<l0>select categoryname,brand_name,subcategory,itemdesc,sellingunit,applicability,effective_from,itemcode,primarysellingrate,sellingpriceid</l0>
			<l1>from (</l1>
			<l2>select b.categoryname, c.brand_name, d.productcategory as subcategory,</l2>
			<l3>a.itemdesc, </l3>
			<l4>a.sellingunit, CASE</l4>
			<l5>            WHEN s.by_customer = ''T'' AND s.by_branch = ''T''</l5>
			<l6>                THEN ''Customers - '' || s.selected_customers || '' | Branches - '' || s.selected_branches</l6>
			<l7>            WHEN s.by_customer = ''T'' and s.by_branch = ''F''</l7>
			<l8>                THEN ''Customers - '' || s.selected_customers</l8>
			<l9>            WHEN s.by_branch = ''T'' and s.by_customer = ''F'' </l9>
			<l10>                THEN ''Branches - '' || s.selected_branches</l10>
			<l11>            ELSE ''All Customers &amp; All Branches''</l11>
			<l12>        END AS applicability,</l12>
			<l13>s.fromdt as effective_from, </l13>
			<l14> a.itemcode as itemcode, </l14>
			<l15>s.primarysellingrate ,s.sellingpriceid,</l15>
			<l16>   ROW_NUMBER() OVER (</l16>
			<l17>            PARTITION BY</l17>
			<l18>                a.itemdesc,</l18>
			<l19>                COALESCE(s.selected_branches,  ''''),</l19>
			<l20>                COALESCE(s.selected_customers, '''')</l20>
			<l21>            ORDER BY s.fromdt DESC</l21>
			<l22>        ) AS rn</l22>
			<l23>from item a, itemcategory b, brand_master c, productcategory d, sellingprice s</l23>
			<l24>where a.itemcategory = b.itemcategoryid  </l24>
			<l25>and a.itembrand = c.brand_masterid </l25>
			<l26>and a.productcategory = d.productcategoryid </l26>
			<l27>and a.itemid = s.itemname </l27>
			<l28>and a.active  = ''T''</l28>
			<l29>and s.active = ''T'' </l29>
			<l30>and s.app_desc = 1</l30>
			<l31>and ( b.categoryname = :pcategoryname or :pcategoryname = ''ALL'')  </l31>
			<l32>and ( c.brand_name = :pbrandname or :pbrandname = ''ALL'')</l32>
			<l33>and (d.productcategory = :pproductcategory or :pproductcategory = ''ALL'')</l33>
			<l34>and a.company = cast( :pcompany as numeric) ) a</l34>
			<l35>where rn = 1</l35>
			<l36>order by 1,2,3, a.itemdesc,effective_from desc</l36>
		</a2>
		<a3></a3>
		<a4>reportsql</a4>
	</row1>
