	<row1 cat="sql">
		<a1>Task1</a1>
		<a2>
			<l0>select a.voucher_date,</l0>
			<l1>a.branchname,</l1>
			<l2>a.vouchertype, </l2>
			<l3>case when a.sourceid = 0 then a.accountshdrid else a.sourceid end as recordid, </l3>
			<l4>a.accountshdrid, </l4>
			<l5>''t''||a.transid as transid, </l5>
			<l6>a.accountname,</l6>
			<l7>a.subledgername, </l7>
			<l8>a.voucher_number, </l8>
			<l9>a.base_credit as base_debit, </l9>
			<l10>a.base_debit as base_credit, </l10>
			<l11>coalesce( </l11>
			<l12>''&lt;span style="font-weight:bold;"&gt;''||''SBU/Branch ''||''&lt;/span&gt;''||a.branchname||''&lt;br/&gt;'' </l12>
			<l13>||case when (a.reference_number is not null or a.reference_date is not null) then </l13>
			<l14>''&lt;span style="font-weight:bold;"&gt;''||''Ref#/Date ''||''&lt;/span&gt;''||</l14>
			<l15>coalesce (a.reference_number,'' '') ||''-''||to_char(a.reference_date,''dd/mm/yyyy'')||''&lt;br/&gt;'' end, '' '')</l15>
			<l16>||</l16>
			<l17>coalesce( case when (a.cheque_number is not null or a.cheque_date is not null) then </l17>
			<l18>''&lt;span style="font-weight:bold;"&gt;''||''Chq#/Date ''||''&lt;/span&gt;''||</l18>
			<l19>coalesce (a.cheque_number,'' '')||''-''||to_char(a.cheque_date,''dd/mm/yyyy'')||''&lt;br/&gt;'' end, '' '')</l19>
			<l20>||</l20>
			<l21>coalesce (case when a.narration is not null then ''&lt;span style="font-style:italic;"&gt;''||a.narration||''&lt;/span&gt;''||''&lt;br/&gt;'' end ,'' '')</l21>
			<l22>as details, </l22>
			<l23>2 as id,</l23>
			<l24>''Less: Cheques Sent for Collection but not yet Credited'' as tag</l24>
			<l25>from mv_accountsdetails a</l25>
			<l26>where a.voucher_date &lt;=  cast( :asondate as date)</l26>
			<l27>and (a.branchname = cast( :pbranchname as text) or cast( :pbranchname as text)= ''ALL'')</l27>
			<l28>and a.company = cast( :pcompanyid as numeric)  </l28>
			<l29>and a.accountname = :mpaccountname </l29>
			<l30>and (a.base_debit - a.base_credit &gt; 0)</l30>
			<l31>and (a.reconciled = ''F'' or ( a.reconciled = ''T'' and a.reconciled_date &gt; cast( :asondate as date)))</l31>
			<l32>union all                            </l32>
			<l33>select a.voucher_date,</l33>
			<l34>a.branchname,</l34>
			<l35>a.vouchertype, </l35>
			<l36>case when a.sourceid = 0 then a.accountshdrid else a.sourceid end as recordid, </l36>
			<l37>a.accountshdrid, </l37>
			<l38>''t''||a.transid as transid, </l38>
			<l39>a.accountname,</l39>
			<l40>a.subledgername, </l40>
			<l41>a.voucher_number, </l41>
			<l42>a.base_credit as base_debit, </l42>
			<l43>a.base_debit as base_credit, </l43>
			<l44>coalesce( </l44>
			<l45>''&lt;span style="font-weight:bold;"&gt;''||''SBU/Branch ''||''&lt;/span&gt;''||a.branchname||''&lt;br/&gt;'' </l45>
			<l46>||case when (a.reference_number is not null or a.reference_date is not null) then </l46>
			<l47>''&lt;span style="font-weight:bold;"&gt;''||''Ref#/Date ''||''&lt;/span&gt;''||</l47>
			<l48>coalesce (a.reference_number,'' '') ||''-''||to_char(a.reference_date,''dd/mm/yyyy'')||''&lt;br/&gt;'' end, '' '')</l48>
			<l49>||</l49>
			<l50>coalesce( case when (a.cheque_number is not null or a.cheque_date is not null) then </l50>
			<l51>''&lt;span style="font-weight:bold;"&gt;''||''Chq#/Date ''||''&lt;/span&gt;''||</l51>
			<l52>coalesce (a.cheque_number,'' '')||''-''||to_char(a.cheque_date,''dd/mm/yyyy'')||''&lt;br/&gt;'' end, '' '')</l52>
			<l53>||</l53>
			<l54>coalesce (case when a.narration is not null then ''&lt;span style="font-style:italic;"&gt;''||a.narration||''&lt;/span&gt;''||''&lt;br/&gt;'' end ,'' '')</l54>
			<l55>as details, </l55>
			<l56>1 as id,</l56>
			<l57>''Add: Cheques Issued but not yet presented'' as tag</l57>
			<l58>from mv_accountsdetails a</l58>
			<l59>where a.voucher_date &lt;=  cast( :asondate as date)</l59>
			<l60>and (a.branchname = cast( :pbranchname as text) or cast( :pbranchname as text)= ''ALL'')</l60>
			<l61>and a.company = cast( :pcompanyid as numeric)  </l61>
			<l62>and a.accountname = :mpaccountname </l62>
			<l63>and (a.base_debit - a.base_credit &lt; 0)</l63>
			<l64>and (a.reconciled = ''F'' or ( a.reconciled = ''T'' and a.reconciled_date &gt; cast( :asondate as date)))</l64>
			<l65>union all</l65>
			<l66>select cast( null as date) as voucher_date,</l66>
			<l67>:pbranchname as branchname,</l67>
			<l68>'''' vouchertype, </l68>
			<l69>0 as recordid, </l69>
			<l70>0 as accountshdrid, </l70>
			<l71>'''' as transid, </l71>
			<l72>a.accountname,</l72>
			<l73>''''subledgername, </l73>
			<l74>'''' voucher_number, </l74>
			<l75>case when sum(a.base_debit-a.base_credit) &gt; 0 then sum(a.base_debit-a.base_credit) else 0 end as base_debit,</l75>
			<l76>case when sum(a.base_debit-a.base_credit) &lt; 0 then cast( -sum(a.base_debit-a.base_credit) as numeric) else 0 end as base_credit,</l76>
			<l77>''&lt;span style="font-weight:bold;"&gt;''||''Bank Balance as per Bank Book as On ''||''&lt;/span&gt;''||to_char( :asondate,''dd/mm/yyyy'')</l77>
			<l78>as details, </l78>
			<l79>0 as id, </l79>
			<l80>'''' as tag</l80>
			<l81>from mv_accountsdetails a</l81>
			<l82>where a.voucher_date &lt;=  cast( :asondate as date)</l82>
			<l83>and (a.branchname = cast( :pbranchname as text) or cast( :pbranchname as text)= ''ALL'')</l83>
			<l84>and a.company = cast( :pcompanyid as numeric)  </l84>
			<l85>and a.accountname = :mpaccountname </l85>
			<l86>group by a.accountname</l86>
			<l87>union all </l87>
			<l88>select a.voucher_date, a.branchname, a.vouchertype, a.recordid, a.accountshdrid, a.transid, a.accountname, </l88>
			<l89>a.subledgername, a.voucher_number, </l89>
			<l90>case when sum(a.debit-a.credit) &gt; 0 then sum(a.debit-a.credit) else 0 end as base_debit,</l90>
			<l91>case when sum(a.debit-a.credit) &lt; 0 then cast( -sum(a.debit-a.credit) as numeric) else 0 end as base_credit,</l91>
			<l92>a.details,  </l92>
			<l93>a.id, </l93>
			<l94>a.tag</l94>
			<l95>from </l95>
			<l96>(</l96>
			<l97>select cast( null as date) as voucher_date,</l97>
			<l98>:pbranchname as branchname,</l98>
			<l99>'''' vouchertype, </l99>
			<l100>0 as recordid, </l100>
			<l101>0 as accountshdrid, </l101>
			<l102>'''' as transid, </l102>
			<l103>a.accountname,</l103>
			<l104>'''' subledgername, </l104>
			<l105>'''' voucher_number, </l105>
			<l106>a.base_debit as debit,</l106>
			<l107>a.base_credit as credit,</l107>
			<l108>''&lt;span style="font-weight:bold;"&gt;''||''Balance as per Pass Book as On ''||''&lt;/span&gt;''||to_char( :asondate,''dd/mm/yyyy'')</l108>
			<l109>as details, </l109>
			<l110>3 as id, </l110>
			<l111>'''' as tag</l111>
			<l112>from mv_accountsdetails a</l112>
			<l113>where a.voucher_date &lt;=  cast( :asondate as date)</l113>
			<l114>and (a.branchname = cast( :pbranchname as text) or cast( :pbranchname as text)= ''ALL'')</l114>
			<l115>and a.company = cast( :pcompanyid as numeric)  </l115>
			<l116>and a.accountname = :mpaccountname </l116>
			<l117>union all </l117>
			<l118>select cast( null as date) as voucher_date,</l118>
			<l119>:pbranchname as branchname,</l119>
			<l120>'''' vouchertype, </l120>
			<l121>0 as recordid, </l121>
			<l122>0 as accountshdrid, </l122>
			<l123>'''' as transid, </l123>
			<l124>a.accountname,</l124>
			<l125>''''subledgername, </l125>
			<l126>''''voucher_number, </l126>
			<l127>case when sum(a.base_debit-a.base_credit) &lt; 0 then cast( -sum(a.base_debit-a.base_credit) as numeric) else 0 end as debit,</l127>
			<l128>case when sum(a.base_debit-a.base_credit) &gt; 0 then sum(a.base_debit-a.base_credit) else 0 end as credit,</l128>
			<l129>''&lt;span style="font-weight:bold;"&gt;''||''Balance as per Pass Book as On ''||''&lt;/span&gt;''||to_char( :asondate,''dd/mm/yyyy'') as details, </l129>
			<l130>3 as id, </l130>
			<l131>'''' as tag</l131>
			<l132>from mv_accountsdetails a</l132>
			<l133>where a.voucher_date &lt;=  cast( :asondate as date)</l133>
			<l134>and (a.branchname = cast( :pbranchname as text) or cast( :pbranchname as text)= ''ALL'')</l134>
			<l135>and a.company = cast( :pcompanyid as numeric)  </l135>
			<l136>and a.accountname = :mpaccountname </l136>
			<l137>and (a.reconciled = ''F'' or ( a.reconciled = ''T'' and a.reconciled_date &gt; cast( :asondate as date)))</l137>
			<l138>group by a.accountname </l138>
			<l139>) a</l139>
			<l140>group by a.accountname, a.voucher_date, a.branchname, a.vouchertype, a.recordid, a.accountshdrid, a.transid, a.accountname, a.subledgername, a.voucher_number, </l140>
			<l141>a.details,  </l141>
			<l142>a.id, </l142>
			<l143>a.tag</l143>
			<l144>order by accountname,id,voucher_date</l144>
		</a2>
		<a3></a3>
		<a4>reportsql</a4>
	</row1>
