	<row1 cat="sql">
		<a1>Task1</a1>
		<a2>
			<l0>select a.sno, a.alie,  </l0>
			<l1>''Actmonthly,Monthly Summary,Script,calendar_month~</l1>
			<l2> dailysum,Daily Summary,Script,calendar_today~''</l2>
			<l3>  ||case when a.acategory in (''Receivable A/c'',''Payable A/c'') </l3>
			<l4>  then ''arapagei,Age Analysis,Script,attach_money~'' else '''' end ||</l4>
			<l5>  ''glsubrep,General Ledger,Script,book''||</l5>
			<l6>  case when a.controlaccount = ''T'' then ''~subledge,Subledger Summary,Script,collections_bookmark'' else '''' end as axrowoptions,     </l6>
			<l7>a.groupname, </l7>
			<l8>a.accountname, </l8>
			<l9>''&lt;span style="margin-left: 20px;"&gt;'' || a.accountname  || ''&lt;/span&gt;'' as maccountname,</l9>
			<l10>b.subledgername,</l10>
			<l11>coalesce (b.OPADB,0) as opadb,</l11>
			<l12>coalesce (b.OPACR,0) as OPACR,</l12>
			<l13>coalesce (b.OPADB) - coalesce(b.OPACR,0) as opbal,</l13>
			<l14>coalesce (b.TRADB,0) as tradb,</l14>
			<l15>coalesce (b.TRACR,0) as tracr,</l15>
			<l16>coalesce (b.CLODB,0) as CLODB,</l16>
			<l17>coalesce (b.CLOCR,0) as CLOCR,</l17>
			<l18>coalesce (b.CLODB,0) - coalesce (b.CLOCR,0) as clbal,</l18>
			<l19>coalesce (b.TRADB,0) - coalesce (b.TRACR,0) as nettransaction,</l19>
			<l20>cast( :pbranchname as text) as mbranchname, </l20>
			<l21>cast( :pstartdate as date) as mstartdate,</l21>
			<l22>cast( :penddate as date) as menddate,</l22>
			<l23>cast( :psubledger as text) as msubledger,</l23>
			<l24>cast( :pbranchlist as text) as mbranchlist, </l24>
			<l25>a.mg_accountid</l25>
			<l26>from 	</l26>
			<l27>(</l27>
			<l28>select * from fn_account_tree( cast( :pcompanyid as numeric) ) </l28>
			<l29>where accountname not in  (''ASSETS'',''LIABILITIES'',''INCOME'',''EXPENSES'') </l29>
			<l30>) a join (</l30>
			<l31>        select</l31>
			<l32>		accountname,</l32>
			<l33>        subledgername, </l33>
			<l34>		SUM (OPADB) as OPADB,</l34>
			<l35>        SUM (OPACR) as OPACR,</l35>
			<l36>		SUM (TRADB) as TRADB,</l36>
			<l37>		SUM (TRACR) as TRACR,</l37>
			<l38>        CASE WHEN (SUM (OPADB) - SUM (OPACR) + SUM (TRADB) - SUM (TRACR)) &gt; 0 then</l38>
			<l39>        SUM (OPADB) - SUM (OPACR) + SUM (TRADB) - SUM (TRACR) ELSE 0 END </l39>
			<l40>        AS CLODB, </l40>
			<l41>        CASE WHEN (SUM (OPADB) - SUM (OPACR) + SUM (TRADB) - SUM (TRACR)) &lt; 0 then (SUM (OPADB) - SUM (OPACR) + SUM (TRADB) - SUM (TRACR))*(1-2) ELSE 0 END </l41>
			<l42>        AS CLOCR</l42>
			<l43>	from</l43>
			<l44>		(		</l44>
			<l45>		select</l45>
			<l46>			b.mg_accountid accountname, </l46>
			<l47>            case when b.controlaccount = ''F'' then '''' else </l47>
			<l48>            ''auto_stories'' end as subledgername,</l48>
			<l49>			(b.base_debit) as OPADB,</l49>
			<l50>            (b.base_credit) as OPACR,</l50>
			<l51>			0 as TRADB,</l51>
			<l52>			0 as TRACR</l52>
			<l53>		from mv_accountmonthlysummary B</l53>
			<l54>		where</l54>
			<l55>			 (b.base_debit - b.base_credit) &lt;&gt; 0</l55>
			<l56>			and b.company = cast( :pcompanyid as numeric)</l56>
			<l57>            and (b.branchname = cast( :pbranchname as text) or cast( :pbranchname as text) = ''ALL'')</l57>
			<l58>            and b.voucher_yearmonth &lt; cast( to_char( :pstartdate, ''YYYYMM'') as  numeric) </l58>
			<l59>            union all</l59>
			<l60>		select b.mg_accountid accountname,</l60>
			<l61>            case when b.controlaccount = ''F'' then '''' else </l61>
			<l62>            ''auto_stories'' end as subledgername,</l62>
			<l63>			0 as OPADB,</l63>
			<l64>            0 as OPACR,</l64>
			<l65>			b.base_debit  as TRADB,</l65>
			<l66>			b.base_credit  as TRACR</l66>
			<l67>		from</l67>
			<l68>			mv_accountmonthlysummary B</l68>
			<l69>            where (b.branchname = cast( :pbranchname as text) or cast( :pbranchname as text)= ''ALL''  )           </l69>
			<l70>			and b.company = cast( :pcompanyid as numeric)           </l70>
			<l71>			and b.voucher_yearmonth between cast( to_char( :pstartdate, ''YYYYMM'') as  numeric) AND </l71>
			<l72>			cast( to_char( :penddate, ''YYYYMM'') as  numeric)</l72>
			<l73>	) a</l73>
			<l74>	group by a.accountname,a.subledgername</l74>
			<l75>) B on	A.mg_accountid  = B.accountname</l75>
			<l76>union all</l76>
			<l77>select 9999 as sno, ''e'' alie,  </l77>
			<l78>''NULL,No Breakup,Script,access_alarms'' as axrowoptions,     </l78>
			<l79>'''' groupname, </l79>
			<l80>'' '' accountname, </l80>
			<l81>''&lt;span style="font-weight:bold;"&gt;&lt;i class="red-text"&gt;Discrepancy in Opening Balance&lt;/i&gt;&lt;/span&gt;'' as maccountname,</l81>
			<l82>'' '' subledgername,</l82>
			<l83>0 as opadb,</l83>
			<l84>0 as OPACR,</l84>
			<l85>-sum(b.base_debit - base_credit) as opbal,</l85>
			<l86>0 as tradb,</l86>
			<l87>0 as tracr,</l87>
			<l88>0 as CLODB,</l88>
			<l89>0 as CLOCR,</l89>
			<l90>-sum (b.base_debit - base_credit) as clbal,</l90>
			<l91>0 as nettransaction,</l91>
			<l92>cast( :pbranchname as text) as mbranchname, </l92>
			<l93>cast( :pstartdate as date) as mstartdate,</l93>
			<l94>cast( :penddate as date) as menddate,</l94>
			<l95>'' '' as msubledger,</l95>
			<l96>cast( :pbranchlist as text) as mbranchlist, </l96>
			<l97>0 mg_accountid</l97>
			<l98>from mv_accountmonthlysummary B</l98>
			<l99>where </l99>
			<l100>(b.branchname = cast( :pbranchname as text) or  cast( :pbranchname as text)= ''ALL''  )           </l100>
			<l101>and b.company = cast( :pcompanyid as numeric)           </l101>
			<l102>and b.voucher_yearmonth &lt; cast( to_char( :pstartdate, ''YYYYMM'') as  numeric) </l102>
			<l103>having sum(b.base_debit - base_credit) != 0</l103>
			<l104>order by alie, sno</l104>
		</a2>
		<a3></a3>
		<a4>reportsql</a4>
	</row1>
