	<row1 cat="sql">
		<a1>Task1</a1>
		<a2>
			<l0>select </l0>
			<l1>''&lt;span style="font-weight:bold;"&gt;''||to_char(a.voucher_date,''dd/mm/yyyy'')||''&lt;/span&gt;'' as voucher_date,</l1>
			<l2>a.branchname,</l2>
			<l3>a.vouchertype, </l3>
			<l4>a.accountshdrid, </l4>
			<l5>''t''||a.otransid as transid, </l5>
			<l6>''t''||a.transid as stransid, </l6>
			<l7>a.sourceid as srecordid, </l7>
			<l8>func_returns_hyperlink( a.voucher_number,''formpage'',a.transid,a.sourceid,b.caption,a.voucher_number) as view_source, 			</l8>
			<l9>''&lt;span style="font-weight:bold;"&gt;''||</l9>
			<l10>case when a.base_debit = 0 then ''Cr  ''else ''Dr  '' end||''&lt;/span&gt;'' || </l10>
			<l11>case when a.subledgername !=''None'' then  ''&lt;span style="font-weight:bold;"&gt;''||a.accountname||''&lt;/span&gt;'' </l11>
			<l12>else a.accountname end||''&lt;br/&gt;''||</l12>
			<l13>coalesce (case when a.subledgername != ''None'' then </l13>
			<l14>          ''&lt;span style="margin-left: 20px; font-style: italic;"&gt;Subledger: '' || a.subledgername || ''&lt;/span&gt;&lt;br/&gt;'' end ,'' '')</l14>
			<l15>as accountname,</l15>
			<l16>a.subledgername, </l16>
			<l17>a.voucher_number,</l17>
			<l18>func_returns_hyperlink( a.voucher_number,''formpage'',a.otransid,a.accountshdrid,b.caption,a.voucher_number)</l18>
			<l19>as mvoucher_number,</l19>
			<l20>a.branchname||''&lt;br/&gt;''||a.vouchertype||''&lt;br/&gt;''</l20>
			<l21>||coalesce( case when a.supply_type is not null then ''&lt;span style="font-weight:bold;"&gt;''||''Supply Type ''||''&lt;/span&gt;''||a.supply_type||''&lt;br/&gt;'' end, '' '')   </l21>
			<l22>||''&lt;/br&gt;''||coalesce( case when (a.reference_number is not null or a.reference_date is not null) then </l22>
			<l23>''&lt;span style="font-weight:bold;"&gt;''||''Ref#/Date ''||''&lt;/span&gt;''||coalesce (a.reference_number,'' '') ||''-''||to_char(a.reference_date,''dd/mm/yyyy'')||''&lt;br/&gt;'' end, '' '')</l23>
			<l24>||coalesce( case when (a.cheque_number is not null or a.cheque_date is not null) then ''&lt;span style="font-weight:bold;"&gt;''||''Chq#/Date ''||''&lt;/span&gt;''</l24>
			<l25>||coalesce (a.cheque_number,'' '')||''-''||to_char(a.cheque_date,''dd/mm/yyyy'')||''&lt;br/&gt;'' end, '' '') </l25>
			<l26>||coalesce (case when a.narration is not null then ''&lt;span style="font-style:italic;"&gt;''||a.narration||''&lt;/span&gt;''||''&lt;br/&gt;'' end ,'' '')</l26>
			<l27>as details,a.base_debit, a.base_credit,1735770000008 recordid, :pdatecriteria as vdatecriteria, :penddate as venddate,</l27>
			<l28>:pstartdate as vstartdate, :pcompanyid as company, :pvouchertype as vvouchertype</l28>
			<l29>from mv_accountsdetails a left join (select name, caption from tstructs a where a.blobno = 1) b on ( a.transid = b.name) </l29>
			<l30>where (( :pdatecriteria = ''By Transaction Date'' and a.voucher_date between  cast( :pstartdate as date) and cast( :penddate as date))</l30>
			<l31>or ( :pdatecriteria =''By Posted Date'' and to_date(to_char(a.modifiedon, ''DD/MM/YYYY''), ''DD/MM/YYYY'')  between cast( :pstartdate as date) and cast( :penddate as date)))   </l31>
			<l32>and a.company = cast( :pcompanyid as numeric)  </l32>
			<l33>and (a.vouchertype = :pvouchertype or :pvouchertype = ''ALL'')</l33>
			<l34>order by  </l34>
			<l35>case when :pdatecriteria = ''By Transaction Date''  then  a.voucher_date else to_date(to_char(a.modifiedon,''dd/mm/yyyy''),''dd/mm/yyyy'') end desc, vouchertype, voucher_number</l35>
		</a2>
		<a3></a3>
		<a4>reportsql</a4>
	</row1>
