		<x__head caption="Monthly Summary of Accounts" cat="txt" parent="pnlButton" color="$00F2F0F0" align="none" def="left" tlhw="7,5,19,53" font="_Tahoma,,,clWindowText" type="pnl"/>
	</comps>
	<row1 cat="sql">
		<a1>Task1</a1>
		<a2>
			<l0>select</l0>
			<l1>	a.monthyear,</l1>
			<l2>	a.monthyearnumeric,</l2>
			<l3>	a.mg_accountid,</l3>
			<l4>	a.accountname,</l4>
			<l5>	a.subledgername,</l5>
			<l6>	sum(a.opening_balance) as opening_balance,</l6>
			<l7>	sum(a.base_debit) as base_debit,</l7>
			<l8>	sum(a.base_credit) as base_credit,</l8>
			<l9>	sum(a.base_debit - a.base_credit ) as net,</l9>
			<l10>	a.monthstartdate,</l10>
			<l11>	a.monthenddate,a.pbranchlist</l11>
			<l12>from</l12>
			<l13>	(</l13>
			<l14>	select</l14>
			<l15>		to_char( a.voucher_date , ''Mon YYYY'' ) as monthyear,</l15>
			<l16>		cast( to_char( a.voucher_date , ''YYYYMM'' ) as numeric) as monthyearnumeric,</l16>
			<l17>		date_trunc(''month'', a.voucher_date) as monthstartdate,</l17>
			<l18>		date_trunc(''month'', a.voucher_date) + interval ''1 month'' - interval ''1 day'' as monthenddate,</l18>
			<l19>		a.branchname ,</l19>
			<l20>		a.accountname,</l20>
			<l21>		a.subledgername,</l21>
			<l22>		0 opening_balance,</l22>
			<l23>		a.base_debit,</l23>
			<l24>		a.base_credit,</l24>
			<l25>		a.mg_accountid,''ALL'' as pbranchlist</l25>
			<l26>	from</l26>
			<l27>		mv_accountsdetails a</l27>
			<l28>	where</l28>
			<l29>		a.voucher_date &gt;= cast( to_timestamp(:pstartdate, ''dd/mm/yyyy hh24:mi:ss'') as date)</l29>
			<l30>		and a.voucher_date &lt;= cast( to_timestamp(:penddate, ''dd/mm/yyyy hh24:mi:ss'') as date)</l30>
			<l31>		and (a.branchname = cast( :pbranchname as text)</l31>
			<l32>			or  cast( :pbranchname as text)= ''ALL'')				</l32>
			<l33>		and a.financial_year = cast( :pfinyear as text)</l33>
			<l34>		and a.company = cast( :pcompanyid as numeric)</l34>
			<l35>		and a.mg_accountid = cast( :paccountname as numeric)</l35>
			<l36>union all</l36>
			<l37>	select</l37>
			<l38>		''Opening Balance'' as monthyear,</l38>
			<l39>		cast(to_char( cast( to_timestamp(:pstartdate, ''dd/mm/yyyy hh24:mi:ss'') as date) - 1, ''YYYYMM'' ) as numeric) as monthyearnumeric,</l39>
			<l40>		date_trunc(''month'', cast( to_timestamp(:pstartdate, ''dd/mm/yyyy hh24:mi:ss'') as date) - 1) as monthstartdate,</l40>
			<l41>		date_trunc(''month'', cast( to_timestamp(:pstartdate, ''dd/mm/yyyy hh24:mi:ss'') as date) - 1) + interval ''1 month'' - interval ''1 day'' as monthenddate,</l41>
			<l42>		:pbranchname as branchname ,</l42>
			<l43>		a.accountname,</l43>
			<l44>		a.subledgername,</l44>
			<l45>		sum(a.base_debit - a.base_credit) as opening_balance,</l45>
			<l46>		cast( 0 as numeric) as base_debit,</l46>
			<l47>		cast( 0 as numeric) as base_credit,</l47>
			<l48>		a.mg_accountid,''ALL'' as pbranchlist</l48>
			<l49>	from</l49>
			<l50>		mv_accountsdetails a</l50>
			<l51>	where</l51>
			<l52>		a.voucher_date &lt; cast( to_timestamp(:pstartdate, ''dd/mm/yyyy hh24:mi:ss'') as date)</l52>
			<l53>		and (a.branchname = cast( :pbranchname as text)</l53>
			<l54>			or  cast( :pbranchname as text)= ''ALL'')</l54>
			<l55>		and a.company = cast( :pcompanyid as numeric)</l55>
			<l56>		and a.mg_accountid = cast( :paccountname as numeric)</l56>
			<l57>	group by</l57>
			<l58>		a.accountname,</l58>
			<l59>		a.subledgername,</l59>
			<l60>		a.mg_accountid,pbranchlist</l60>
			<l61>	having</l61>
			<l62>		sum(a.base_debit - a.base_credit) &lt;&gt; 0 ) a</l62>
			<l63>group by</l63>
			<l64>	a.monthyear,</l64>
			<l65>	a.monthyear,</l65>
			<l66>	a.monthyearnumeric,</l66>
			<l67>	a.accountname,</l67>
			<l68>	a.subledgername,</l68>
			<l69>	a.monthstartdate,</l69>
			<l70>	a.monthenddate,</l70>
			<l71>	a.mg_accountid,a.pbranchlist</l71>
			<l72>order by</l72>
			<l73>	a.monthyearnumeric,</l73>
			<l74>	a.subledgername,</l74>
			<l75>	a.accountname</l75>
		</a2>
		<a3></a3>
		<a4>reportsql</a4>
	</row1>
