('apdetlv2', 'Outstanding Supplier Bills', '<root pform="yes" name="apdetlv2" caption="Outstanding Supplier Bills" updatedon="20/05/2026 17:16:01" updatedby="tamilselvan" createdon="23/01/2026 15:58:45" createdby="durga"><iview cat="iview" hideprojname="" hidereportdate="" parrange="1"><a0>apdetlv2</a0><a2>Outstanding Supplier Bills</a2><a3 ptable=""></a3><a4>0</a4><a5>true</a5><a6></a6><a7></a7><a8>0</a8><a9></a9><a10>false</a10><a11>true</a11><a12></a12><a13></a13><a14></a14><a15>IView</a15><a16></a16><a17>Enabled</a17><a18>false</a18><a19>false</a19><a51></a51><a52></a52><a53></a53><a54></a54><a55>select row</a55><a57>false</a57><a63>true</a63><a64>false</a64><b9>Outstanding Supplier Bills V2</b9><b10></b10><b11></b11><b12></b12><b13></b13><b14></b14><b15></b15><b16></b16><b17></b17><b35>false</b35><b36>Center</b36><b37>Center</b37><a31></a31><a32>1</a32><a33>false</a33><a34>false</a34><a35>0</a35><a36></a36><a37></a37><a38></a38><a39>false</a39><a40>false</a40><a21>false</a21><a41>false</a41><a42>clskyblue</a42><a43>[Tahoma,9,clBlack,,True,False,False,False]</a43><a44>[Tahoma,8,clBlack,,True,False,False,False]</a44><a45>[Tahoma,8,clBlack,,True,False,False,False]</a45><a46>$00F3AFA0</a46><a47>[Tahoma,8,clBlack,,True,False,False,False]</a47><a48>$00EEF1F2</a48><a49>$00E2E8E9</a49><a50>18</a50><a60>2</a60><b18></b18><b21></b21><b23></b23><b22>0</b22><b38>Classic</b38><b39></b39><a65>false</a65><a66>false</a66></iview><comps cat="comps" dwbtb="true" LocalNum="9" btn="6" vupd="" pnlheight="35"><btn1 key="btn1" caption="Print" cat="btn" tlhw="7,1,20,20" parent="btnPanel" font="Tahoma,8,clWindowText,ffff" def="right" task="print" action="" container="" sname="" flat="true" position="Left" visible="true" footer="false" hint="Print" down=""/><btn2 key="btn2" caption="Preview" cat="btn" tlhw="7,1,20,20" parent="btnPanel" font="Tahoma,8,clWindowText,ffff" def="right" task="preview" action="" container="" sname="" flat="true" position="Left" visible="true" footer="false" hint="Preview" down=""/><btn3 key="btn3" caption="Page Setup / Printer Setting" cat="btn" tlhw="7,1,20,20" parent="btnPanel" font="Tahoma,8,clWindowText,ffff" def="right" task="printersetting" action="" container="" sname="" flat="true" position="Left" visible="true" footer="false" hint="Page Setup / Printer Setting" down=""/><btn4 key="btn4" caption="View" cat="btn" tlhw="7,1,20,20" parent="btnPanel" font="Tahoma,8,clWindowText,ffff" def="right" task="view" action="" container="" sname="" flat="true" position="Left" visible="true" footer="false" hint="View" down=""/><btn5 key="btn5" caption="Find" cat="btn" tlhw="7,1,20,20" parent="btnPanel" font="Tahoma,8,clWindowText,ffff" def="right" task="find" action="" container="" sname="" flat="true" position="Left" visible="true" footer="false" hint="Find" down=""/><btn6 key="btn6" caption="Tasks" cat="btn" tlhw="7,1,20,20" parent="btnPanel" font="Tahoma,8,clWindowText,ffff" def="right" task="tasks" action="" container="" sname="" flat="true" position="Left" visible="false" footer="false" hint="Tasks" down="" folder="true"/><x__head caption="Outstanding Supplier Bills" cat="txt" parent="pnlButton" color="$00F2F0F0" align="none" def="left" tlhw="7,5,19,53" font="_Tahoma,,,clWindowText" type="pnl"/></comps><row1 cat="sql"><a1>Task1</a1><a2><l0>select </l0><l1>a.arapdetailsid, </l1><l2>a.sourceid, </l2><l3>a.transid, </l3><l4>a.mg_accountid, </l4><l5>a.mg_subledgerid,  </l5><l6>a.accountname,</l6><l7>a.subledgername, </l7><l8>a.branchname, </l8><l9>func_returns_hyperlink( a.docid,''formpage'',a.stransid,a.sourceheaderid,(select t.caption from tstructs t where t.name = a.stransid)) as docid,</l9><l10>a.docid as mdocid,</l10><l11>a.docdate, </l11><l12>a.creditdays, </l12><l13>a.due_date, </l13><l14>a.amount,</l14><l15>a.setamount, </l15><l16>a.outstanding_amount,  </l16><l17>a.outstanding_days, </l17><l18>case when (a.outstanding_days &lt;= 0 or a.outstanding_amount  &lt;= 0) then a.outstanding_amount else 0 end as mslab0,  </l18><l19>case when a.outstanding_days &lt;= a.mslab1 and a.outstanding_amount &gt; 0 and a.outstanding_days &gt; 0 then a.outstanding_amount  else 0 end as mslab1, </l19><l20>case when a.outstanding_days between cast( :slab1 as numeric) + 1 and :slab2 and a.outstanding_amount  &gt; 0 then a.outstanding_amount else 0 end as mslab2,</l20><l21>case when a.outstanding_days between cast( :slab2 as numeric) + 1 and :slab3 and a.outstanding_amount  &gt; 0 then a.outstanding_amount else 0 end as mslab3,</l21><l22>case when a.outstanding_days &gt; cast( :slab3 as numeric) and a.outstanding_amount  &gt; 0 then a.outstanding_amount else 0 end as mslab4,</l22><l23>case when a.outstanding_days between cast( :slab4 as numeric) + 1 and :slab5 and a.outstanding_amount  &gt; 0 then a.outstanding_amount else 0 end as mslab5,</l23><l24>case when a.outstanding_days &gt; cast( :slab5 as numeric) and a.outstanding_amount  &gt; 0 then a.outstanding_amount else 0 end as mslab6</l24><l25>from (</l25><l26>select a.arapdetailsid, </l26><l27>a.sourceid, </l27><l28>substring(a.mapname FROM ''[A-Za-z]+'')as transid,  </l28><l29>(select substring(e.mapname FROM ''[A-Za-z]+'') from accountsdtl d, accountshdr e where a.sourceid = d.accountsdtlid and e.accountshdrid = d.accountshdrid) as stransid,</l29><l30>m.mg_accountid, </l30><l31>s.mg_subledgerid,  </l31><l32>(select e.sourceid from accountsdtl d, accountshdr e where a.sourceid = d.accountsdtlid and e.accountshdrid = d.accountshdrid) as sourceheaderid, </l32><l33>m.accountname,</l33><l34>s.subledgername, </l34><l35>br.branchname, </l35><l36>a.docid, a.docdate, </l36><l37>cast( :asondate as date) as asondate,</l37><l38>case when a.amount &gt; 0 then a.creditdays else 0 end as creditdays,</l38><l39>case when a.amount &gt; 0 then a.docdate + interval ''1day'' * a.creditdays else a.docdate end as due_date,</l39><l40>case when cast( :pcurrency as text) = ''ALL'' then a.bamount else a.namount end as amount,   </l40><l41>case when cast( :pcurrency as text) = ''ALL'' then cast( a.bamount + coalesce ( b.bamount,0) as numeric) else cast( a.namount + coalesce ( b.namount,0) as numeric) </l41><l42>end as outstanding_amount, </l42><l43>case when cast( :pcurrency as text) = ''ALL'' then coalesce(b.bamount,0) else coalesce(b.namount,0) end as setamount,</l43><l44>case when a.amount &gt; 0 then </l44><l45>case when cast( :pdues as text) = ''Over Dues'' then cast( cast( :asondate as date) - cast( a.docdate + interval ''1day'' * a.creditdays as date)  as numeric)</l45><l46>else  cast( :asondate as date) - a.docdate end </l46><l47>else 0 end as outstanding_days,  </l47><l48>cast( :slab1 as numeric) as mslab1, </l48><l49>cast( :slab2 as numeric) as mslab2, </l49><l50>cast( :slab3 as numeric) as mslab3, </l50><l51>cast( :slab4 as numeric) as mslab4, </l51><l52>cast( :slab5 as numeric) as mslab5</l52><l53>from arapdetails a</l53><l54>join branch br on ( a.branch = br.branchid ) </l54><l55>left join (</l55><l56>select b.accountname, b.subledgername, </l56><l57>b.refno, max(b.refdate) as refdate, </l57><l58>sum(b.amount) as amount, </l58><l59>sum(b.bamount) as bamount, sum(b.namount) as namount</l59><l60>from arapadjustments b </l60><l61>where b.cancel = ''F''</l61><l62>and b.company = cast( :pcompanyid as numeric )</l62><l63>group by b.accountname, b.subledgername, b.refno</l63><l64>) b on ( a.subledgercode = b.subledgername </l64><l65> and a.docid = b.refno </l65><l66> and a.docdate &lt;= :asondate</l66><l67> and a.accountname = b.accountname</l67><l68> )</l68><l69> join mg_subledger s on ( a.subledgercode = s.mg_subledgerid  )</l69><l70> join mg_account m on ( s.controlaccount = m.mg_accountid and m.acatcode = ''p'' )</l70><l71> join currency c on ( m.acurrency = c.currencyid)</l71><l72>where a.cancel = ''F''</l72><l73>and  a.app_desc = 1</l73><l74>and a.company  = cast( :pcompanyid as numeric )</l74><l75>and (c.currency = cast( :pcurrency as text) or cast( :pcurrency as text) = ''ALL'')</l75><l76>and (s.subledgername = cast( :pcustomer as text) or cast( :pcustomer as text) = ''ALL'')  </l76><l77>and (br.branchname = cast( :pbranchname as text) or cast( :pbranchname as text) = ''ALL'') </l77><l78>and a.docdate &lt;= :asondate</l78><l79>) a</l79><l80>where a.outstanding_amount != 0 </l80><l81>order by accountname, subledgername, docdate, docid</l81></a2><a3></a3><a4>reportsql</a4></row1><pcompanyid cat="params" ord="1"><a1>Task1</a1><a0>pcompanyid</a0><a2>pcompanyid</a2><a4>Numeric</a4><a9>false</a9><a6 sugg="false">m_companyid</a6><a10></a10><a21>true</a21><a11></a11><a5>0</a5><a12>true</a12><a14>false</a14><a56></a56><a13>Accept</a13><a15><s>pcurrency,pcustomer</s></a15><a67>325</a67><a68>false</a68></pcompanyid><pbranchname cat="params" ord="2"><a1>Task1</a1><a0>pbranchname</a0><a2>Branch</a2><a4>Character</a4><a9>false</a9><a6 sugg="false">m_branch</a6><a10></a10><a21>false</a21><a11 pcount="0">select a.branchname
from vw_userbranchlocations a
where a.username = :username 
and a.companyid = cast( :m_companyid as numeric)
union 
select ''ALL'' as branchname from dual 
order by 1</a11><a5>0</a5><a12>true</a12><a14>false</a14><a56></a56><a13>Select</a13><a15></a15><a67>325</a67><a68>false</a68></pbranchname><pcurrency cat="params" ord="3"><a1>Task1</a1><a0>pcurrency</a0><a2>Currency</a2><a4>Character</a4><a9>false</a9><a6 sugg="false">m_currency</a6><a10></a10><a21>false</a21><a11 pcount="1">select distinct b.currency from currency b, mg_account c 
where c.company = cast( :pcompanyid as numeric) and
c.acurrency = b.currencyid and 
c.acatcode = ''r''
union 
select ''ALL'' as currency 
order by 1
</a11><a5>0</a5><a12>true</a12><a14>false</a14><a56></a56><a13>Select</a13><a15><s>pcustomer</s></a15><a67>325</a67><a68>false</a68></pcurrency><pcustomer cat="params" ord="4"><a1>Task1</a1><a0>pcustomer</a0><a2>Supplier</a2><a4>Character</a4><a9>false</a9><a6 sugg="false">{ALL}</a6><a10></a10><a21>false</a21><a11 pcount="2">select subledgername from mg_subledger a, mg_account b, currency c
where a.company = cast( :pcompanyid as numeric) and
a.controlaccount = b.mg_accountid and
b.acurrency = c.currencyid and
b.acatcode = ''p'' and 
c.currency = :pcurrency 
union 
select ''ALL'' as subledgername from dual 
order by subledgername
</a11><a5>0</a5><a12>true</a12><a14>false</a14><a56></a56><a13>Select</a13><a15></a15><a67>325</a67><a68>false</a68></pcustomer><pdues cat="params" ord="5"><a1>Task1</a1><a0>pdues</a0><a2>Status</a2><a4>Character</a4><a9>false</a9><a6 sugg="false">{Over Dues}</a6><a10></a10><a21>false</a21><a11>select cast( choice as texT) as choice from 
( select ''Dues'' as choice from dual union select ''Over Dues'' as choice from dual ) a

</a11><a5>0</a5><a12>true</a12><a14>false</a14><a56></a56><a13>Select</a13><a15></a15><a67>325</a67><a68>false</a68></pdues><asondate cat="params" ord="6"><a1>Task1</a1><a0>asondate</a0><a2>As on Date</a2><a4>Date/Time</a4><a9>false</a9><a6 sugg="false">date()</a6><a10></a10><a21>false</a21><a11></a11><a5>0</a5><a12>true</a12><a14>false</a14><a56></a56><a13>Accept</a13><a15></a15><a67>325</a67><a68>false</a68></asondate><slab1 cat="params" ord="7"><a1>Task1</a1><a0>slab1</a0><a2>&lt;= Days</a2><a4>Numeric</a4><a9>false</a9><a6 sugg="false">30</a6><a10></a10><a21>false</a21><a11></a11><a5>0</a5><a12>true</a12><a14>false</a14><a56></a56><a13>Accept</a13><a15></a15><a67>325</a67><a68>false</a68></slab1><slab2 cat="params" ord="8"><a1>Task1</a1><a0>slab2</a0><a2>Age Slab 2</a2><a4>Numeric</a4><a9>false</a9><a6 sugg="false">60</a6><a10></a10><a21>false</a21><a11></a11><a5>0</a5><a12>true</a12><a14>false</a14><a56></a56><a13>Accept</a13><a15></a15><a67>325</a67><a68>false</a68></slab2><slab3 cat="params" ord="9"><a1>Task1</a1><a0>slab3</a0><a2>Age Slab 3</a2><a4>Numeric</a4><a9>false</a9><a6 sugg="false">90</a6><a10></a10><a21>false</a21><a11></a11><a5>0</a5><a12>true</a12><a14>false</a14><a56></a56><a13>Accept</a13><a15></a15><a67>325</a67><a68>false</a68></slab3><slab4 cat="params" ord="10"><a1>Task1</a1><a0>slab4</a0><a2>Age Slab 4</a2><a4>Numeric</a4><a9>false</a9><a6 sugg="false">120</a6><a10></a10><a21>true</a21><a11></a11><a5>0</a5><a12>true</a12><a14>false</a14><a56></a56><a13>Accept</a13><a15></a15><a67>325</a67><a68>false</a68></slab4><slab5 cat="params" ord="11"><a1>Task1</a1><a0>slab5</a0><a2>Age Slab 5</a2><a4>Numeric</a4><a9>false</a9><a6 sugg="false">150</a6><a10></a10><a21>true</a21><a11></a11><a5>0</a5><a12>true</a12><a14>false</a14><a56></a56><a13>Accept</a13><a15></a15><a67>325</a67><a68>false</a68></slab5><accountname cat="querycol" encrypted="F" freezecol="F" negativenorep="" customdecimal="F"><a2>accountname</a2><a3>General Ledger Control A/c</a3><a1>Task1</a1><a4>Character</a4><a5>0</a5><a6></a6><a7>false</a7><a8>true</a8><a21>true</a21><a13>true</a13><a10>false</a10><a11>false</a11><a12>Clwindow</a12><a9>[Arial,8,clBlack,,False,False,False,False]</a9><a14>Left</a14><a15>true</a15><a16>false</a16><a17>238</a17><a18></a18><a19>false</a19><a53></a53><a54></a54><a55></a55><a58></a58><a59></a59><a61>0</a61><a62></a62><a69 masking=""></a69></accountname><subledgername cat="querycol" encrypted="F" freezecol="F" negativenorep="" customdecimal="F"><a2>subledgername</a2><a3>Customer Name</a3><a1>Task1</a1><a4>Character</a4><a5>0</a5><a6></a6><a7>false</a7><a8>true</a8><a21>true</a21><a13>false</a13><a10>false</a10><a11>false</a11><a12>Clwindow</a12><a9>[Arial,8,clBlack,,False,False,False,False]</a9><a14>Left</a14><a15>true</a15><a16>false</a16><a17>250</a17><a18></a18><a19>false</a19><a53></a53><a54></a54><a55></a55><a58></a58><a59></a59><a61>0</a61><a62></a62><a69 masking=""></a69></subledgername><arapdetailsid cat="querycol" encrypted="F" freezecol="F" negativenorep="" customdecimal="F"><a2>arapdetailsid</a2><a3>arapdetailsid</a3><a1>Task1</a1><a4>Numeric</a4><a5>0</a5><a6></a6><a7>false</a7><a8>false</a8><a21>true</a21><a13>false</a13><a10>false</a10><a11>false</a11><a12>Clwindow</a12><a9>[Arial,8,clBlack,,False,False,False,False]</a9><a14>Right</a14><a15>true</a15><a16>true</a16><a17>122</a17><a18></a18><a19>false</a19><a53></a53><a54></a54><a55></a55><a58></a58><a59></a59><a61>0</a61><a62></a62><a69 masking=""></a69></arapdetailsid><docid cat="querycol" encrypted="F" freezecol="F" negativenorep="" customdecimal="F"><a2>docid</a2><a3>Invoice#</a3><a1>Task1</a1><a4>Character</a4><a5>0</a5><a6></a6><a7>false</a7><a8>true</a8><a21>false</a21><a13>false</a13><a10>false</a10><a11>false</a11><a12>Clwindow</a12><a9>[Arial,8,clBlack,,False,False,False,False]</a9><a14>Left</a14><a15>true</a15><a16>false</a16><a17>192</a17><a18></a18><a19>false</a19><a53></a53><a54></a54><a55></a55><a58></a58><a59></a59><a61>0</a61><a62></a6