	<row1 cat="sql">
		<a1>Task1</a1>
		<a2>
			<l0>select</l0>
			<l1>	A.GROUPNAME,</l1>
			<l2>	A.atype ACCOUNTTYPE,</l2>
			<l3>    a.accountname,    </l3>
			<l4>    a.accountcode accountcode , </l4>
			<l5>	a.ACATEGORY,</l5>
			<l6>    case when upper(a.atype) = ''GROUP'' then concat(''&lt;span style="font-weight:bold;"&gt;'', a.atype, ''&lt;/span&gt;'') else a.atype end as amtype,</l6>
			<l7>	a.atype, </l7>
			<l8>	A.ALIE,</l8>
			<l9>	a.COLLAPSE,</l9>
			<l10>	A.MG_ACCOUNTID,</l10>
			<l11>	null as TEMP_EXPAND,</l11>
			<l12>    case when upper(A.ACCOUNT) in (''ASSETS'',''LIABILITIES'',''INCOME'',''EXPENSES'') then </l12>
			<l13>    concat(''&lt;span style="font-weight:bold;"&gt;&lt;u&gt;'', a.account, ''&lt;/u&gt;&lt;/span&gt;'')</l13>
			<l14>    when upper(a.atype) = ''GROUP'' then concat(''&lt;span style="font-weight:bold;"&gt;'', a.account, ''&lt;/span&gt;'')</l14>
			<l15>    else</l15>
			<l16>    initcap(a.ACCOUNT) end</l16>
			<l17>    as ACCOUNT, </l17>
			<l18>	coalesce (b.OP,0) as op,</l18>
			<l19>	coalesce (b.TRADB,0) as tradb,</l19>
			<l20>	coalesce (b.TRACR,0) as tracr,</l20>
			<l21>	coalesce (b.CL,0) as cl,</l21>
			<l22>	'''' as pgrp,</l22>
			<l23>    concat(''&lt;span style="font-weight:bold;"&gt;&lt;u&gt;'', </l23>
			<l24>	upper(case</l24>
			<l25>		alie when ''1'' then ''Assets''</l25>
			<l26>		when ''2'' then ''Liabilities''</l26>
			<l27>		when ''3'' then ''Income''</l27>
			<l28>		when ''4'' then ''Expenses''</l28>
			<l29>	end),  ''&lt;/u&gt;&lt;/span&gt;'')</l29>
			<l30>    as acc_type,</l30>
			<l31>	''&lt;span class="material-icons material-icons-style material-icons-2" style="color: Blue;"&gt;mode_edit&lt;/span&gt;'' as editacc,</l31>
			<l32>	case</l32>
			<l33>		when a.atype = ''Group'' and a.addable = ''T'' then ''&lt;span class="material-icons material-icons-style material-icons-2" style="color:blue"&gt;playlist_add&lt;/span&gt;''</l33>
			<l34>		else ''''</l34>
			<l35>	end as add_child,</l35>
			<l36>	case when a.atype = ''Group'' then ''&lt;span class="material-icons material-icons-style" style="color:blue"&gt;topic&lt;/span&gt;'' else </l36>
			<l37>    ''&lt;span class="material-icons material-icons-style" style="color:#2b4da1"&gt;more_horiz&lt;/span&gt;''  end as gpac, </l37>
			<l38>    case when a.atype != ''Group'' and upper(a.ibaccount) = ''T'' then ''&lt;span class="material-icons material-icons-style" style="color:#2b4da1"&gt;check_box&lt;/span&gt;'' </l38>
			<l39>     else '' '' end as ibaccount,</l39>
			<l40>     case when a.atype != ''Group'' and upper(a.controlaccount) = ''T'' then ''&lt;span class="material-icons material-icons-style" style="color:#2b4da1"&gt;check_box&lt;/span&gt;'' </l40>
			<l41>     else '' '' end as controlac</l41>
			<l42>from</l42>
			<l43>	(select * from fn_account_tree( cast( :pcompanyid as numeric) ) where accountname not in  (''ASSETS'',''LIABILITIES'',''INCOME'',''EXPENSES'') ) a 	</l43>
			<l44>left outer join (</l44>
			<l45>select</l45>
			<l46>		PARANTID,</l46>
			<l47>		SUM (OP) as OP,</l47>
			<l48>		SUM (TRADB) as TRADB,</l48>
			<l49>		SUM (TRACR) as TRACR,</l49>
			<l50>		SUM (OP + TRADB - TRACR) as CL</l50>
			<l51>	from</l51>
			<l52>		(		</l52>
			<l53>		select</l53>
			<l54>			A.PARANTID,</l54>
			<l55>			(b.base_debit - b.base_credit) * case</l55>
			<l56>				when b.alie in (''2'', ''3'') then 1-2</l56>
			<l57>				else 1</l57>
			<l58>			end as op,</l58>
			<l59>			0 as TRADB,</l59>
			<l60>			0 as TRACR</l60>
			<l61>		from</l61>
			<l62>			VW_ACCOUNTTREELINK A,</l62>
			<l63>			mv_accountmonthlysummary B</l63>
			<l64>		where</l64>
			<l65>			A.CHILDID = B.mg_accountid</l65>
			<l66>			and B.financial_year = :pfinyr </l66>
			<l67>			and (b.base_debit - b.base_credit) &lt;&gt; 0</l67>
			<l68>			and b.company = :pcompanyid </l68>
			<l69>			and voucher_yearmonth &lt; cast( :m_startdatenumeric as numeric)				</l69>
			<l70>	union all</l70>
			<l71>	select A.PARANTID,</l71>
			<l72>			0 as OP,</l72>
			<l73>			b.base_debit  as TRADB,</l73>
			<l74>			b.base_credit  as TRACR</l74>
			<l75>		from</l75>
			<l76>			VW_ACCOUNTTREELINK A,</l76>
			<l77>			mv_accountmonthlysummary B</l77>
			<l78>		where		</l78>
			<l79>			A.CHILDID = B.mg_accountid</l79>
			<l80>			and B.financial_year = :pfinyr</l80>
			<l81>			and b.company = :pcompanyid</l81>
			<l82>			and voucher_yearmonth &lt;=  cast( :m_enddatenumeric as numeric) </l82>
			<l83>	) a</l83>
			<l84>	group by</l84>
			<l85>		PARANTID</l85>
			<l86>		) B on	</l86>
			<l87>A.mg_accountid  = B.PARANTID				</l87>
			<l88>order by</l88>
			<l89>	aprefix,</l89>
			<l90>	sno</l90>
		</a2>
		<a3></a3>
		<a4>reportsql</a4>
	</row1>
