	<row1 cat="sql">
		<a1>Task1</a1>
		<a2>
			<l0>select a.id, a.category, </l0>
			<l1>case when a.common_intergration_code != 0 then </l1>
			<l2>''&lt;span style="margin-left: 20px;"&gt;'' || a.accountname  || ''&lt;/span&gt;'' else</l2>
			<l3>''&lt;span style="color: maroon; text-decoration: underline; text-decoration: ''||case when a.linestyle = ''d'' then ''underline double'' else ''underline'' end</l3>
			<l4>||''; font-weight: bold;"&gt;''||a.accountname||''&lt;/span&gt;''</l4>
			<l5>end accountname,</l5>
			<l6>a.accountcode_alias, a.alie, a.common_intergration_code,  </l6>
			<l7>cast(''A''||a.id as text) groupslno, </l7>
			<l8>case when ( a.common_intergration_code != 0 or a.linestyle = ''s'') then a.valexp else '''' end  valexp, </l8>
			<l9>case when a.common_intergration_code = 0 and a.linestyle = ''d'' then a.valexp else '''' end  as mvalexp, </l9>
			<l10>coalesce ( fn_accounts_justbalances( cast( :pcompanyid as numeric), </l10>
			<l11>                                    cast( :pbranchid as numeric ), </l11>
			<l12>                                    a.common_intergration_code, </l12>
			<l13>                                    cast( :pfromdate as date), </l13>
			<l14>                                    cast( :ptodate as date), </l14>
			<l15>                                    cast( ''T'' as text)) </l15>
			<l16>         ) as amount,</l16>
			<l17>a.scheduleno, </l17>
			<l18>:pbranchname as branch, </l18>
			<l19>cast( :currentyearpandl as numeric) mcurrentyearpandl,</l19>
			<l20>cast( :openingbaldiff as numeric) mopeningbaldiff</l20>
			<l21>from bsheet a</l21>
			<l22>where (( cast( :openingbaldiff as numeric) = 0 and id != 280) or cast( :openingbaldiff as numeric) != 0)</l22>
			<l23>order by id</l23>
		</a2>
		<a3></a3>
		<a4>reportsql</a4>
	</row1>
