	<row1 cat="sql">
		<a1>Task1</a1>
		<a2>
			<l0>select a.sno, a.alie,  </l0>
			<l1>''Actmonthly,Monthly Summary,Script,calendar_month~</l1>
			<l2>dailysum,Daily Summary,Script,calendar_today~</l2>
			<l3>''||case when a.acategory in  (''Receivable A/c'',''Payable A/c'') then </l3>
			<l4>''arapagei,Age Analysis,Script,attach_money~'' else '''' end ||</l4>
			<l5>''subledge,Subledger,Script,collections_bookmark'' as axrowoptions,     </l5>
			<l6>a.groupname, </l6>
			<l7>a.accountname, </l7>
			<l8>''...''||a.accountname as maccountname,</l8>
			<l9>b.subledgername,</l9>
			<l10>coalesce (b.OPADB,0) as opadb,</l10>
			<l11>coalesce (b.OPACR,0) as OPACR,</l11>
			<l12>coalesce (b.OPADB) - coalesce(b.OPACR,0) as opbal,</l12>
			<l13>coalesce (b.TRADB,0) as tradb,</l13>
			<l14>coalesce (b.TRACR,0) as tracr,</l14>
			<l15>coalesce (b.CLODB,0) as CLODB,</l15>
			<l16>coalesce (b.CLOCR,0) as CLOCR,</l16>
			<l17>coalesce (b.CLODB,0) - coalesce (b.CLOCR,0) as clbal,</l17>
			<l18>coalesce (b.TRADB,0) - coalesce (b.TRACR,0) as nettransaction,</l18>
			<l19>cast( :pbranchname as text) as mbranchname, </l19>
			<l20>cast( :pstartdate as date) as mstartdate,</l20>
			<l21>cast( :penddate as date) as menddate,</l21>
			<l22>cast( :psubledger as text) as msubledger,</l22>
			<l23>cast( :pbranchlist as text) as mbranchlist, </l23>
			<l24>a.mg_accountid </l24>
			<l25>from 	</l25>
			<l26>(</l26>
			<l27>select * from fn_account_tree( cast( :pcompanyid as numeric) ) </l27>
			<l28>where accountname not in  (''ASSETS'',''LIABILITIES'',''INCOME'',''EXPENSES'') </l28>
			<l29>) a join (</l29>
			<l30>        select</l30>
			<l31>		accountname,</l31>
			<l32>        subledgername, </l32>
			<l33>		SUM (OPADB) as OPADB,</l33>
			<l34>        SUM (OPACR) as OPACR,</l34>
			<l35>		SUM (TRADB) as TRADB,</l35>
			<l36>		SUM (TRACR) as TRACR,</l36>
			<l37>        CASE WHEN (SUM (OPADB) - SUM (OPACR) + SUM (TRADB) - SUM (TRACR)) &gt; 0 then</l37>
			<l38>        SUM (OPADB) - SUM (OPACR) + SUM (TRADB) - SUM (TRACR) ELSE 0 END </l38>
			<l39>        AS CLODB, </l39>
			<l40>        CASE WHEN (SUM (OPADB) - SUM (OPACR) + SUM (TRADB) - SUM (TRACR)) &lt; 0 then (SUM (OPADB) - SUM (OPACR) + SUM (TRADB) - SUM (TRACR))*(1-2) ELSE 0 END </l40>
			<l41>        AS CLOCR</l41>
			<l42>	from</l42>
			<l43>		(		</l43>
			<l44>		select</l44>
			<l45>			b.mg_accountid accountname, </l45>
			<l46>            b.subledgername,</l46>
			<l47>			(b.base_debit) as OPADB,</l47>
			<l48>            (b.base_credit) as OPACR,</l48>
			<l49>			0 as TRADB,</l49>
			<l50>			0 as TRACR</l50>
			<l51>		from mv_accountmonthlysummary B</l51>
			<l52>		where</l52>
			<l53>			 (b.base_debit - b.base_credit) &lt;&gt; 0</l53>
			<l54>			and b.company = cast( :pcompanyid as numeric)</l54>
			<l55>            and b.controlaccount = ''T''</l55>
			<l56>            and (b.branchname = cast( :pbranchname as text) or </l56>
			<l57>               ( cast( :pbranchname as text)= ''ALL'' and ( cast( :pbranchlist as text) like ''%''||b.branchname||''%''  or :pbranchlist = ''ALL'')) )   </l57>
			<l58>            and b.voucher_yearmonth &lt; cast( to_char( :pstartdate, ''YYYYMM'') as  numeric) </l58>
			<l59>            and ( b.accountname = cast( :paccountname as text) or cast( :paccountname as text)  = ''ALL'')</l59>
			<l60>            union all</l60>
			<l61>		select b.mg_accountid accountname,</l61>
			<l62>            b.subledgername,</l62>
			<l63>			0 as OPADB,</l63>
			<l64>            0 as OPACR,</l64>
			<l65>			b.base_debit  as TRADB,</l65>
			<l66>			b.base_credit  as TRACR</l66>
			<l67>		from</l67>
			<l68>			mv_accountmonthlysummary B</l68>
			<l69>            where (b.branchname = cast( :pbranchname as text) or </l69>
			<l70>               ( cast( :pbranchname as text)= ''ALL'' and ( cast( :pbranchlist as text) like ''%''||b.branchname||''%''  or :pbranchlist = ''ALL'')) )           </l70>
			<l71>		    and b.company = cast( :pcompanyid as numeric)           </l71>
			<l72>            and b.controlaccount = ''T''</l72>
			<l73>			and b.voucher_yearmonth between cast( to_char( :pstartdate, ''YYYYMM'') as  numeric) AND </l73>
			<l74>			cast( to_char( :penddate, ''YYYYMM'') as  numeric)</l74>
			<l75>            and ( b.accountname = cast( :paccountname as text) or cast( :paccountname as text)  = ''ALL'')</l75>
			<l76>	) a</l76>
			<l77>	group by a.accountname,a.subledgername</l77>
			<l78>) B on	A.mg_accountid  = B.accountname</l78>
			<l79>order by accountname,subledgername</l79>
		</a2>
		<a3></a3>
		<a4>reportsql</a4>
	</row1>
