	</comps>
	<row1 cat="sql">
		<a1>Task1</a1>
		<a2>
			<l0>select a.voucher_date,</l0>
			<l1>a.branchname,</l1>
			<l2>a.vouchertype, </l2>
			<l3>case when a.sourceid = 0 then a.accountshdrid else a.sourceid end as recordid, </l3>
			<l4>''t''||a.transid as transid, </l4>
			<l5>a.accountname,</l5>
			<l6>a.subledgername, </l6>
			<l7>func_returns_hyperlink( a.voucher_number, ''formpage'',a.transid,(case when a.sourceid = 0 then a.accountshdrid else a.sourceid end),(select t1.caption from tstructs t1 where t1.name = a.transid),a.voucher_number) as voucher_number, </l7>
			<l8>0 opening_balance, </l8>
			<l9>a.base_debit, </l9>
			<l10>a.base_credit, </l10>
			<l11>coalesce( </l11>
			<l12>''&lt;span style="font-weight:bold;"&gt;''||''SBU/Branch ''||''&lt;/span&gt;''||a.branchname||''&lt;br/&gt;'' </l12>
			<l13>||case when (a.reference_number is not null or a.reference_date is not null) then </l13>
			<l14>''&lt;span style="font-weight:bold;"&gt;''||''Ref#/Date ''||''&lt;/span&gt;''||</l14>
			<l15>coalesce (a.reference_number,'' '') ||''-''||to_char(a.reference_date,''dd/mm/yyyy'')||''&lt;br/&gt;'' end, '' '')</l15>
			<l16>||</l16>
			<l17>coalesce( case when (a.cheque_number is not null or a.cheque_date is not null) then </l17>
			<l18>''&lt;span style="font-weight:bold;"&gt;''||''Chq#/Date ''||''&lt;/span&gt;''||</l18>
			<l19>coalesce (a.cheque_number,'' '')||''-''||to_char(a.cheque_date,''dd/mm/yyyy'')||''&lt;br/&gt;'' end, '' '')</l19>
			<l20>||</l20>
			<l21>coalesce (case when a.narration is not null then ''&lt;span style="font-style:italic;"&gt;''||a.narration||''&lt;/span&gt;''||''&lt;br/&gt;'' end ,'' '')</l21>
			<l22>as details</l22>
			<l23>from mv_accountsdetails a</l23>
			<l24>where a.voucher_date &gt;=  cast( :pstartdate as date) </l24>
			<l25>and a.voucher_date &lt;=  cast( :penddate as date)</l25>
			<l26>and (a.branchname = cast( :pbranchname as text) or </l26>
			<l27>               ( cast( :pbranchname as text)= ''ALL'' and ( cast( :pbranchlist as text) like ''%''||a.branchname||''%''  or :pbranchlist = ''ALL'')) )   </l27>
			<l28>and a.company = cast( :pcompanyid as numeric)  </l28>
			<l29>and ( a.accountname = :mpaccountname or :mpaccountname = ''ALL'')</l29>
			<l30>union all</l30>
			<l31>select cast( :pstartdate as date) as voucher_date, </l31>
			<l32>cast( null as text) as branchname,</l32>
			<l33>cast( null as text) vouchertype, </l33>
			<l34>0 as recordid, </l34>
			<l35>cast( '''' as text) as transid, </l35>
			<l36>a.accountname,</l36>
			<l37>cast( null as text) subledgername, </l37>
			<l38>func_returns_hyperlink( ''Opening Balance '', ''formpage'',null, 0 ,''Finance Transaction'',''Opening Balance '') as voucher_number, </l38>
			<l39>sum(a.base_debit - a.base_credit) as opening_balance, </l39>
			<l40>case when sum(a.base_debit - a.base_credit) &gt; 0 then sum(a.base_debit - a.base_credit) else cast( 0 as numeric) end as base_debit, </l40>
			<l41>case when sum(a.base_debit - a.base_credit) &lt; 0 then -sum(a.base_debit - a.base_credit) else cast( 0 as numeric) end as base_credit, </l41>
			<l42>cast('' '' as text) as details</l42>
			<l43>from mv_accountsdetails a</l43>
			<l44>where a.voucher_date &lt; cast( :pstartdate as date) </l44>
			<l45>and (a.branchname = cast( :pbranchname as text) or </l45>
			<l46>               ( cast( :pbranchname as text)= ''ALL'' and ( cast( :pbranchlist as text) like ''%''||a.branchname||''%''  or :pbranchlist = ''ALL'')) )   </l46>
			<l47>and a.company = cast( :pcompanyid as numeric)  </l47>
			<l48>and ( a.accountname = :mpaccountname or :mpaccountname = ''ALL'')</l48>
			<l49>group by a.accountname</l49>
			<l50>order by accountname,voucher_date,branchname</l50>
		</a2>
		<a3></a3>
		<a4>reportsql</a4>
	</row1>
