	<row1 cat="sql">
		<a1>Task1</a1>
		<a2>
			<l0>select a.voucher_date,</l0>
			<l1>a.branchname,</l1>
			<l2>a.vouchertype, </l2>
			<l3>case when a.sourceid = 0 then a.accountshdrid else a.sourceid end as recordid, </l3>
			<l4>''t''||a.transid as transid, </l4>
			<l5>a.accountname,</l5>
			<l6>a.subledgername, </l6>
			<l7>func_returns_hyperlink( a.voucher_number, ''formpage'',a.transid,(case when a.sourceid = 0 then a.accountshdrid else a.sourceid end),(select t1.caption from tstructs t1 where t1.name = a.transid),a.voucher_number) as voucher_number, a.txn_exrate,</l7>
			<l8>0 opening_balance, </l8>
			<l9>a.base_debit, </l9>
			<l10>a.base_credit, </l10>
			<l11>coalesce( </l11>
			<l12>''&lt;span style="font-weight:bold;"&gt;''||''Branch ''||''&lt;/span&gt;''||a.branchname||''&lt;br/&gt;'' </l12>
			<l13>||case when (a.reference_number is not null or a.reference_date is not null) then </l13>
			<l14>''&lt;span style="font-weight:bold;"&gt;''||''Ref#/Date ''||''&lt;/span&gt;''||</l14>
			<l15>coalesce (a.reference_number,'' '') ||''-''||to_char(a.reference_date,''dd/mm/yyyy'')||''&lt;br/&gt;'' end, '' '')</l15>
			<l16>||</l16>
			<l17>coalesce( case when (a.cheque_number is not null or a.cheque_date is not null) then </l17>
			<l18>''&lt;span style="font-weight:bold;"&gt;''||''Chq#/Date ''||''&lt;/span&gt;''||</l18>
			<l19>coalesce (a.cheque_number,'' '')||''-''||to_char(a.cheque_date,''dd/mm/yyyy'')||''&lt;br/&gt;'' end, '' '')</l19>
			<l20>||</l20>
			<l21>coalesce (case when a.narration is not null then ''&lt;span style="font-style:italic;"&gt;''||a.narration||''&lt;/span&gt;''||''&lt;br/&gt;'' end ,'' '')</l21>
			<l22>as details,a.txn_currency, a.txn_debit ,a.txn_credit </l22>
			<l23>from mv_accountsdetails a</l23>
			<l24>where a.voucher_date &gt;=  cast( :pstartdate as date) </l24>
			<l25>and a.voucher_date &lt;=  cast( :penddate as date)</l25>
			<l26>and (a.branchname = cast( :pbranchname as text) or </l26>
			<l27>                cast( :pbranchname as text)= ''ALL'')    </l27>
			<l28>and a.company = cast( :pcompanyid as numeric)  </l28>
			<l29>and ( a.accountname = :mpaccountname) </l29>
			<l30>and (a.subledgername = :psubledgername or :psubledgername = ''ALL'')</l30>
			<l31>union all</l31>
			<l32>select cast( :pstartdate as date) as voucher_date, </l32>
			<l33>cast( null as text) as branchname,</l33>
			<l34>cast( null as text) vouchertype, </l34>
			<l35>0 as recordid, </l35>
			<l36>cast( '''' as text) as transid, </l36>
			<l37>a.accountname,</l37>
			<l38>a.subledgername, </l38>
			<l39>cast( ''Opening Balance '' as text) as voucher_number, a.txn_exrate ,</l39>
			<l40>sum(a.base_debit - a.base_credit) as opening_balance, </l40>
			<l41>case when sum(a.base_debit - a.base_credit)  &gt; 0 then sum(a.base_debit - a.base_credit)  else cast( 0 as numeric) end as base_debit, </l41>
			<l42>case when sum(a.base_debit - a.base_credit)  &lt; 0 then -sum(a.base_debit - a.base_credit)  else cast( 0 as numeric) end as base_credit, </l42>
			<l43>cast('' '' as text) as details,a.txn_currency ,</l43>
			<l44>case when sum(a.txn_debit - a.txn_credit)  &gt; 0 then sum(a.txn_debit - a.txn_credit)  else cast( 0 as numeric) end as txn_debit ,</l44>
			<l45>case when sum(a.txn_debit - a.txn_credit)  &lt; 0 then -sum(a.txn_debit - a.txn_credit)  else cast( 0 as numeric) end as txn_credit </l45>
			<l46>from mv_accountsdetails a</l46>
			<l47>where a.voucher_date &lt; cast( :pstartdate as date) </l47>
			<l48>and (a.branchname = cast( :pbranchname as text) or </l48>
			<l49>                cast( :pbranchname as text)= ''ALL'')    </l49>
			<l50>and a.company = cast( :pcompanyid as numeric)  </l50>
			<l51>and ( a.accountname = :mpaccountname ) </l51>
			<l52>and (a.subledgername = :psubledgername or :psubledgername = ''ALL'')</l52>
			<l53>group by a.accountname, a.subledgername,a.txn_currency ,a.txn_exrate</l53>
			<l54>order by accountname,subledgername, voucher_date, branchname</l54>
		</a2>
		<a3></a3>
		<a4>reportsql</a4>
	</row1>
