		<a10></a10>
		<a21>false</a21>
		<a11 pcount="0">select ''ALL'' as branchname from dual 
union all 
select distinct cast( b.branchname as varchar(100)) branchname from branch b,
(select b.axusersid, UNNEST(STRING_TO_ARRAY(b.axug_branch, '','')) as branchname from axusergrouping b ) c, axusers a
where b.branchname = c.branchname and a.axusersid = c.axusersid and b.companyname = :m_companyid
and a.username = :username
union 
select cast(b.branchname as varchar(100)) as branchname from branch b
where b.cancel = ''F'' and b.companyname = :m_companyid
and b.app_desc = 1 and b.active = ''T''
and ( upper( :usergroup) like ''%DEFAULT%'')  
order by branchname</a11>
		<a5>0</a5>
