	<row1 cat="sql">
		<a1>Task1</a1>
		<a2>
			<l0>select</l0>
			<l1>	a.groupname,</l1>
			<l2>    ''&lt;span style="margin-left: 20px;"&gt;'' || a.accountname  || ''&lt;/span&gt;'' as accountname,a.accountname as maccountname,</l2>
			<l3>	a.accountcode_alias,</l3>
			<l4>	    sum(a.amount) as amount,</l4>
			<l5>	sum(a.cumulative) as cumulative,</l5>
			<l6>	a.mg_accountid,</l6>
			<l7>    cast( :pscheduleno as text) as schno, </l7>
			<l8>    ''Actmonthly,Monthly Summary,Script,calendar_month~dailysum,Daily Summary,Script,calendar_today~arapagei,Age Analysis,Script,attach_money~glsubrep,General Ledger,Script,book'' as axrowoptions,    </l8>
			<l9>    cast( :pbranchname as text) as mbranchname,</l9>
			<l10>    cast( :pfromdate as date) as mstartdate,</l10>
			<l11>    cast( :ptodate as date) as menddate</l11>
			<l12>from</l12>
			<l13>	(</l13>
			<l14>	select</l14>
			<l15>		b.accountname,</l15>
			<l16>		b.groupname,</l16>
			<l17>		b.mg_accountid,</l17>
			<l18>		b.accountcode_alias,</l18>
			<l19>		case</l19>
			<l20>			when b.alie = ''3'' then sum(b.base_debit-b.base_credit)*(1-2)</l20>
			<l21>			else sum(b.base_debit-b.base_credit)</l21>
			<l22>		end as amount,</l22>
			<l23>		0 as cumulative</l23>
			<l24>	from</l24>
			<l25>		vw_accounttreelink a,</l25>
			<l26>		mv_accountsdetails b</l26>
			<l27>	where</l27>
			<l28>		a.parantid in (</l28>
			<l29>		select</l29>
			<l30>			a.accountname</l30>
			<l31>		from</l31>
			<l32>			vw_parantlink a</l32>
			<l33>		where          </l33>
			<l34>     	(( a.common_intergration_code = cast( :pcommonintegratiocode as numeric) or a.common_intergration_code1 = cast( :pcommonintegratiocode as numeric) </l34>
			<l35>			  or a.common_intergration_code2 = cast( :pcommonintegratiocode as numeric)) </l35>
			<l36>				or cast( :pcommonintegratiocode as numeric) = 0)</l36>
			<l37>				and a.company = cast( :pcompanyid as numeric) )          </l37>
			<l38>		and a.parantid = b.mg_accountid</l38>
			<l39>		and b.company = cast( :pcompanyid as numeric)</l39>
			<l40>		and ( b.branchid = cast( :pbranchid as numeric) or ( cast( :pbranchid as numeric) = 0</l40>
			<l41>			or cast( :pbranchid as numeric) = 1))</l41>
			<l42>		and  b.voucher_date between cast( :pfromdate as date) and cast( :ptodate as date)</l42>
			<l43>	group by</l43>
			<l44>		b.accountname,</l44>
			<l45>		b.groupname,</l45>
			<l46>		b.alie,</l46>
			<l47>		b.mg_accountid,</l47>
			<l48>		b.accountcode_alias</l48>
			<l49>union all</l49>
			<l50>	select</l50>
			<l51>		b.accountname,</l51>
			<l52>		b.groupname,</l52>
			<l53>		b.mg_accountid,</l53>
			<l54>		b.accountcode_alias,</l54>
			<l55>		0 as amount,</l55>
			<l56>		case</l56>
			<l57>			when b.alie = ''3'' then sum(b.base_debit-b.base_credit)*(1-2)</l57>
			<l58>			else sum(b.base_debit-b.base_credit)</l58>
			<l59>		end as cumulative</l59>
			<l60>	from</l60>
			<l61>		vw_accounttreelink a,</l61>
			<l62>		mv_accountsdetails b</l62>
			<l63>	where</l63>
			<l64>		a.parantid in (</l64>
			<l65>		select</l65>
			<l66>			a.accountname</l66>
			<l67>		from</l67>
			<l68>			vw_parantlink a</l68>
			<l69>		where</l69>
			<l70>	    (( a.common_intergration_code = cast( :pcommonintegratiocode as numeric) or a.common_intergration_code1 = cast( :pcommonintegratiocode as numeric) </l70>
			<l71>			  or a.common_intergration_code2 = cast( :pcommonintegratiocode as numeric)) </l71>
			<l72>				or cast( :pcommonintegratiocode as numeric) = 0)</l72>
			<l73>				and a.company = cast( :pcompanyid as numeric) )          </l73>
			<l74>		and a.parantid = b.mg_accountid</l74>
			<l75>		and b.company = cast( :pcompanyid as numeric)</l75>
			<l76>		and ( b.branchid = cast( :pbranchid as numeric)</l76>
			<l77>			or cast( :pbranchid as numeric) = 1)</l77>
			<l78>		and  b.voucher_date &lt;= cast( :ptodate as date)</l78>
			<l79>	group by</l79>
			<l80>		b.accountname,</l80>
			<l81>		b.groupname,</l81>
			<l82>		b.alie,</l82>
			<l83>		b.mg_accountid,</l83>
			<l84>		b.accountcode_alias ) a</l84>
			<l85>group by</l85>
			<l86>	a.accountname,</l86>
			<l87>	a.groupname,</l87>
			<l88>	a.mg_accountid,</l88>
			<l89>	a.accountcode_alias</l89>
			<l90>order by</l90>
			<l91>	groupname,</l91>
			<l92>	accountname</l92>
		</a2>
		<a3></a3>
		<a4>reportsql</a4>
	</row1>
