ountid, </l8><l9>a.accountname, a.accountcode_alias, a.atype, a.alie, a.company, a.primarygroup,</l9><l10>b.period_text||''^''||b.mperiod_subtext as pivot, </l10><l11>case when ((a.alie = ''3'' and sum( b.balance) &gt; 0) or (a.alie = ''4'' and sum( b.balance) &lt; 0)) then -sum( b.balance) </l11><l12>     else abs(sum(b.balance))</l12><l13>end balance, b.ordno</l13><l14>from vw_pandlsetup a,</l14><l15>fn_accounts_balances( cast( :pcompanyid as numeric), cast( :pbranchid as numeric), cast( ''MONTHLY'' as varchar), </l15><l16>                     cast( a.mg_accountid as numeric), </l16><l17>                    cast( :pfromdate as date), cast( :ptodate as date),''T'',''F'' ) b </l17><l18>where a.company = cast( :pcompanyid as numeric) </l18><l19>and a.id not in ( 70, 130) </l19><l20>  and a.accountname = :paccountname </l20><l21>group by a.id, a.category, a.groupid, a.groupname, a.mg_accountid, a.accountname, a.accountcode_alias, a.atype, a.alie, a.company, a.primarygroup, </l21><l22>b.period_text||''^''||b.mperiod_subtext, b.ordno, a.alie</l22><l23>union all</l23><l24>select a.id, null category, 0 groupid, null groupname, 0 mg_accountid,    </l24><l25>a.accountname as accountname,   </l25><l26> null accountcode_alias, '' '' atype, '' '' alie, a.company, '' '' primarygroup, </l26><l27>b.period_text||''^''||b.mperiod_subtext as pivot, </l27><l28>case when ((''3'' = ''3'' and sum( b.balance) &gt; 0) or (''3'' = ''4'' and sum( b.balance) &lt; 0)) then -sum( b.balance) </l28><l29>     else abs(sum(b.balance))</l29><l30>end balance,</l30><l31>b.ordno</l31><l32>from vw_pandlsetup a,</l32><l33>fn_accounts_balances( cast( :pcompanyid as numeric), cast( :pbranchid as numeric), cast( ''QUARTERLY'' as varchar), cast( a.mg_accountid as numeric), </l33><l34>                    cast( :pfromdate as date), cast( :ptodate as date),''T'',''F'' ) b </l34><l35>where a.company = cast( :pcompanyid as numeric)</l35><l36>and a.id in ( 70, 130) </l36><l37>  and a.accountname = :paccountname </l37><l38>group by a.id, a.category, a.groupname, a.accountname, a.company, b.period_text||''^''||b.mperiod_subtext,b.ordno</l38><l39>) a</l39><l40>order by id, groupname, accountname, ordno</l40></a2><a3></a3><a4>reportsql</a4></row1><pcompanyid cat="params" ord="1"><a1>Task1</a1><a0>pcompanyid</a0><a2>pcompanyid</a2><a4>Numeric</a4><a9>false</a9><a6 sugg="false">m_companyid</a6><a10></a10><a21>true</a21><a11></a11><a5>0</a5><a12>true</a12><a14>false</a14><a56></a56><a13>Accept</a13><a15></a15><a67>325</a67><a68>false</a68></pcompanyid><pbranchid cat="params" ord="2"><a1>Task1</a1><a0>pbranchid</a0><a2>pbranchid</a2><a4>Numeric</a4><a9>false</a9><a6 sugg="false">{99847}</a6><a10></a10><a21>true</a21><a11></a11><a5>0</a5><a12>true</a12><a14>false</a14><a56></a56><a13>Accept</a13><a15></a15><a67>325</a67><a68>false</a68></pbranchid><pfromdate cat="params" ord="3"><a1>Task1</a1><a0>pfromdate</a0><a2>From Date</a2><a4>Date/Time</a4><a9>false</a9><a6 sugg="false">m_fystartdate</a6><a10></a10><a21>false</a21><a11></a11><a5>0</a5><a12>true</a12><a14>false</a14><a56></a56><a13>Accept</a13><a15></a15><a67>325</a67><a68>false</a68></pfromdate><ptodate cat="params" ord="4"><a1>Task1</a1><a0>ptodate</a0><a2>To Date</a2><a4>Date/Time</a4><a9>false</a9><a6 sugg="false">m_fyenddate</a6><a10></a10><a21>false</a21><a11></a11><a5>0</a5><a12>true</a12><a14>false</a14><a56></a56><a13>Accept</a13><a15></a15><a67>325</a67><a68>false</a68></ptodate><paccountname cat="params" ord="5"><a1>Task1</a1><a0>paccountname</a0><a2>Account Name</a2><a4>Character</a4><a9>false</a9><a6 sugg="false"></a6><a10></a10><a21>true</a21><a11>select a.accountname 
