	</comps>
	<row1 cat="sql">
		<a1>Task1</a1>
		<a2>
			<l0>select i.itemcode, i.itemname, a.locationname, a.branchname,</l0>
			<l1>a.vouchertype,  </l1>
			<l2>a.docdate, </l2>
			<l3>a.docid,  </l3>
			<l4>''t''||case WHEN a.mapname IS NOT NULL THEN cast(regexp_replace(a.mapname, ''[0-9]+'', '''', ''g'') as text) ELSE ''stock'' end as transid,</l4>
			<l5>a.username, </l5>
			<l6>a.createdon,</l6>
			<l7>a.createdby,</l7>
			<l8>a.modifiedon,</l8>
			<l9>a.issued_qty as issued_qty, </l9>
			<l10>a.issued_value as issued_vlu,</l10>
			<l11>a.received_qty as received_qty,</l11>
			<l12>a.received_value received_vlu,</l12>
			<l13>a.received_qty + a.issued_qty as closing_qty,</l13>
			<l14>a.received_value + a.issued_value as closing_value,</l14>
			<l15>a.rate</l15>
			<l16>from</l16>
			<l17>( select a.itemid itemname, a.locationname, a.branchname, a.company, </l17>
			<l18>''Opening Balance'' vouchertype, </l18>
			<l19>cast( :pfromdate as date) AS docdate, </l19>
			<l20>''Opening Bal.'' AS docid, </l20>
			<l21>NULL AS mapname, </l21>
			<l22>NULL username, </l22>
			<l23>cast(null as date)  as createdon,cast(null as date) AS modifiedon,min(a.createdby) AS createdby,</l23>
			<l24>''p'' AS plusorminus,</l24>
			<l25>0 issued_qty, 0 AS issued_value, sum(a.received_qty + a.issued_qty) as received_qty,sum(a.received_value + a.issued_value) AS received_value, </l25>
			<l26>CASE WHEN sum(a.received_qty + a.issued_qty) &gt;  0 THEN sum(a.received_value + a.issued_value) / sum(a.received_qty + a.issued_qty) ELSE 0 END AS rate    </l26>
			<l27>from mv_stockdetails a</l27>
			<l28>where  a.cancel = ''F'' and a.docdate &lt; cast( :pfromdate as date)</l28>
			<l29>group by a.itemid, a.branchname, a.company,a.locationname</l29>
			<l30>union all</l30>
			<l31>select a.itemid itemname, a.locationname, a.branchname, a.company, </l31>
			<l32>a.vouchertype,  </l32>
			<l33>a.docdate, </l33>
			<l34>a.docid,</l34>
			<l35>a.mapname, </l35>
			<l36>a.username, </l36>
			<l37>a.createdon,a.modifiedon,a.createdby,</l37>
			<l38>a.plusorminus,</l38>
			<l39>a.issued_qty,</l39>
			<l40>a.issued_value,</l40>
			<l41>a.received_qty,</l41>
			<l42>a.received_value, </l42>
			<l43>a.rate </l43>
			<l44>from mv_stockdetails a</l44>
			<l45>where a.cancel = ''F'' and a.docdate between cast( :pfromdate as date)  and cast( :ptodate as date)</l45>
			<l46>) a, item i</l46>
			<l47>where a.itemname = i.itemid</l47>
			<l48>and i.itemid != 1</l48>
			<l49>and a.company = cast( :pcompanyid as numeric)</l49>
			<l50>and (a.branchname  = :pbranch or ''ALL'' = :pbranch )</l50>
			<l51>and (a.locationname  = :plocation or ''ALL'' = :plocation )</l51>
			<l52>and (i.itemdesc = :pitemdesc or :pitemdesc = ''ALL'')</l52>
			<l53>order by a.branchname, a.locationname, i.itemname, docdate, createdon nulls first</l53>
		</a2>
		<a3></a3>
		<a4>reportsql</a4>
	</row1>
