	</pcompanyid>
	<pbranch cat="params" ord="4">
		<a1>Task1</a1>
		<a0>pbranch</a0>
		<a2>Location/Branch</a2>
		<a4>Character</a4>
		<a9>false</a9>
		<a6 sugg="false">{ALL}</a6>
		<a10></a10>
		<a21>false</a21>
		<a11 pcount="1">select ''ALL'' as branchname from dual 
union all 
select distinct cast( b.branchname as varchar(100)) branchname from branch b,
(select b.axusersid, UNNEST(STRING_TO_ARRAY(b.axug_branch, '','')) as branchname from axusergrouping b ) c, axusers a
where b.branchname = c.branchname and a.axusersid = c.axusersid and b.companyname = :m_companyid
and a.username = :username
union 
select cast(b.branchname as varchar(100)) as branchname from branch b
where b.cancel = ''F'' and b.companyname = :m_companyid
and b.app_desc = 1 and b.active = ''T''
and ( upper( :usergroup) like ''%DEFAULT%'')  
order by branchname</a11>
		<a5>0</a5>
		<a12>true</a12>
		<a14>false</a14>
		<a56></a56>
		<a13>Select</a13>
		<a15>
			<s>plocation</s></a15>
		<a67>325</a67>
		<a68>false</a68>
	</pbranch>
	<plocation cat="params" ord="5">
		<a1>Task1</a1>
		<a0>plocation</a0>
		<a2>Sub Location</a2>
		<a4>Character</a4>
		<a9>false</a9>
		<a6 sugg="false">{ALL}</a6>
		<a10></a10>
		<a21>false</a21>
		<a11 pcount="2">select a.locationname as locationname from vw_userloactions a 
join branch b on a.branch = b.branchid
where a.username = :pusername
and (b.branchname = :pbranch or :pbranch = ''ALL'')
union
select ''ALL'' as locationname
order by  locationname
</a11>
		<a5>0</a5>
		<a12>true</a12>
		<a14>false</a14>
		<a56></a56>
		<a13>Select</a13>
		<a15></a15>
		<a67>325</a67>
