	<row1 cat="sql">
		<a1>Task1</a1>
		<a2>
			<l0>select </l0>
			<l1>b.branchname, </l1>
			<l2>b.accountname,</l2>
			<l3>b.voucher_date, </l3>
			<l4>func_returns_hyperlink( b.voucher_number,''formpage'',b.otransid,b.accountshdrid,''Finance Transaction'', b.voucher_number) as voucher_number,</l4>
			<l5>func_returns_hyperlink( b.voucher_number,''formpage'',b.transid,b.sourceid,''Source Data'', b.voucher_number) as sourcedata,</l5>
			<l6>sum(b.base_debit - b.base_credit)  as netamount,</l6>
			<l7>concat( a.dimensions,''^'', a.costcentrename) as pivot, </l7>
			<l8>sum(a.amount * b.txn_exrate) as costamount</l8>
			<l9>from costcentre_data a, mv_accountsdetails b,axpselectionc a2 </l9>
			<l10>where a.sourceid= b.accountsdtlid  </l10>
			<l11>and a.dimensions = a2.selection</l11>
			<l12>AND b.company = cast( :pcompany AS numeric )</l12>
			<l13>and b.voucher_date between :fdate and :tdate </l13>
			<l14>and (b.accountname = :paccountname or :paccountname = ''ALL'')</l14>
			<l15>group by b.branchname, </l15>
			<l16>b.accountname,</l16>
			<l17>a.dimensions,a.costcentrename, </l17>
			<l18>b.transid,</l18>
			<l19>b.otransid, </l19>
			<l20>b.accountshdrid, </l20>
			<l21>b.sourceid, </l21>
			<l22>b.voucher_date, </l22>
			<l23>b.voucher_number</l23>
			<l24>order by 1,2,3, pivot</l24>
		</a2>
		<a3></a3>
		<a4>reportsql</a4>
	</row1>
