	<row1 cat="sql">
		<a1>Task1</a1>
		<a2>
			<l0>select a.voucher_date, a.branchname, a.accountname, a.subledgername, sum(a.opening_balance) as opening_balance, </l0>
			<l1>sum(a.base_debit) as base_debit, sum(a.base_credit) as base_credit, sum(a.net) as net, </l1>
			<l2>cast( :pstartdate as date) as mstartdate,</l2>
			<l3>cast( :penddate as date) as menddate,</l3>
			<l4>cast( :pbranchname as varchar) as mbranchname,</l4>
			<l5>mg_accountid</l5>
			<l6>from (</l6>
			<l7>select a.voucher_date,</l7>
			<l8>a.branchname,</l8>
			<l9>a.accountname,</l9>
			<l10>a.subledgername,  </l10>
			<l11>0 opening_balance, </l11>
			<l12>a.base_debit, </l12>
			<l13>a.base_credit, </l13>
			<l14>a.base_debit - a.base_credit as net, </l14>
			<l15>a.mg_accountid </l15>
			<l16>from mv_accountsdetails a</l16>
			<l17>where a.voucher_date &gt;=  cast( :pstartdate as date) </l17>
			<l18>and a.voucher_date &lt;=  cast( :penddate as date)</l18>
			<l19>and (a.branchname = cast( :pbranchname as text) or  cast( :pbranchname as text)= ''ALL'')  </l19>
			<l20>and a.financial_year = cast( :pfinyear as text)</l20>
			<l21>and a.company = cast( :pcompanyid as numeric)  </l21>
			<l22>and (a.accountname = :pmaccountname or ''ALL'' = :pmaccountname)</l22>
			<l23>and ( a.subledgername = :psubledgername or :psubledgername = ''ALL'')</l23>
			<l24>union all</l24>
			<l25>select cast( :pstartdate as date) as voucher_date, </l25>
			<l26>cast( null as text) as branchname, </l26>
			<l27>a.accountname,</l27>
			<l28>cast( ''Opening Bal.'' as text) subledgername,  </l28>
			<l29>sum(a.base_debit - a.base_credit) as opening_balance, </l29>
			<l30>cast( 0 as numeric) as base_debit, </l30>
			<l31>cast( 0 as numeric)  as base_credit, </l31>
			<l32>0 as net, </l32>
			<l33>a.mg_accountid </l33>
			<l34>from mv_accountsdetails a</l34>
			<l35>where a.voucher_date &lt; cast( :pstartdate as date) </l35>
			<l36>and (a.branchname = cast( :pbranchname as text) or  cast( :pbranchname as text)= ''ALL'')  </l36>
			<l37>and a.company = cast( :pcompanyid as numeric)  </l37>
			<l38>and (a.accountname = :pmaccountname or ''ALL'' = :pmaccountname)</l38>
			<l39>and ( a.subledgername = :psubledgername or :psubledgername = ''ALL'')</l39>
			<l40>group by a.accountname, a.voucher_date, a.mg_accountid</l40>
			<l41> ) a</l41>
			<l42>group by a.accountname, a.voucher_date, a.branchname, a.accountname, a.subledgername, a.mg_accountid</l42>
			<l43>order by accountname,voucher_date</l43>
		</a2>
		<a3></a3>
		<a4>reportsql</a4>
	</row1>
