	<row1 cat="sql">
		<a1>Task1</a1>
		<a2>
			<l0>select a.accountname, a.acategory, c.currency, cast( coalesce(sum( b.native_debit - b.native_credit ),0) as numeric) as Balance </l0>
			<l1>from mg_account a left join mv_accountmonthlysummary b on a.mg_accountid = b.mg_accountid</l1>
			<l2>join currency c on a.acurrency = c.currencyid </l2>
			<l3>where a.acatcode in ( ''b'',''c'') and a.atype = ''Account'' </l3>
			<l4>and a.cancel= ''F'' and a.app_desc = 1 and a.company = cast( :m_companyid as numeric) </l4>
			<l5>group by a.accountname,a.acategory, c.currency</l5>
			<l6>order by a.acategory, 1</l6>
		</a2>
		<a3></a3>
		<a4>reportsql</a4>
	</row1>
