"true" footer="false" hint="Preview" down=""><icon><text>video_label</text><addClass>material-icons</addClass></icon></btn2><btn3 key="btn3" caption="Page Setup / Printer Setting" cat="btn" tlhw="7,1,20,20" parent="btnPanel" font="Tahoma,8,clWindowText,ffff" def="right" task="printersetting" action="" container="" sname="" flat="true" position="Left" visible="true" footer="false" hint="Page Setup / Printer Setting" down=""><icon><text>import_contacts</text><addClass>material-icons</addClass></icon></btn3><btn4 key="btn4" caption="View" cat="btn" tlhw="7,1,20,20" parent="btnPanel" font="Tahoma,8,clWindowText,ffff" def="right" task="view" action="" container="" sname="" flat="true" position="Left" visible="true" footer="false" hint="View" down=""><icon><text>remove_red_eye</text><addClass>material-icons</addClass></icon></btn4><btn5 key="btn5" caption="Find" cat="btn" tlhw="7,1,20,20" parent="btnPanel" font="Tahoma,8,clWindowText,ffff" def="right" task="find" action="" container="" sname="" flat="true" position="Left" visible="true" footer="false" hint="Find" down=""><icon><text>search</text><addClass>material-icons</addClass></icon></btn5><btn6 key="btn6" caption="Tasks" cat="btn" tlhw="7,1,20,20" parent="btnPanel" font="Tahoma,8,clWindowText,ffff" def="right" task="tasks" action="" container="" sname="" flat="true" position="Left" visible="true" footer="false" hint="Tasks" down="" folder="true"><icon><text>receipt</text><addClass>material-icons</addClass></icon></btn6><x__head caption="GSTR1 CDNR Report" cat="txt" parent="pnlButton" color="$00F2F0F0" align="none" def="left" tlhw="7,5,19,53" font="_Tahoma,,,clWindowText" type="pnl"/></comps><row1 cat="sql"><a1>Task1</a1><a2><l0>select a.gstregno,a.party_name,func_returns_hyperlink( a.returnid ,''formpage'',a.transid,a.headerid,t.caption,a.returnid)returnid,a.docdate,a.place_of_supply,</l0><l1>sum(a.net_amount)total_net_amount,sum(a.gross_afterdiscount)total_gross_amount,sum(a.sgstamount)total_sgstamount,sum(a.cgstamount)total_cgstamount,</l1><l2>sum(a.igstamount)total_igstamount,a.cess_amount,a.taxcategory,a.docid </l2><l3>from vw_salesgst_details a  </l3><l4>join tstructs t on t.name = a.transid</l4><l5>where a.gstregistered = ''T''</l5><l6>and a.company = :pcompany</l6><l7>and (a.branchname = :pbranch or :pbranch = ''ALL'')</l7><l8>and (a.docdate between :pfromdt and :ptodate)</l8><l9>and a.returnid is not null</l9><l10>group by a.gstregno,a.party_name,a.docid,a.docdate,</l10><l11>a.place_of_supply,a.cess_amount,a.taxcategory,a.transid,a.headerid,t.caption ,a.returnid </l11><l12>order by docdate ,docid</l12></a2><a3></a3><a4>reportsql</a4></row1><pcompany cat="params" ord="1"><a1>Task1</a1><a0>pcompany</a0><a2>Company</a2><a4>Numeric</a4><a9>false</a9><a6 sugg="false">m_companyid</a6><a10></a10><a21>true</a21><a11></a11><a5>0</a5><a12>true</a12><a14>false</a14><a56></a56><a13>Accept</a13><a15></a15><a67>325</a67><a68>false</a68></pcompany><pbranch cat="params" ord="2"><a1>Task1</a1><a0>pbranch</a0><a2>Branch</a2><a4>Character</a4><a9>false</a9><a6 sugg="false"></a6><a10></a10><a21>false</a21><a11 pcount="0">select a.branchname from vw_userbranchlocations a
where a.username = :username 
UNION
