('gstperce', 'GST Percentagewise Report', '<root pform="yes" name="gstperce" caption="GST Percentagewise Report" updatedon="23/06/2026 05:53:45" updatedby="admin" createdon="23/06/2026 5:53:45 AM" createdby="admin"><iview cat="iview" hideprojname="" hidereportdate="" parrange="1"><a0>gstperce</a0><a2>GST Percentagewise Report</a2><a3 ptable=""></a3><a4>0</a4><a5>true</a5><a6></a6><a7></a7><a8>0</a8><a9></a9><a10>false</a10><a11>true</a11><a12></a12><a13></a13><a14></a14><a15></a15><a16></a16><a17>Enabled</a17><a18>false</a18><a19>false</a19><a51></a51><a52></a52><a53></a53><a54></a54><a55>select row</a55><a57>false</a57><a63>true</a63><a64>false</a64><b9>gstperce</b9><b10></b10><b11></b11><b12></b12><b13></b13><b14></b14><b15></b15><b16></b16><b17></b17><b35>false</b35><b36>Center</b36><b37>Center</b37><a31></a31><a32>1</a32><a33>false</a33><a34>false</a34><a35>0</a35><a36></a36><a37></a37><a38></a38><a39>false</a39><a40>false</a40><a21>false</a21><a41>false</a41><a42>clskyblue</a42><a43>[Tahoma,9,clBlack,,True,False,False,False]</a43><a44>[Tahoma,8,clBlack,,True,False,False,False]</a44><a45>[Tahoma,8,clBlack,,True,False,False,False]</a45><a46>$00F3AFA0</a46><a47>[Tahoma,8,clBlack,,True,False,False,False]</a47><a48>$00EEF1F2</a48><a49>$00E2E8E9</a49><a50>18</a50><a60>1</a60><b18></b18><b21></b21><b23></b23><b22>0</b22><b38>Classic</b38><b39></b39><a65>false</a65><a66>false</a66></iview><comps cat="comps" dwbtb="true" LocalNum="9" btn="6" vupd="" pnlheight="35"><btn1 key="btn1" caption="Print" cat="btn" tlhw="7,1,20,20" parent="btnPanel" font="Tahoma,8,clWindowText,ffff" def="right" task="print" action="" container="" sname="" flat="true" position="Left" visible="true" footer="false" hint="Print" down=""/><btn2 key="btn2" caption="Preview" cat="btn" tlhw="7,1,20,20" parent="btnPanel" font="Tahoma,8,clWindowText,ffff" def="right" task="preview" action="" container="" sname="" flat="true" position="Left" visible="true" footer="false" hint="Preview" down=""/><btn3 key="btn3" caption="Page Setup / Printer Setting" cat="btn" tlhw="7,1,20,20" parent="btnPanel" font="Tahoma,8,clWindowText,ffff" def="right" task="printersetting" action="" container="" sname="" flat="true" position="Left" visible="true" footer="false" hint="Page Setup / Printer Setting" down=""/><btn4 key="btn4" caption="View" cat="btn" tlhw="7,1,20,20" parent="btnPanel" font="Tahoma,8,clWindowText,ffff" def="right" task="view" action="" container="" sname="" flat="true" position="Left" visible="true" footer="false" hint="View" down=""/><btn5 key="btn5" caption="Find" cat="btn" tlhw="7,1,20,20" parent="btnPanel" font="Tahoma,8,clWindowText,ffff" def="right" task="find" action="" container="" sname="" flat="true" position="Left" visible="true" footer="false" hint="Find" down=""/><btn6 key="btn6" caption="Tasks" cat="btn" tlhw="7,1,20,20" parent="btnPanel" font="Tahoma,8,clWindowText,ffff" def="right" task="tasks" action="" container="" sname="" flat="true" position="Left" visible="true" footer="false" hint="Tasks" down="" folder="true"/><x__head caption="GST Percentagewise Report" cat="txt" parent="pnlButton" color="$00F2F0F0" align="none" def="left" tlhw="7,5,19,53" font="_Tahoma,,,clWindowText" type="pnl"/></comps><row1 cat="sql"><a1>Task1</a1><a2><l0>select branchname,placeofsupply,taxper,</l0><l1>case when supplytype in ( ''Inter State'','''') then sum(taxableamount) end as igst,</l1><l2>case  when supplytype = ''Intra State'' then sum(taxableamount)/2 end as cgst,</l2><l3>case when supplytype = ''Intra State'' then sum(taxableamount)/2 end as sgst,</l3><l4>supplytype,sum(grossamount) as grossamount,sum(taxableamount) as taxableamount,sum(netamount) as netamount</l4><l5>from (</l5><l6>select ''t''||sh.transid as stransid,b.branchname ,sh.docid voucher_number, sh.docdate voucher_date,</l6><l7>case when sh.transid!= ''incdv''then sh.newcustomer else j.party_name end as newcustomer,</l7><l8>sh.supply_type supplytype,upper(trim(sh.state)) placeofsupply,sh2.itemname,i.itemdesc ,i.hsnno,sh.gstnumber gstno,sh2.taxcategory,sh2.taxper,</l8><l9>sh2.taxableamount  ,sh2.net_amount  grossamount,sh2.gross_afterdiscount netamount</l9><l10>from salesinvoice_header sh join salesinvoice_items  sh2 on sh.salesinvoice_headerid =sh2.salesinvoice_headerid </l10><l11>left join vw_item i on sh2.itemname =i.itemid join branch b on sh.branch =b.branchid</l11><l12>left join (select mp.party_name,sh.salesinvoice_headerid  from salesinvoice_header sh </l12><l13>left join mg_customer mp on sh.customer = mp.mg_customerid </l13><l14>where sh.transid =''incdv'') j on sh.salesinvoice_headerid = j.salesinvoice_headerid</l14><l15>where sh.cancel =''F'' and sh.app_desc = 1 </l15><l16>and sh.company = :company</l16><l17>and (b.branchname = :branch or ''ALL'' = :branch )</l17><l18>and sh.docdate between :fdate and :tdate</l18><l19>union all</l19><l20>select  ''t''||sh.transid as stransid,b.branchname ,sh.docid voucher_number, sh.docdate voucher_date,</l20><l21>sh.newcustomer ,</l21><l22>sh.supply_type supplytype,upper(trim(sh.state)) placeofsupply,0 itemname,''Shipping'' itemdesc,''NA'' hsnno,sh.gstnumber gstno,sh.taxper_shipping taxcat,</l22><l23>sh.shipping_taxrate taxper,shipping_taxamount   taxableamount, sh.shipping_netamount  grossamount,sh.shipping_charges netamount</l23><l24>from salesinvoice_header sh join branch b on sh.branch =b.branchid </l24><l25>where shipping_charges &lt;&gt;0 </l25><l26>and sh.cancel =''F'' and sh.app_desc = 1 </l26><l27>and sh.company = :company</l27><l28>and (b.branchname = :branch or ''ALL'' = :branch )</l28><l29>and sh.docdate between :fdate and :tdate</l29><l30>union all</l30><l31>select ''tinstk'' as stransid,d2.branchname branch,a.docid voucher_number,a.docdate voucher_date,</l31><l32>d2.branchname as newcustomer,</l32><l33>case when d2.state = d.state then ''Intra State'' else ''Inter State'' end as supplytype,upper(trim(d2.state)) placeofsupply,</l33><l34>i.itemid itemname,i.itemdesc,i.hsnno ,d2.tinno gstno,''NA'' taxcat,0 taxper,</l34><l35>0 taxableamount,b.issue_amount grossamount,b.issue_amount netamount</l35><l36>from stockissues_header a join stockissues_items b on a.stockissues_headerid =b.stockissues_headerid </l36><l37>join vw_item i on b.itemname =i.itemid join branch d on a.branch=d.branchid join branch d2 on a.tobranch = d2.branchid </l37><l38>where a.cancel =''F'' and a.app_desc = 1 </l38><l39>and a.company = :company</l39><l40>and (d.branchname = :branch or ''ALL'' = :branch )</l40><l41>and a.docdate between :fdate and :tdate</l41><l42>and a.issuetypecode =''5''</l42><l43>union all</l43><l44>select ''t''||a.transid as stransid,d.branchname branch,a.docid voucher_number,a.docdate vouche_date,</l44><l45>m.party_name as newcustomer,</l45><l46>a.supply_type supplytype,d.state state,i.itemid itemname,i.itemdesc ,i.hsnno,a.gstnumber gstno,b.taxcategory taxcat,b.taxper taxper,</l46><l47>-b.taxableamount taxableamount,-b.net_amount grossamount,-b.gross_amount netamount</l47><l48>from salesreturns_header a,salesreturns_items   b,branch d,vw_item i, mg_customer m</l48><l49>where a.salesreturns_headerid = b.salesreturns_headerid </l49><l50>and a.branch = d.branchid</l50><l51>and b.itemname =i.itemid </l51><l52>and m.mg_customerid = a.customer</l52><l53>and  a.cancel = ''F''</l53><l54>and a.app_desc = 1 </l54><l55>and a.company = :company</l55><l56>and (d.branchname = :branch or ''ALL'' = :branch )</l56><l57>and a.docdate between :fdate and :tdate</l57><l58>order by 2,3</l58><l59>) a</l59><l60>where (case when length(gstno) = ''15'' then ''Registered''   else ''UnRegistered'' end  = :gsttype or ''ALL''= :gsttype)</l60><l61>and (supplytype = :stype or ''ALL'' = :stype) </l61><l62>group by branchname,placeofsupply,supplytype,taxper</l62></a2><a3></a3><a4>reportsql</a4></row1><company cat="params" ord="1"><a1>Task1</a1><a0>company</a0><a2>company</a2><a4>Numeric</a4><a9>false</a9><a6 sugg="false">m_companyid</a6><a10></a10><a21>true</a21><a11></a11><a5>0</a5><a12>true</a12><a14>false</a14><a56></a56><a13>Accept</a13><a15></a15><a67>325</a67><a68>false</a68></company><branch cat="params" ord="2"><a1>Task1</a1><a0>branch</a0><a2>Branch</a2><a4>Character</a4><a9>false</a9><a6 sugg="false">m_branch</a6><a10></a10><a21>false</a21><a11 pcount="0">select a.branchname branchname
from vw_userbranchlocations a    
where a.username = :username 
