se" hint="Preview" down=""><icon><text>video_label</text><addClass>material-icons</addClass></icon></btn2><btn3 key="btn3" caption="Page Setup / Printer Setting" cat="btn" tlhw="7,1,20,20" parent="btnPanel" font="Tahoma,8,clWindowText,ffff" def="right" task="printersetting" action="" container="" sname="" flat="true" position="Left" visible="true" footer="false" hint="Page Setup / Printer Setting" down=""><icon><text>import_contacts</text><addClass>material-icons</addClass></icon></btn3><btn4 key="btn4" caption="View" cat="btn" tlhw="7,1,20,20" parent="btnPanel" font="Tahoma,8,clWindowText,ffff" def="right" task="view" action="" container="" sname="" flat="true" position="Left" visible="true" footer="false" hint="View" down=""><icon><text>remove_red_eye</text><addClass>material-icons</addClass></icon></btn4><btn5 key="btn5" caption="Find" cat="btn" tlhw="7,1,20,20" parent="btnPanel" font="Tahoma,8,clWindowText,ffff" def="right" task="find" action="" container="" sname="" flat="true" position="Left" visible="true" footer="false" hint="Find" down=""><icon><text>search</text><addClass>material-icons</addClass></icon></btn5><btn6 key="btn6" caption="Tasks" cat="btn" tlhw="7,1,20,20" parent="btnPanel" font="Tahoma,8,clWindowText,ffff" def="right" task="tasks" action="" container="" sname="" flat="true" position="Left" visible="true" footer="false" hint="Tasks" down="" folder="true"><icon><text>receipt</text><addClass>material-icons</addClass></icon></btn6><x__head caption="GSTR3B Report" cat="txt" parent="pnlButton" color="$00F2F0F0" align="none" def="left" tlhw="7,5,19,53" font="_Tahoma,,,clWindowText" type="pnl"/></comps><row1 cat="sql"><a1>Task1</a1><a2><l0>select ''1. Outward Supplies'' as caption,0 as amount,1 ord from dual</l0><l1>union</l1><l2>select ''- Taxable Supplies (Other than Exports)'' as caption, sum(a.gross_afterdiscount)amount,2 ord </l2><l3>from vw_salesgst_details a </l3><l4>where a.company = :pcompany</l4><l5>and (a.branchname = :pbranch or :pbranch = ''ALL'')</l5><l6>and (a.docdate between :pfromdt and :ptodate)</l6><l7>and a.gstregistered = ''T''</l7><l8>union</l8><l9>select ''- Inter-State Supplies (IGST)'' as caption, sum(a.igstamount)amount,3 ord </l9><l10>from vw_salesgst_details a </l10><l11>where a.company = :pcompany</l11><l12>and (a.branchname = :pbranch or :pbranch = ''ALL'')</l12><l13>and (a.docdate between :pfromdt and :ptodate)</l13><l14>and a.gstregistered = ''T''</l14><l15>union</l15><l16>select ''- Intra-State Supplies (CGST + SGST)'' as caption, (sum(a.cgstamount)+sum(a.sgstamount))amount,4 ord </l16><l17>from vw_salesgst_details a </l17><l18>where a.company = :pcompany</l18><l19>and (a.branchname = :pbranch or :pbranch = ''ALL'')</l19><l20>and (a.docdate between :pfromdt and :ptodate)</l20><l21>and a.gstregistered = ''T''</l21><l22>union</l22><l23>select ''2. ITC on Purchases (Eligible)'',0 as amount,5 ord from dual</l23><l24>union</l24><l25>select ''- IGST Credit'' as caption, sum(a.igstamount)amount,6 ord </l25><l26>from vw_purchasegst_details a </l26><l27>where a.company = :pcompany</l27><l28>and (a.branchname = :pbranch or :pbranch = ''ALL'')</l28><l29>and (a.docdate between :pfromdt and :ptodate)</l29><l30>and a.gstregistered = ''T''</l30><l31>union</l31><l32>select ''- CGST Credit'' as caption, sum(a.cgstamount)amount,7 ord </l32><l33>from vw_purchasegst_details a </l33><l34>where a.company = :pcompany</l34><l35>and (a.branchname = :pbranch or :pbranch = ''ALL'')</l35><l36>and (a.docdate between :pfromdt and :ptodate)</l36><l37>and a.gstregistered = ''T''</l37><l38>union</l38><l39>select ''- SGST Credit'' as caption, sum(a.sgstamount)amount, 8 as ord</l39><l40>from vw_purchasegst_details a </l40><l41>where a.company = :pcompany</l41><l42>and (a.branchname = :pbranch or :pbranch = ''ALL'')</l42><l43>and (a.docdate between :pfromdt and :ptodate)</l43><l44>and a.gstregistered = ''T''</l44><l45>order by ord</l45></a2><a3></a3><a4>reportsql</a4></row1><pcompany cat="params" ord="1"><a1>Task1</a1><a0>pcompany</a0><a2>Company</a2><a4>Numeric</a4><a9>false</a9><a6 sugg="false">m_companyid</a6><a10></a10><a21>true</a21><a11></a11><a5>0</a5><a12>true</a12><a14>false</a14><a56></a56><a13>Accept</a13><a15></a15><a67>325</a67><a68>false</a68></pcompany><pbranch cat="params" ord="2"><a1>Task1</a1><a0>pbranch</a0><a2>Branch</a2><a4>Character</a4><a9>false</a9><a6 sugg="false"></a6><a10></a10><a21>false</a21><a11 pcount="0">select a.branchname from vw_userbranchlocations a
where a.username = :username 
UNION
select ''ALL'' from dual
order  by 1</a11><a5>0</a5><a12>true</a12><a14>false</a14><a56></a56><a13>Select</a13><a15></a15><a67>325</a67><a68>false</a68></pbranch><pfromdt cat="params" ord="3"><a1>Task1</a1><a0>pfromdt</a0><a2>From Date</a2><a4>Date/Time</a4><a9>false</a9><a6 sugg="false">date()</a6><a10></a10><a21>false</a21><a11></a11><a5>0</a5><a12>true</a12><a14>false</a14><a56></a56><a13>Accept</a13><a15></a15><a67>325</a67><a68>false</a68></pfromdt><ptodate cat="params" ord="4"><a1>Task1</a1><a0>ptodate</a0><a2>To Date</a2><a4>Date/Time</a4><a9>false</a9><a6 sugg="false">date()</a6><a10></a10><a21>false</a21><a11></a11><a5>0</a5><a12>true</a12><a14>false</a14><a56></a56><a13>Accept</a13><a15></a15><a67>325</a67><a68>false</a68></ptodate><caption cat="querycol" encrypted="F" freezecol="F" negativenorep="" customdecimal="F"><a2>caption</a2><a3>Description</a3><a1>Task1</a1><a4>Character</a4><a5>0</a5><a6></a6><a7>false</a7><a8>true</a8><a21>false</a21><a13>false</a13><a10>false</a10><a11>false</a11><a12>Clwindow</a12><a9>[Arial,8,clBlack,,False,False,False,False]</a9><a14>Left</a14><a15>true</a15><a16>false</a16><a17>361</a17><a18></a18><a19>false</a19><a53></a53><a54></a54><a55></a55><a58></a58><a59></a59><a61>0</a61><a62></a62><a69 masking=""></a69></caption><amount cat="querycol" encrypted="F" freezecol="F" negativenorep="" customdecimal="F"><a2>amount</a2><a3>Value</a3><a1>Task1</a1><a4>Numeric</a4><a5>2</a5><a6></a6><a7>false</a7><a8>true</a8><a21>false</a21><a13>false</a13><a10>true</a10><a11>false</a11><a12>Clwindow</a12><a9>[Arial,8,clBlack,,False,False,False,False]</a9><a14>Right</a14><a15>true</a15><a16>true</a16><a17>152</a17><a18></a18><a19>false</a19><a53></a53><a54></a54><a55></a55><a58></a58><a59></a59><a61>0</a61><a62></a62><a69 masking=""></a69></amount><ord cat="querycol" encrypted="F" freezecol="F" negativenorep="" customdecimal="F"><a2>ord</a2><a3>ord</a3><a1>Task1</a1><a4>Numeric</a4><a5>0</a5><a6></a6><a7>false</a7><a8>true</a8><a21>true</a21><a13>false</a13><a10>fa