('gstrsale', 'GST Sales Report', '<root pform="yes" name="gstrsale" caption="GST Sales Report" updatedon="23/06/2026 05:53:45" updatedby="admin" createdon="23/06/2026 5:53:45 AM" createdby="admin"><iview cat="iview" hideprojname="" hidereportdate="" parrange="1"><a0>gstrsale</a0><a2>GST Sales Report</a2><a3 ptable=""></a3><a4>0</a4><a5>true</a5><a6></a6><a7></a7><a8>0</a8><a9></a9><a10>false</a10><a11>true</a11><a12></a12><a13></a13><a14></a14><a15></a15><a16></a16><a17>Enabled</a17><a18>false</a18><a19>false</a19><a51></a51><a52></a52><a53></a53><a54></a54><a55>select row</a55><a57>false</a57><a63>true</a63><a64>false</a64><b9>GST Sales Report</b9><b10></b10><b11></b11><b12></b12><b13></b13><b14></b14><b15></b15><b16></b16><b17></b17><b35>false</b35><b36>Center</b36><b37>Center</b37><a31></a31><a32>1</a32><a33>false</a33><a34>false</a34><a35>0</a35><a36></a36><a37></a37><a38></a38><a39>false</a39><a40>false</a40><a21>false</a21><a41>false</a41><a42>clskyblue</a42><a43>[Tahoma,9,clBlack,,True,False,False,False]</a43><a44>[Tahoma,8,clBlack,,True,False,False,False]</a44><a45>[Tahoma,8,clBlack,,True,False,False,False]</a45><a46>$00F3AFA0</a46><a47>[Tahoma,8,clBlack,,True,False,False,False]</a47><a48>$00EEF1F2</a48><a49>$00E2E8E9</a49><a50>18</a50><a60>1</a60><b18></b18><b21></b21><b23></b23><b22>0</b22><b38>Classic</b38><b39>None</b39><a65>false</a65><a66>false</a66></iview><comps cat="comps" dwbtb="true" LocalNum="9" btn="6" vupd="" pnlheight="35"><btn1 key="btn1" caption="Print" cat="btn" tlhw="7,1,20,20" parent="btnPanel" font="Tahoma,8,clWindowText,ffff" def="right" task="print" action="" container="" sname="" flat="true" position="Left" visible="true" footer="false" hint="Print" down=""/><btn2 key="btn2" caption="Preview" cat="btn" tlhw="7,1,20,20" parent="btnPanel" font="Tahoma,8,clWindowText,ffff" def="right" task="preview" action="" container="" sname="" flat="true" position="Left" visible="true" footer="false" hint="Preview" down=""/><btn3 key="btn3" caption="Page Setup / Printer Setting" cat="btn" tlhw="7,1,20,20" parent="btnPanel" font="Tahoma,8,clWindowText,ffff" def="right" task="printersetting" action="" container="" sname="" flat="true" position="Left" visible="true" footer="false" hint="Page Setup / Printer Setting" down=""/><btn4 key="btn4" caption="View" cat="btn" tlhw="7,1,20,20" parent="btnPanel" font="Tahoma,8,clWindowText,ffff" def="right" task="view" action="" container="" sname="" flat="true" position="Left" visible="true" footer="false" hint="View" down=""/><btn5 key="btn5" caption="Find" cat="btn" tlhw="7,1,20,20" parent="btnPanel" font="Tahoma,8,clWindowText,ffff" def="right" task="find" action="" container="" sname="" flat="true" position="Left" visible="true" footer="false" hint="Find" down=""/><btn6 key="btn6" caption="Tasks" cat="btn" tlhw="7,1,20,20" parent="btnPanel" font="Tahoma,8,clWindowText,ffff" def="right" task="tasks" action="" container="" sname="" flat="true" position="Left" visible="true" footer="false" hint="Tasks" down="" folder="true"/><x__head caption="GST Sales Report" cat="txt" parent="pnlButton" color="$00F2F0F0" align="none" def="left" tlhw="7,5,19,53" font="_Tahoma,,,clWindowText" type="pnl"/></comps><row1 cat="sql"><a1>Task1</a1><a2><l0>select stransid as ttransid,branchname,voucher_number,voucher_date,newcustomer,</l0><l1>case when length(gstno) &gt;=''15'' then gstno   else ''UnRegistered'' end as gstno  ,taxcat,</l1><l2>case when supplytype in ( ''Inter State'','''') then sum(taxableamount) end as igst,</l2><l3>case  when supplytype = ''Intra State'' then sum(taxableamount)/2 end as cgst,</l3><l4>case when supplytype = ''Intra State'' then sum(taxableamount)/2 end as sgst,</l4><l5>supplytype,sum(grossamount) as grossamount,sum(taxableamount) as taxableamount,sum(netamount) as netamount</l5><l6>from (</l6><l7>select ''t''||sh.transid as stransid,b.branchname ,sh.docid voucher_number, sh.docdate voucher_date,</l7><l8>case when sh.transid!= ''incdv''then sh.newcustomer else j.party_name end as newcustomer,</l8><l9>sh.supply_type supplytype,upper(trim(sh.state)) placeofsupply,sh2.itemname,i.itemdesc ,i.hsnno,sh.gstnumber gstno,sh2.taxcategory as taxcat,sh2.taxper,</l9><l10>sh2.taxableamount  ,sh2.net_amount  grossamount,sh2.gross_afterdiscount netamount</l10><l11>from salesinvoice_header sh join salesinvoice_items  sh2 on sh.salesinvoice_headerid =sh2.salesinvoice_headerid </l11><l12>left join vw_item i on sh2.itemname =i.itemid join branch b on sh.branch =b.branchid</l12><l13>left join (select mp.party_name,sh.salesinvoice_headerid  from salesinvoice_header sh </l13><l14>left join mg_customer mp on sh.customer = mp.mg_customerid </l14><l15>where sh.transid =''incdv'') j on sh.salesinvoice_headerid = j.salesinvoice_headerid</l15><l16>where sh.cancel =''F'' and sh.app_desc = 1 </l16><l17>and sh.company = :company</l17><l18>and (b.branchname = :branch or ''ALL'' = :branch )</l18><l19>and sh.docdate between :fdate and :tdate</l19><l20>union</l20><l21>select  ''t''||sh.transid as stransid,b.branchname ,sh.docid voucher_number, sh.docdate voucher_date,</l21><l22>sh.newcustomer ,</l22><l23>sh.supply_type supplytype,upper(trim(sh.state)) placeofsupply,0 itemname,''Shipping'' itemdesc,''NA'' hsnno,sh.gstnumber gstno,sh.taxper_shipping taxcat,</l23><l24>sh.shipping_taxrate taxrate,shipping_taxamount   taxableamount, sh.shipping_netamount  grossamount,sh.shipping_charges netamount</l24><l25>from salesinvoice_header sh join branch b on sh.branch =b.branchid </l25><l26>where shipping_charges &lt;&gt;0 </l26><l27>and sh.cancel =''F'' and sh.app_desc = 1 </l27><l28>and sh.company = :company</l28><l29>and (b.branchname = :branch or ''ALL'' = :branch )</l29><l30>and sh.docdate between :fdate and :tdate</l30><l31>union</l31><l32>select ''tinstk'' as stransid,d2.branchname branch,a.docid voucher_number,a.docdate voucher_date,</l32><l33>d2.branchname as newcustomer,</l33><l34>case when d2.state = d.state then ''Intra State'' else ''Inter State'' end as supplytype,upper(trim(d2.state)) placeofsupply,</l34><l35>i.itemid itemname,i.itemdesc,i.hsnno ,d2.tinno gstno,''NA'' as taxcat,0 taxrate,</l35><l36>0 taxableamount,(b.issue_qty * b.rate) grossamount,b.issue_amount netamount</l36><l37>from stockissues_header a join stockissues_items b on a.stockissues_headerid =b.stockissues_headerid </l37><l38>join vw_item i on b.itemname =i.itemid join branch d on a.branch=d.branchid join branch d2 on a.tobranch = d2.branchid </l38><l39>where a.cancel =''F'' and a.app_desc = 1 </l39><l40>and a.company = :company</l40><l41>and (d.branchname = :branch or ''ALL'' = :branch )</l41><l42>and a.docdate between :fdate and :tdate</l42><l43>and a.issuetypecode =''5''</l43><l44>union</l44><l45>select ''t''||a.transid as stransid,d.branchname branch,a.docid voucher_number,a.docdate vouche_date,</l45><l46>m.party_name as newcustomer,</l46><l47>a.supply_type supplytype,d.state state,i.itemid itemname,i.itemdesc ,i.hsnno,a.gstnumber gstno,b.taxcategory taxcat,b.taxper taxrate,</l47><l48>-b.taxableamount taxableamount,-b.net_amount grossamount,-b.gross_amount netamount</l48><l49>from salesreturns_header a, salesreturns_items   b,branch d,vw_item i, mg_customer m</l49><l50>where a.salesreturns_headerid = b.salesreturns_headerid </l50><l51>and a.branch = d.branchid</l51><l52>and b.itemname =i.itemid </l52><l53>and a.customer = m.mg_customerid</l53><l54>and  a.cancel = ''F''</l54><l55>and a.app_desc = 1 </l55><l56>and  a.company = :company</l56><l57>and (d.branchname = :branch or ''ALL'' = :branch )</l57><l58>and a.docdate between :fdate and :tdate) a</l58><l59>where (case when length(gstno) = ''15'' then ''Registered''   else ''UnRegistered'' end  = :gsttype or ''ALL''= :gsttype)</l59><l60>and (supplytype =:stype or ''ALL'' = :stype) </l60><l61>group by stransid ,branchname,voucher_number,voucher_date,gstno,supplytype,newcustomer,taxcat</l61><l62>order by 2,3</l62></a2><a3></a3><a4>reportsql</a4></row1><company cat="params" ord="1"><a1>Task1</a1><a0>company</a0><a2>company</a2><a4>Numeric</a4><a9>false</a9><a6 sugg="false">m_companyid</a6><a10></a10><a21>true</a21><a11></a11><a5>0</a5><a12>true</a12><a14>false</a14><a56></a56><a13>Accept</a13><a15></a15><a67>325</a67><a68>false</a68></company><branch cat="params" ord="2"><a1>Task1</a1><a0>branch</a0><a2>SBU/Branch</a2><a4>Character</a4><a9>false</a9><a6 sugg="false">m_branch</a6><a10></a10><a21>false</a21><a11 pcount="0">select a.branchname branchname
