('hsngst', 'HSN GST Sales Report', '<root pform="yes" name="hsngst" caption="HSN GST Sales Report" updatedon="23/06/2026 05:53:45" updatedby="admin" updusername="" dbtype="postgre" importedon="11/12/2024 16:08:57" importedby="admin" createdon="23/06/2026 5:53:45 AM" createdby="admin"><iview cat="iview" hideprojname="" hidereportdate="" parrange="1"><a0>hsngst</a0><a2>HSN GST Sales Report</a2><a3 ptable=""></a3><a4>0</a4><a5>true</a5><a6></a6><a7></a7><a8>0</a8><a9></a9><a10>false</a10><a11>true</a11><a12></a12><a13></a13><a14></a14><a15></a15><a16></a16><a17>Enabled</a17><a18>false</a18><a19>false</a19><a51></a51><a52></a52><a53></a53><a54></a54><a55>select row</a55><a57>false</a57><a63>false</a63><a64>false</a64><b9>hsngst</b9><b10></b10><b11></b11><b12></b12><b13></b13><b14></b14><b15></b15><b16></b16><b17></b17><b35>false</b35><b36>Center</b36><b37>Center</b37><a31></a31><a32>1</a32><a33>false</a33><a34>false</a34><a35>0</a35><a36></a36><a37></a37><a38></a38><a39>false</a39><a40>false</a40><a21>false</a21><a41>false</a41><a42>clskyblue</a42><a43>[Tahoma,9,clBlack,,True,False,False,False]</a43><a44>[Tahoma,8,clBlack,,True,False,False,False]</a44><a45>[Tahoma,8,clBlack,,True,False,False,False]</a45><a46>$00F3AFA0</a46><a47>[Tahoma,8,clBlack,,True,False,False,False]</a47><a48>$00EEF1F2</a48><a49>$00E2E8E9</a49><a50>18</a50><a60>1</a60><b18></b18><b21></b21><b23></b23><b22>0</b22><b38>Classic</b38><b39>None</b39><a65>false</a65><a66>false</a66></iview><comps cat="comps" dwbtb="true" LocalNum="9" btn="6" vupd="" pnlheight="35"><btn1 key="btn1" caption="Print" cat="btn" tlhw="7,1,20,20" parent="btnPanel" font="Tahoma,8,clWindowText,ffff" def="right" task="print" action="" container="" sname="" flat="true" position="Left" visible="true" footer="false" hint="Print" down=""><icon><text>list</text><addClass>material-icons</addClass></icon></btn1><btn2 key="btn2" caption="Preview" cat="btn" tlhw="7,1,20,20" parent="btnPanel" font="Tahoma,8,clWindowText,ffff" def="right" task="preview" action="" container="" sname="" flat="true" position="Left" visible="true" footer="false" hint="Preview" down=""><icon><text>video_label</text><addClass>material-icons</addClass></icon></btn2><btn3 key="btn3" caption="Page Setup / Printer Setting" cat="btn" tlhw="7,1,20,20" parent="btnPanel" font="Tahoma,8,clWindowText,ffff" def="right" task="printersetting" action="" container="" sname="" flat="true" position="Left" visible="true" footer="false" hint="Page Setup / Printer Setting" down=""><icon><text>import_contacts</text><addClass>material-icons</addClass></icon></btn3><btn4 key="btn4" caption="View" cat="btn" tlhw="7,1,20,20" parent="btnPanel" font="Tahoma,8,clWindowText,ffff" def="right" task="view" action="" container="" sname="" flat="true" position="Left" visible="true" footer="false" hint="View" down=""><icon><text>remove_red_eye</text><addClass>material-icons</addClass></icon></btn4><btn5 key="btn5" caption="Find" cat="btn" tlhw="7,1,20,20" parent="btnPanel" font="Tahoma,8,clWindowText,ffff" def="right" task="find" action="" container="" sname="" flat="true" position="Left" visible="true" footer="false" hint="Find" down=""><icon><text>search</text><addClass>material-icons</addClass></icon></btn5><btn6 key="btn6" caption="Tasks" cat="btn" tlhw="7,1,20,20" parent="btnPanel" font="Tahoma,8,clWindowText,ffff" def="right" task="tasks" action="" container="" sname="" flat="true" position="Left" visible="true" footer="false" hint="Tasks" down="" folder="true"><icon><text>receipt</text><addClass>material-icons</addClass></icon></btn6><x__head caption="HSN GST Sales Report" cat="txt" parent="pnlButton" color="$00F2F0F0" align="none" def="left" tlhw="7,5,19,53" font="_Tahoma,,,clWindowText" type="pnl"/></comps><row1 cat="sql"><a1>Task1</a1><a2><l0>select hsntax.hsnno,sum(hsntax.taxableamount) totaltax,sum(hsntax.igst) igst,sum(hsntax.cgst) cgst,sum(hsntax.sgst) sgst,sum(hsntax.gross_amount) gross_amount,</l0><l1>sum(hsntax.gross_amount)+ sum(hsntax.taxableamount) netamount from</l1><l2>(select x.hsnno, x.supply_type,x.taxableamount,x.gross_amount,</l2><l3>case when x.supply_type =''Inter State'' then x.taxableamount else 0 end igst,</l3><l4>case when x.supply_type =''Intra State'' then x.taxableamount/2 else 0 end cgst,</l4><l5>case when x.supply_type =''Intra State'' then x.taxableamount/2 else 0 end sgst</l5><l6> from </l6><l7>(select docid,vi.hsnno,sh.supply_type,case when sh.supply_type =''Export'' then 0 else si.taxableamount end taxableamount,</l7><l8>case when sh.supply_type =''Export'' then si.gross_amount else si.net_amount end gross_amount,sh.shipping_taxamount,sh.shipping_netamount from</l8><l9>salesinvoice_header sh  join salesinvoice_items si on sh.salesinvoice_headerid =si.salesinvoice_headerid </l9><l10> join vw_item vi on si.itemname =vi.itemid </l10><l11>union all</l11><l12>select  docid ,vi.hsnno,sh.supplytype,case when sh.supplytype =''Export'' then 0 else si.taxableamount end taxableamount,</l12><l13>case when sh.supplytype =''Export'' then si.issue_amount else si.gross_amount end gross_amount,0 shipping_taxamount,0 shipping_netamount from</l13><l14>stockissues_header sh  join stockissues_items si on sh.stockissues_headerid =si.stockissues_headerid </l14><l15> join vw_item vi on si.itemname =vi.itemid </l15><l16> where issuetypecode =''5''</l16><l17>union all</l17><l18>select sh2.docid,vi2.hsnno,sh2.supply_type,-case when sh2.supply_type =''Export'' then 0 else se.extaxableamount end taxableamount,</l18><l19>-case when sh2.supply_type =''Export'' then se.exgross_amount else se.exnet_amount  end gross_amount,0 shipping_taxamount,0 shipping_netamount</l19><l20>from salesreturns_header sh2 join sales_exchangeitems se on sh2.salesreturns_headerid =se.salesreturns_headerid </l20><l21>join vw_item vi2 on se.exitemname =vi2.itemid</l21><l22>order by docid)x join vw_gstoutputsalesrpt gst on x.docid = gst.voucher_number</l22><l23>where gst.company = :company and gst.branchname = :branch and</l23><l24> gst.voucher_date between :fdate and :todate)hsntax</l24><l25>group by hsntax.hsnno</l25></a2><a3></a3><a4>reportsql</a4></row1><company cat="params" ord="1"><a1>Task1</a1><a0>company</a0><a2>company</a2><a4>Numeric</a4><a9>false</a9><a6 sugg="false">m_companyid</a6><a10></a10><a21>true</a21><a11></a11><a5>0</a5><a12>true</a12><a14>false</a14><a56></a56><a13>Accept</a13><a15></a15><a67>325</a67><a68>false</a68></company><branch cat="params" ord="2"><a1>Task1</a1><a0>branch</a0><a2>Branch</a2><a4>Character</a4><a9>false</a9><a6 sugg="false">m_branch</a6><a10></a10><a21>false</a21><a11 pcount="0">select a.branchname branchname
from vw_userbranchlocations a    
where a.username = :username 
UNION
select ''ALL'' as branchname from dual
order by branchname</a11><a5>0</a5><a12>true</a12><a14>false</a14><a56></a56><a13>Select</a13><a15></a15><a67>325</a67><a68>false</a68></branch><fdate cat="params" ord="3"><a1>Task1</a1><a0>fdate</a0><a2>From</a2><a4>Date/Time</a4><a9>false</a9><a6 sugg="false">date()</a6><a10></a10><a21>false</a21><a11></a11><a5>0</a5><a12>true</a12><a14>false</a14><a56></a56><a13>Accept</a13><a15></a15><a67>325</a67><a68>false</a68></fdate><todate cat="params" ord="4"><a1>Task1</a1><a0>todate</a0><a2>To</a2><a4>Date/Time</a4><a9>false</a9><a6 sugg="false">date()</a6><a10></a10><a21>false</a21><a11></a11><a5>0</a5><a12>true</a12><a14>false</a14><a56></a56><a13>Accept</a13><a15></a15><a67>325</a67><a68>false</a68></todate><hsnno cat="querycol" encrypted="F" freezecol="F" negativenorep="" customdecimal="F"><a2>hsnno</a2><a3>HSN Number</a3><a1>Task1</a1><a4>Character</a4><a5>0</a5><a6></a6><a7>false</a7><a8>true</a8><a21>false</a21><a13>false</a13><a10>false</a10><a11>false</a11><a12>Clwindow</a12><a9>[Arial,8,clBlack,,False,False,False,False]</a9><a14>Left</a14><a15>true</a15><a16>false</a16><a17>126</a17><a18></a18><a19>false</a19><a53></a53><a54></a54><a55></a55><a58></a58><a59></a59><a61>0</a61><a62></a62><a69 masking=""></a69></hsnno><gross_amount cat="querycol" encrypted="F" freezecol="F" negativenorep="" customdecimal="F"><a2>gross_amount</a2><a3>Gross Amount</a3><a1>Task1</a1><a4>Numeric</a4><a5>2</a5><a6></a6><a7>false</a7><a8>true</a8><a21>false</a21><a13>false</a13><a10>true</a10><a11>false</a11><a12>Clwindow</a12><a9>[Arial,8,clBlack,,False,False,False,False]</a9><a14>Right</a14><a15>true</a15><a16>true</a16><a17>142</a17><a18></a18><a19>false</a19><a53></a53><a54></a54><a55></a55><a58></a58><a59></a59><a61>0</a61><a62></a62><a69 masking=""></a69></gross_amount><cgst cat="querycol" encrypted="F" freezecol="F" negativenorep="" customdecimal="F"><a2>cgst</a2><a3>CGST</a3><a1>Task1</a1><a4>Numeric</a4><a5>2</a5><a6></a6><a7>false</a7><a8>true</a8><a21>false</a21><a13>false</a13><a10>true</a10><a11>false</a11><a12>Clwindow</a12><a9>[Arial,8,clBlack,,False,False,False,False]</a9><a14>Right</a14><a15>true</a15><a16>true</a16><a17>138</a17><a18></a18><a19>false</a19><a53></a53><a54></a54><a55></a55><a58></a58><a59></a59><a61>0</a61><a62></a62><a69 masking=""></a69></cgst><igst cat="querycol" encrypted="F" freezecol="F" negativenorep="" customdecimal="F"><a2>igst</a2><a3>IGST</a3><a1>Task1</a1><a4>Numeric</a4><a5>2</a5><a6></a6><a7>false</a7><a8>true</a8><a21>false</a21><a13>false</a13><a10>true</a10><a11>false</a11><a12>Clwindow</a12><a9>[Arial,8,clBlack,,False,False,False,False]</a9><a14>Right</a14><a15>true</a15><a16>true</a16><a17>135</a17><a18></a18><a19>false</a19><a53></a53><a54></a54><a55></a55><a58></a58><a59></a59><a61>0</a61><a62></a62><a69 masking=""></a69></igst><sgst cat="querycol" encrypted="F" freezecol="F" negativenorep="" customdecimal="F"><a2>sgst</a2><a3>SGST</a3><a1>Task1</a1><a4>Numeric</a4><a5>2</a5><a6></a6><a7>false</a7><a8>true</a8><a21>false</a21><a13>false</a13><a10>true</a10><a11>false</a11><a12>Clwindow</a12><a9>[Arial,8,clBlack,,False,False,False,False]</a9><a14>Right</a14><a15>true</a15><a16>true</a16><a17>126</a17><a18></a18><a19>false</a19><a53></a53><a54></a54><a55></a55><a58></a58><a59></a59><a61>0</a61><a62></a62><a69 masking=""></a69></sgst><totaltax cat="querycol" encrypted="F" freezecol="F" negativenorep="" customdecimal="F"><a2>totaltax</a2><a3>Total Tax</a3><a1>Task1</a1><a4>Numeric</a4><a5>2</a5><a6></a6><a7>false</a7><a8>true</a8><a21>false</a21><a13>false</a13><a10>true</a10><a11>false</a11><a12>Clwindow</a12><a9>[Arial,8,clBlack,,False,False,False,False]</a9><a14>Right</a14><a15>true</a15><a16>true</a16><a17>136</a17><a18></a18><a19>false</a19><a53></a53><a54></a54><a55></a55><a58></a58><a59></a59><a61>0</a61><a62></a62><a69 masking=""></a69></totaltax><netamount cat="querycol" encrypted="F" freezecol="F" negativenorep="" customdecimal="F"><a2>netamount</a2><a3>Net Amount</a3><a1>Task1</a1><a4>Numeric</a4><a5>2</a5><a6></a6><a7>false</a7><a8>true</a8><a21>false</a21><a13>false</a13><a10>true</a10><a11>false</a11><a12>Clwindow</a12><a9>[Arial,8,clBlack,,False,False,False,False]</a9><a14>Right</a14><a15>true</a15><a16>true</a16><a17>161</a17><a18></a18><a19>false</a19><a53></a53><a54></a54><a55></a55><a58></a58><a59></a59><a61>0</a61><a62></a62><a69 masking=""></a69></netamount><hyperlinks cat="hyperlinks"/><temp><iviewcaption>HSN GST Sales Report</iviewcaption><menupos>Default</menupos><menupath></menupath><defpage>t</defpage><includepage>F</includepage></temp></root>
