('trialrep', 'GST pivot Report', '<root pform="yes" name="trialrep" caption="GST pivot Report" updatedon="23/06/2026 05:53:45" updatedby="admin" createdon="23/06/2026 5:53:45 AM" createdby="admin"><iview cat="iview" hideprojname="" hidereportdate="" parrange="1"><a0>trialrep</a0><a2>GST pivot Report</a2><a3 ptable=""></a3><a4>0</a4><a5>true</a5><a6></a6><a7></a7><a8>0</a8><a9></a9><a10>false</a10><a11>true</a11><a12></a12><a13></a13><a14></a14><a15></a15><a16></a16><a17>Enabled</a17><a18>false</a18><a19>false</a19><a51></a51><a52></a52><a53></a53><a54></a54><a55>select row</a55><a57>false</a57><a63>false</a63><a64>false</a64><b9>trialrep</b9><b10></b10><b11></b11><b12></b12><b13></b13><b14></b14><b15></b15><b16></b16><b17></b17><b35>false</b35><b36>Center</b36><b37>Center</b37><a31></a31><a32>1</a32><a33>false</a33><a34>false</a34><a35>0</a35><a36></a36><a37></a37><a38></a38><a39>false</a39><a40>false</a40><a21>false</a21><a41>false</a41><a42>clskyblue</a42><a43>[Tahoma,9,clBlack,,True,False,False,False]</a43><a44>[Tahoma,8,clBlack,,True,False,False,False]</a44><a45>[Tahoma,8,clBlack,,True,False,False,False]</a45><a46>$00F3AFA0</a46><a47>[Tahoma,8,clBlack,,True,False,False,False]</a47><a48>$00EEF1F2</a48><a49>$00E2E8E9</a49><a50>18</a50><a60>1</a60><b18></b18><b21></b21><b23></b23><b22>0</b22><b38>Classic</b38><b39></b39><a65>false</a65><a66>false</a66></iview><comps cat="comps" dwbtb="true" LocalNum="9" btn="6" vupd="" pnlheight="35"><btn1 key="btn1" caption="Print" cat="btn" tlhw="7,1,20,20" parent="btnPanel" font="Tahoma,8,clWindowText,ffff" def="right" task="print" action="" container="" sname="" flat="true" position="Left" visible="true" footer="false" hint="Print" down=""/><btn2 key="btn2" caption="Preview" cat="btn" tlhw="7,1,20,20" parent="btnPanel" font="Tahoma,8,clWindowText,ffff" def="right" task="preview" action="" container="" sname="" flat="true" position="Left" visible="true" footer="false" hint="Preview" down=""/><btn3 key="btn3" caption="Page Setup / Printer Setting" cat="btn" tlhw="7,1,20,20" parent="btnPanel" font="Tahoma,8,clWindowText,ffff" def="right" task="printersetting" action="" container="" sname="" flat="true" position="Left" visible="true" footer="false" hint="Page Setup / Printer Setting" down=""/><btn4 key="btn4" caption="View" cat="btn" tlhw="7,1,20,20" parent="btnPanel" font="Tahoma,8,clWindowText,ffff" def="right" task="view" action="" container="" sname="" flat="true" position="Left" visible="true" footer="false" hint="View" down=""/><btn5 key="btn5" caption="Find" cat="btn" tlhw="7,1,20,20" parent="btnPanel" font="Tahoma,8,clWindowText,ffff" def="right" task="find" action="" container="" sname="" flat="true" position="Left" visible="true" footer="false" hint="Find" down=""/><btn6 key="btn6" caption="Tasks" cat="btn" tlhw="7,1,20,20" parent="btnPanel" font="Tahoma,8,clWindowText,ffff" def="right" task="tasks" action="" container="" sname="" flat="true" position="Left" visible="true" footer="false" hint="Tasks" down="" folder="true"/><x__head caption="GST pivot Report" cat="txt" parent="pnlButton" color="$00F2F0F0" align="none" def="left" tlhw="7,5,19,53" font="_Tahoma,,,clWindowText" type="pnl"/></comps><row1 cat="sql"><a1>Task1</a1><a2><l0>select A.STATE,A.BRANCHNAME, A.SUPPLY_TYPE, A.SALESACCOUNT as pivot, SUM(A.TAXAMOUNT) as AMOUNT</l0><l1>from (</l1><l2>select a.branchname,  a.supply_type,x.state,   </l2><l3>coalesce(t.taxcode,''Sales'') as salesaccount,</l3><l4>-sum(a.base_debit - a.base_credit) as taxamount</l4><l5>from mv_accountsdetails a left join taxmaster t on a.accountname = t.accountname</l5><l6>left join(select docid,sh.state from salesinvoice_header sh  </l6><l7>union all</l7><l8>select  docid ,b.state from stockissues_header sh  join branch b on sh.tobranch = b.branchid</l8><l9> where issuetypecode =''5''</l9><l10>union all</l10><l11>select a.docid,b.dstate from salesreturns_header a left join so_portalhdr b on cast(a.order_referene as varchar)=b.order_number</l11><l12>order by docid) x on a.voucher_number = x.docid</l12><l13>where a.omapname in (''salco3'', ''salco4'', ''rtsal3'' ,''rtsal4'',''incdv0'',''instk4'',''salry7'',''salry8'',''salry9'')</l13><l14>and a.voucher_date between :fdate and :todate and (a.branchname = :branch  or :branch = ''ALL'' )</l14><l15>group by a.branchname , coalesce(t.taxcode,''Sales''), t.taxcode, a.alie, a.supply_type,x.state</l15><l16>) A</l16><l17>group by A.BRANCHNAME, A.SUPPLY_TYPE, A.SALESACCOUNT,A.state</l17><l18>order by 1, 2, 3</l18></a2><a3></a3><a4>reportsql</a4></row1><fdate cat="params" ord="1"><a1>Task1</a1><a0>fdate</a0><a2>From</a2><a4>Date/Time</a4><a9>false</a9><a6 sugg="false">date()</a6><a10></a10><a21>false</a21><a11></a11><a5>0</a5><a12>true</a12><a14>false</a14><a56></a56><a13>Accept</a13><a15></a15><a67>325</a67><a68>false</a68></fdate><todate cat="params" ord="2"><a1>Task1</a1><a0>todate</a0><a2>To</a2><a4>Date/Time</a4><a9>false</a9><a6 sugg="false">date()</a6><a10></a10><a21>false</a21><a11></a11><a5>0</a5><a12>true</a12><a14>false</a14><a56></a56><a13>Accept</a13><a15></a15><a67>325</a67><a68>false</a68></todate><branch cat="params" ord="3"><a1>Task1</a1><a0>branch</a0><a2>Branch</a2><a4>Character</a4><a9>false</a9><a6 sugg="false">m_branch</a6><a10></a10><a21>false</a21><a11 pcount="0">select a.branchname branchname
from vw_userbranchlocations a    
where a.username = :username 
