	<row1 cat="sql">
		<a1>Task1</a1>
		<a2>
			<l0>select a.purchase_bill_headerid as srecordid,''t''||a.transid as transid,c.tinno  as gstno,d.branchname,c.party_name,</l0>
			<l1>a.docid,a.docdate,a.refno as invoiceno,a.docdate as invoicedate,</l1>
			<l2>''&lt;span class="material-icons material-icons-style" style="color:#2b4da1"&gt;auto_stories&lt;/span&gt;'' as view_source,</l2>
			<l3>a.total_sgstamount as sgstamount,</l3>
			<l4>a.total_sgstamount as cgstamount,</l4>
			<l5>a.total_igstamount  as igstamount,</l5>
			<l6>0 as tdsamount,</l6>
			<l7>a.total_taxamount as taxamount , </l7>
			<l8>a.total_billvalue as netamount,</l8>
			<l9>a.total_itemvalue  as grossamount</l9>
			<l10>from purchase_bill_header a </l10>
			<l11> join branch d on a.branch = d.branchid </l11>
			<l12> join mg_supplier c</l12>
			<l13>on a.supplier = c.mg_supplierid</l13>
			<l14>where  a.company = cast( :pcompanyid as numeric)</l14>
			<l15>and a.docdate BETWEEN :fromdate and :todate</l15>
			<l16>and a.app_desc = 1</l16>
			<l17>and a.cancel = ''F''</l17>
			<l18>and length(c.tinno ) = ''15''</l18>
			<l19>and (d.branchname = :branch or ''ALL''=:branch)</l19>
			<l20>group by a.purchase_bill_headerid ,a.transid,c.tinno,d.branchname,c.party_name,a.docid,a.docdate,a.refno,a.docdate</l20>
			<l21>order by branchname,docdate,docid</l21>
		</a2>
		<a3></a3>
		<a4>reportsql</a4>
	</row1>
