	<row1 cat="sql">
		<a1>Task1</a1>
		<a2>
			<l0>select a.voucher_number,a.voucher_date ,a.supply_type,a.grossamount,coalesce (b.taxamt,0) totaltax,b.igst,b.sgst,b.cgst,</l0>
			<l1>a.grossamount + coalesce (b.taxamt,0) as netamount,a.branchname,''t''||a.transid transid</l1>
			<l2>from</l2>
			<l3>(select  a.voucher_number, a.vouchertype,  a.voucher_date, a.supply_type,-sum(a.base_debit - a.base_credit) as grossamount, a.branchname,a.transid</l3>
			<l4>from mv_accountsdetails a</l4>
			<l5>where   a.voucher_date between :fdate and :todate and (a.branchname = :branch  or :branch = ''ALL'' )</l5>
			<l6>and a.company = :company  and a.alie =''3'' and (a.supply_type = :stype or ''ALL'' = :stype )</l6>
			<l7> and (a.vouchertype = :vtype or ''ALL'' = :vtype)</l7>
			<l8>group by a.voucher_number, a.vouchertype,  a.voucher_date, a.supply_type, a.branchname,a.transid) a</l8>
			<l9>left join</l9>
			<l10>(</l10>
			<l11>select b.voucher_number, sum(b.taxamt) as taxamt, sum( b.igst ) as igst, sum(b.cgst) as cgst,</l11>
			<l12>sum(b.sgst) as sgst</l12>
			<l13>from (</l13>
			<l14>select  a.voucher_number, a.vouchertype,  a.voucher_date, a.supply_type,</l14>
			<l15>-(a.base_debit - a.base_credit) as taxamt, '' '' taxcode, 0 rate,</l15>
			<l16>case when a.accountname ilike ''%igst%'' then -(a.base_debit - a.base_credit)  else 0 end as igst,</l16>
			<l17>case when a.accountname ilike ''%cgst%''  then -(a.base_debit - a.base_credit)/2 else 0 end as cgst,</l17>
			<l18>case when a.accountname ilike ''%sgst%'' then -(a.base_debit - a.base_credit)/2 else 0 end as sgst,</l18>
			<l19>a.branchname</l19>
			<l20>from mv_accountsdetails a</l20>
			<l21>where a.accountname ilike ''%gst%''</l21>
			<l22>and a.voucher_date between :fdate and :todate and (a.branchname = :branch  or :branch = ''ALL'' )</l22>
			<l23>) b group by b.voucher_number</l23>
			<l24>) b</l24>
			<l25>on ( a.voucher_number = b.voucher_number )</l25>
			<l26>order by branchname, voucher_date</l26>
		</a2>
		<a3></a3>
		<a4>reportsql</a4>
	</row1>
