	<row1 cat="sql">
		<a1>Task1</a1>
		<a2>
			<l0>select func_returns_hyperlink( a.docid,''formpage'',a.transid,a.headerid,t.caption,a.docid)docid,a.docdate,a.place_of_supply,sum(a.net_amount)total_net_amount,</l0>
			<l1>sum(a.gross_afterdiscount)total_gross_amount,sum(a.igstamount)total_igstamount,a.cess_amount,a.taxcategory </l1>
			<l2>from vw_salesgst_details a</l2>
			<l3>join tstructs t on t.name = a.transid</l3>
			<l4>where a.gstenabled = ''T''</l4>
			<l5>and a.gstregistered = ''F''</l5>
			<l6>and a.supply_type = ''Inter State''</l6>
			<l7>and a.company = :pcompany</l7>
			<l8>and (a.branchname = :pbranch or :pbranch = ''ALL'')</l8>
			<l9>and (a.docdate between :pfromdt and :ptodate)</l9>
			<l10>group by a.docid,a.docdate,</l10>
			<l11>a.place_of_supply,a.cess_amount,a.taxcategory,a.transid,a.headerid,t.caption </l11>
			<l12>having sum(a.net_amount) &gt; 250000</l12>
			<l13>order by docdate ,docid   </l13>
		</a2>
		<a3></a3>
		<a4>reportsql</a4>
	</row1>
