	<row1 cat="sql">
		<a1>Task1</a1>
		<a2>
			<l0>select a.salesreturns_headerid as srecordid,''t''||a.transid as transid,a.returntype as returntype,</l0>
			<l1>a.customer  ||''-''||a.mobileno  as customer,</l1>
			<l2>to_char(a.docdate,''dd/mm/yyyy'') as docdate,a.docid,a.modeofpayment ||''-''||a.onaccountof as paymentdetails ,</l2>
			<l3>sum(b.net_amount) as grossamount,sum(b.discount) as discount,</l3>
			<l4>''&lt;span class="material-icons material-icons-style" style="color:#2b4da1"&gt;auto_stories&lt;/span&gt;'' as view_source,</l4>
			<l5>case when a.gstnumber !='''' then a.gstnumber else ''Unregistered'' end as gstnumber,</l5>
			<l6>(sum(b.gross_amount))  as netsales,</l6>
			<l7>case when a.supply_type = ''Inter State'' then (sum(b.taxableamount)) end as igstamount,</l7>
			<l8>case when a.supply_type = ''Intra State'' then (sum(b.taxableamount/2)) end as cgstamount,</l8>
			<l9>case when a.supply_type = ''Intra State'' then (sum(b.taxableamount/2)) end as sgstamount,</l9>
			<l10>(sum(b.taxableamount))  as taxamount,d.branchname as branchname,d.state </l10>
			<l11>from salesreturns_header a,salesreturns_items   b,branch d,</l11>
			<l12>(SELECT trim(column_value) as branch</l12>
			<l13>FROM unnest(string_to_array(replace(replace(:branch, CHR(13), ''''), CHR(10), ''''), ''~'')) AS column_value) e</l13>
			<l14>where a.salesreturns_headerid = b.salesreturns_headerid </l14>
			<l15>and a.returntype not in (''Exchange'',''Replacement'',''Return&amp;Exchange'')</l15>
			<l16>and a.branch = d.branchid</l16>
			<l17>and  a.cancel = ''F''</l17>
			<l18>and a.app_desc = 1 </l18>
			<l19>and a.company = cast( :pcompanyid as numeric) </l19>
			<l20>and (case when a.gstnumber !='''' then ''Registered'' else ''Unregistered'' end = cast( :gsttype as character varying) or ''ALL'' = cast( :gsttype as character varying))</l20>
			<l21>and a.docdate between :fromdate and :todate </l21>
			<l22>and (d.branchname = e.branch or ''ALL'' = e.branch) </l22>
			<l23>group by a.salesreturns_headerid,d.branchname,d.state</l23>
			<l24>order by a.docdate desc</l24>
		</a2>
		<a3></a3>
		<a4>reportsql</a4>
	</row1>
